window.__BOOK_o_pr_ncipe_nicolau_maquiavel = [{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p1_4.jpeg","page":1,"width":500,"height":751},{"type":"heading","lvl":1,"title":"Página de Título","id":"h_o_pr_ncipe_nicolau_maquiavel_0","page":2},{"type":"paragraph","text":"Nicolau Maquiavel","page":2},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p3_14.jpeg","page":3,"width":70,"height":104},{"type":"paragraph","text":"O PRÍNCIPE","page":3},{"type":"paragraph","text":"COMENTÁRIOS DE Napoleão I Cristina da Suécia","page":3},{"type":"paragraph","text":"TRADUÇÃO Fulvio Lubisco","page":3},{"type":"heading","lvl":1,"title":"Página de Direitos Autorais","id":"h_o_pr_ncipe_nicolau_maquiavel_1","page":4},{"type":"paragraph","text":"Título original: Il Principe Copyright © 2007 Jardim dos Livros","page":4},{"type":"paragraph","text":"2ª edição — Fevereiro de 2013","page":4},{"type":"paragraph","text":"Grafia atualizada segundo o Acordo Ortográfico da Língua Portuguesa de 1990, que entrou em vigor no Brasil em 2009","page":4},{"type":"paragraph","text":"EDITOR E PUBLISHER Luiz Fernando Emediato (licenciado)","page":4},{"type":"paragraph","text":"DIRETORA EDITORIAL","page":4},{"type":"paragraph","text":"Fernanda Emediato","page":4},{"type":"paragraph","text":"EDITOR Paulo Schmidt","page":4},{"type":"paragraph","text":"PRODUTORA EDITORIAL","page":4},{"type":"paragraph","text":"Erika Neves","page":4},{"type":"paragraph","text":"CAPA Alan Maia","page":4},{"type":"paragraph","text":"FOTO DA CAPA Estátua de Maquiavel na Galeria dos Ofícios, Florença, Itália","page":4},{"type":"paragraph","text":"PROJETO GRÁFICO E DIAGRAMAÇÃO","page":4},{"type":"paragraph","text":"Megaarte Design","page":4},{"type":"paragraph","text":"PREPARAÇÃO DE TEXTO","page":4},{"type":"paragraph","text":"Sandra Dolinsky","page":4},{"type":"paragraph","text":"REVISÃO Carmen Garcez","page":4},{"type":"paragraph","text":"CIP – BRASIL CATALOGAÇÃO NA FONTE (Sindicato Nacional dos Editores de Livros, RJ)","page":4},{"type":"paragraph","text":"Machiavelli, Niccolò, 1469-1527.","page":4},{"type":"paragraph","text":"O príncipe: comentários de Napoleão I e Cristina da Suécia / Nicolau Maquiavel ; tradução de Fulvio Lubisco – São Paulo :","page":4},{"type":"paragraph","text":"Jardim dos Livros, 2007","page":5},{"type":"paragraph","text":"ISBN 978-85-60018-08-6","page":5},{"type":"paragraph","text":"06-3201 CDD320","page":5},{"type":"paragraph","text":"CDU32","page":5},{"type":"paragraph","text":"Índices para catálogo sistemático: 1. Ciência política – obras anteriores a 1800. 2. Ética política – Obras anteriores a 1800. I. Título","page":5},{"type":"paragraph","text":"EMEDIATO EDITORES LTDA. Rua Major Quedinho, 111 – 20º andar","page":5},{"type":"paragraph","text":"CEP: 01050-904 – São Paulo – SP","page":5},{"type":"paragraph","text":"DEPARTAMENTO EDITORIAL E COMERCIAL","page":5},{"type":"paragraph","text":"Rua Gomes Freire, 225 – Lapa CEP: 05075-010 – São Paulo – SP","page":5},{"type":"paragraph","text":"Telefax: (+ 55 11) 3256-4444 E-mail: jardimdoslivros@geracaoeditorial.com.br www.geracaoeditorial.com.br","page":5},{"type":"paragraph","text":"twitter: @jardimdoslivros","page":5},{"type":"paragraph","text":"2013 Impresso no Brasil","page":5},{"type":"paragraph","text":"Printed in Brazil","page":5},{"type":"heading","lvl":1,"title":"Sumário","id":"h_o_pr_ncipe_nicolau_maquiavel_2","page":6},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p6_27.jpeg","page":6,"width":150,"height":43},{"type":"paragraph","text":"SUMÁRIO","page":6},{"type":"paragraph","text":"BIOGRAFIAS","page":6},{"type":"paragraph","text":"Maquiavel","page":6},{"type":"paragraph","text":"Napoleão I","page":6},{"type":"paragraph","text":"Cristina da Suécia","page":6},{"type":"paragraph","text":"O PRÍNCIPE","page":6},{"type":"paragraph","text":"Nicolau Maquiavel ao Magnífico Lourenço de Médici","page":6},{"type":"paragraph","text":"I Dos vários tipos de principados e por quais meios são adquiridos","page":6},{"type":"paragraph","text":"II Dos principados hereditários","page":6},{"type":"paragraph","text":"III Dos principados mistos","page":6},{"type":"paragraph","text":"IV Por qual motivo o reino de Dario, conquistado por","page":6},{"type":"paragraph","text":"Alexandre, não se revoltou contra os sucessores após a morte do conquistador","page":6},{"type":"paragraph","text":"V De que maneira devem ser governadas as cidades ou principados que, antes de conquistados, viviam pelas próprias leis","page":6},{"type":"paragraph","text":"VI Dos novos principados conquistados pelas próprias armas e pela virtude","page":6},{"type":"paragraph","text":"VII Dos novos principados que se conquistam pelas armas e sorte de outros","page":6},{"type":"paragraph","text":"VIII Dos que alcançaram o principado por meios criminosos","page":6},{"type":"paragraph","text":"IX Do principado civil","page":7},{"type":"paragraph","text":"X De como devem ser medidas as forças de todos os principados","page":7},{"type":"paragraph","text":"XI Dos principados eclesiásticos","page":7},{"type":"paragraph","text":"XII Dos vários tipos de milícias e dos soldados mercenários","page":7},{"type":"paragraph","text":"XIII Dos exércitos auxiliares, mistos e próprios","page":7},{"type":"paragraph","text":"XIV Das competências militares de um príncipe","page":7},{"type":"paragraph","text":"XV Das coisas pelas quais os homens, e especialmente os príncipes, são louvados ou vituperados","page":7},{"type":"paragraph","text":"XVI Da liberalidade e da parcimônia","page":7},{"type":"paragraph","text":"XVII Da crueldade e da clemência. É melhor ser amado ou temido?","page":7},{"type":"paragraph","text":"XVIII Da maneira pela qual os príncipes devem honrar a sua palavra","page":7},{"type":"paragraph","text":"XIX De que maneira é preciso evitar o desprezo e o ódio","page":7},{"type":"paragraph","text":"XX Se as fortalezas e muitas outras coisas que um príncipe realiza cotidianamente são úteis ou não","page":7},{"type":"paragraph","text":"XXI Como um príncipe deve se comportar para que seja apreciado","page":7},{"type":"paragraph","text":"XXII Dos ministros dos príncipes","page":7},{"type":"paragraph","text":"XXIII Como evitar os aduladores","page":7},{"type":"paragraph","text":"XXIV Por qual motivo os príncipes da Itália perderam seus","page":7},{"type":"paragraph","text":"Estados","page":7},{"type":"paragraph","text":"XXV De quanto a sorte influi nas coisas humanas e de como lhe opor resistência","page":7},{"type":"paragraph","text":"XXVI Exortação à tomada da Itália para libertá-la das mãos dos bárbaros","page":7},{"type":"paragraph","text":"CRONOLOGIA","page":8},{"type":"heading","lvl":1,"title":"BIOGRAFIAS","id":"h_o_pr_ncipe_nicolau_maquiavel_3","page":9},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p9_34.jpeg","page":9,"width":200,"height":235},{"type":"heading","lvl":2,"title":"Maquiavel","id":"h_o_pr_ncipe_nicolau_maquiavel_4","page":10},{"type":"paragraph","text":"MAQUIAVEL","page":10},{"type":"paragraph","text":"Niccolò Machiavelli nasceu em Florença, na parte central da Península Itálica, no dia 3 de maio de 1469, filho de Bernardo di Niccolò Machiavelli e de Bartolomea di Stefano Nelli, nobres florentinos. Cresceu e foi educado em ambiente culto e relativamente abastado. De 1478 a 1492, Florença foi governada por Lourenço de Médici, cognominado o Magnífico, importante poeta e patrono das artes do Renascimento italiano (a família Médici já governava Florença desde 1434).","page":10},{"type":"paragraph","text":"Pouco se sabe da vida de Maquiavel até 1498, quando foi nomeado segundochanceler da República Florentina. Nos anos que se seguiram, serviu em missões diplomáticas junto a várias cortes europeias, como a da França e do Sacro Império Romano-Germânico. Dentre essas missões, uma das mais importantes para o desenvolvimento do seu pensamento político foi a que desempenhou na Romanha junto a César Bórgia, filho do papa Alexandre VI.","page":10},{"type":"paragraph","text":"Em 1512, com o retorno dos Médicis ao poder em Florença, Maquiavel foi afastado devido à sua ligação com o governo republicano, sendo ainda preso e torturado sob acusação de envolvimento numa conspiração contra a poderosa família. Exilado, escreveu O príncipe, tratado em que analisa a natureza dos principados e seus governantes, pautando-se pelas questões práticas que envolvem a conquista e a manutenção do poder.","page":10},{"type":"paragraph","text":"Com essa obra, Maquiavel esperava granjear a simpatia dos Médici, dedicando-a a Lourenço II, duque de Urbino, conhecido como “Lorenzino”, sobrinho de Lourenço, o Magnífico. Na dedicatória Nicolau faz um pedido explícito de ajuda, ansioso que estava por voltar a Florença e à vida pública. No entanto, Lorenzino acolheu o livro com frieza, e nem mesmo a sua morte em 1519 melhorou a situação de Maquiavel. Somente algum tempo depois Maquiavel conseguiu cair nas graças da família, obtendo do cardeal Júlio de Médici (que depois se tornou papa Clemente VII) o encargo remunerado de escrever a história de Florença. Depois foi encarregado de inspecionar as fortificações da cidade e de negociar com o governo da Romanha, cujo vice-regente era o seu amigo e também historiador Francesco Guicciardini.","page":10},{"type":"paragraph","text":"Em 1527, de volta de uma viagem a Civitavecchia, Maquiavel adoeceu e morreu em Florença, no dia 22 de junho, algumas semanas depois de os Médicis terem sido novamente destituídos de sua hegemonia no poder.","page":11},{"type":"paragraph","text":"Após sua publicação, O príncipe imediatamente provocou controvérsias e, em 1559, foi incluído no Index librorum prohibitorum (índice dos livros proibidos) da Igreja Católica.","page":11},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p12_41.jpeg","page":12,"width":200,"height":235},{"type":"heading","lvl":2,"title":"Napoleão I","id":"h_o_pr_ncipe_nicolau_maquiavel_5","page":13},{"type":"paragraph","text":"NAPOLEÃO I","page":13},{"type":"paragraph","text":"Napoleão Bonaparte nasceu em Ajaccio, Córsega, a 15 de agosto de 1769, filho de Carlo Bonaparte, pequeno nobre corso que o enviou, ainda muito jovem, para estudar na França.","page":13},{"type":"paragraph","text":"Aos dezesseis anos, Napoleão formou-se na escola militar de Brienne. Entre 1785 e 1793, tentou iniciar carreira política na Córsega, mas se desentendeu com o líder patriota Pasquale Paoli, o que obrigou todo o clã Bonaparte a se refugiar na França, em 1793. Em junho desse ano, o agora capitão Bonaparte foi convocado para o exército da Itália, onde comandou a artilharia no cerco de Toulon. Sua habilidade tática possibilitou a tomada da cidade e expulsão dos britânicos, que a haviam ocupado.","page":13},{"type":"paragraph","text":"Partidário convicto da Revolução Francesa, Bonaparte chegou a ser preso com a queda de Robespierre e do partido jacobino, em 1794. No ano seguinte, Paul Barras, um dos líderes do Diretório, o novo governo controlado pelos moderados girondinos, soube das façanhas militares de Bonaparte em Toulon e lhe deu o comando das forças improvisadas em defesa do governo quando este foi atacado por uma insurreição de monarquistas. Bonaparte repeliu os agressores a canhonaços em 5 de outubro de 1795, ou 13 de Vindimiário do ano IV, segundo o calendário revolucionário francês então em uso.","page":13},{"type":"paragraph","text":"O jovem general tornou-se uma estrela em ascensão. Introduzido nos salões da capital, Bonaparte se apaixonou e desposou, em 1796, a viúva Josefina de Beauharnais. Logo em seguida foi comandar o exército francês na Itália, onde, demonstrando toda a extensão do seu gênio militar, revelou-se um dos maiores estrategistas de todos os tempos. Em 1798, liderou uma campanha no Egito e, no ano seguinte, com o auxílio de aliados poderosos, derrubou o corrupto e ineficaz Diretório, tomando o poder na França por meio de um golpe de Estado conhecido como 18 de Brumário. Teve início, então, a Era Napoleônica.","page":13},{"type":"paragraph","text":"Bonaparte tornou-se o primeiro-cônsul da República, e em quatro anos esse Consulado pacificou o país, restituiu a paz interna, reorganizou a administração, as finanças, a justiça e a Igreja, dando à França algumas de suas instituições mais duradouras, além de consolidar as conquistas da Revolução Francesa.","page":13},{"type":"paragraph","text":"A paz externa, no entanto, pouco durou. Atacada por toda a Europa monarquista desde a Revolução, a república francesa continuou a sofrer agressões contínuas sob Napoleão. A Inglaterra, que já havia financiado duas coalizões contra a França e pouco lucrava com a paz, violou o Tratado de Amiens, firmado em 1802, e apenas um ano depois, financiou a Terceira Coalizão contra a nação francesa.","page":14},{"type":"paragraph","text":"Com aprovação popular por meio de um plebiscito, Napoleão coroou imperador a si mesmo, com a bênção do papa, na catedral de Notre-Dame, em 2 de dezembro de 1804. Em 1805, teve a sua mais espetacular vitória na Batalha de Austerlitz, destruindo os exércitos da coligação formada pela Áustria, Rússia e Inglaterra. Em 1806-1807, o imperador destruiu a Quarta Coalizão, derrotando os exércitos da Prússia em Iena e os da Rússia em Eylau e Friedland. Unidas na Quinta Coalizão, Áustria e Inglaterra foram derrotadas de novo, dessa vez, em Wagram, no ano de 1809, por Napoleão I e seu Grande Exército. A cada vitória, o Império Francês expandia-se consideravelmente.","page":14},{"type":"paragraph","text":"Em 1810-1811, o domínio de Napoleão sobre a Europa continental era absoluto. Seus irmãos se tornaram reis da Espanha, de Nápoles, da Holanda, e seus marechais se tornaram condes e duques. Necessitado de um herdeiro para prosseguir a dinastia fundada por ele, o imperador se divorciou de Josefina, que não pudera dar-lhe filhos, e se casou com a arquiduquesa Maria Luísa, filha de Francisco I da Áustria. Um menino nasceu dessa união, o Rei de Roma. Napoleão então tomou a nefasta decisão de invadir a Rússia, que havia quebrado o Bloqueio Continental imposto pela França, no qual os países europeus eram proibidos de comerciar com a Inglaterra. Napoleão marchou sobre o império do czar Alexandre I à frente de mais de meio milhão de soldados, recrutados dos mais variados países da Europa. Dizimado pelo rigoroso inverno russo e pela fome, o outrora Grande Exército voltou reduzido a pouco mais de 100 mil homens. Enfraquecido na sua base de sustentação, que eram as suas forças armadas, o imperador acabou derrotado — na Batalha de Leipzig, 1813 — pela Sexta Coalizão, formada pelos mesmos adversários de sempre, incluindo a Suécia, aliada da França e cujo rei, Bernadotte, havia sido um dos marechais de Napoleão.","page":14},{"type":"paragraph","text":"Em 1814, Napoleão abdicou e foi exilado para a ilha de Elba, de onde escapou no início do ano seguinte e recuperou o poder na França, dando início ao período chamado Cem Dias de Napoleão. Uma Sétima Coalizão se formou contra ele, que foi ao encontro dos exércitos da Prússia e da Inglaterra na Bélgica, em junho de 1815, sofrendo a derrota final na Batalha de Waterloo, que pôs término ao império napoleônico.","page":15},{"type":"paragraph","text":"Os ingleses, a quem Napoleão se entregou, exilaramno na ilha de Santa Helena, um rochedo minúsculo no Atlântico Sul, a mais de 1.500 quilômetros do litoral africano. Importunado por enfermidades, pelo tédio e pelo governador inglês Hudson Lowe, um burocrata tacanho e mesquinho, o colosso destronado morreu em 5 de maio de 1821, de câncer estomacal, segundo uns, envenenado, segundo outros. Quase vinte anos após a sua morte, em 1840 Napoleão foi exumado e transportado para Paris, onde repousa no Palácio dos Inválidos como o maior herói da história da França.","page":15},{"type":"paragraph","text":"Os comentários de Napoleão nas notas de rodapé vieram a público pela primeira vez em 1816, numa edição feita em Paris pelo abade Silvestre Guillon, que as encontrou numa carruagem do imperador no dia 18 de junho de 1815, após Waterloo. Esses comentários dividem-se de acordo com o período da vida de Napoleão em que presumivelmente foram escritos: quando general, primeirocônsul, imperador e exilado na ilha de Elba. Tais épocas são indicadas entre parênteses em cada nota.","page":15},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p16_50.jpeg","page":16,"width":200,"height":235},{"type":"heading","lvl":2,"title":"Cristina da Suécia","id":"h_o_pr_ncipe_nicolau_maquiavel_6","page":17},{"type":"paragraph","text":"CRISTINA DA SUÉCIA","page":17},{"type":"paragraph","text":"Cristina Augusta Vasa foi rainha da Suécia de 1632 a 1654. Ela nasceu em 8 de dezembro de 1626, em Estocolmo, e morreu em 19 de abril de 1689, em Roma.","page":17},{"type":"paragraph","text":"Dotada de grande inteligência e cultura, foi uma das figuras mais influentes da política europeia do século XVII. Com a morte do pai, Gustavo Adolfo II, Cristina herdou o trono com apenas seis anos de idade e, após a regência de um conselho chefiado pelo estadista Axel Oxenstierna, assumiu o poder em 1644. Aprendeu matemática, filosofia, ciências, história, seis línguas, treinou montaria e manejava a espada tão bem quanto um soldado, além de gostar de se vestir com roupas masculinas e desafiar todas as convenções da sua época e do seu país.","page":17},{"type":"paragraph","text":"Mulher à frente do seu tempo e sempre ávida de saber, a rainha — apelidada de Minerva do Norte — protegeu as artes e atraiu para sua corte numerosos artistas e pensadores, como o filósofo Renée Descartes, seu correspondente de longa data, a quem convidou para lecionar e trabalhar na Suécia. Com ele passava madrugadas inteiras discutindo a natureza do amor — não o carnal, e sim o filosófico.","page":17},{"type":"paragraph","text":"Passado algum tempo, Cristina viu-se ameaçada por uma questão de grande importância íntima e política — a corte sueca a pressionava para que se casasse e gerasse um herdeiro, coisa à qual ela era totalmente avessa, como disse em sua autobiografia:","page":17},{"type":"paragraph","text":"Digo explicitamente que é impossível que eu me case. As razões eu não digo... meu temperamento é inimigo deste tipo de coisa (casamento), e não devo aceitá-lo nem que me torne governante do mundo. Que crime a mulher cometeu para que seja condenada a esta necessidade cruel, que consiste em ser trancafiada a vida toda como prisioneira ou escrava? É como digo: as freiras são prisioneiras e as mulheres casadas, escravas.","page":17},{"type":"paragraph","text":"Em 1654, após grave crise pessoal, converteu-se ao catolicismo — embora a religião do seu país fosse protestante — e abdicou em favor de seu primo Carlos Gustavo, coroado como Carlos X. Deixou então a Suécia e viajou pelos Países Baixos, Turquia, França e Itália, fixando-se em Roma.","page":18},{"type":"paragraph","text":"Em território italiano fez tudo de que realmente gostava. Fundou uma academia de ciências, patrocinou as artes, construiu a primeira ópera de Roma (onde abrigou o seu protegido Scarlatti), continuou os seus estudos filosóficos e começou a se interessar por astronomia e alquimia.","page":18},{"type":"paragraph","text":"Mas o sangue azul ainda fervia em suas veias e a rainha sem coroa, com fome de poder e saudades da política, tentou tomar Nápoles com a ajuda de um comparsa, o marquês Gian Rinaldo Monaldeschi. Seu objetivo era devolver a região ao papa e tornar-se governante dela em nome da Igreja. Mas o golpe fracassou e Cristina mandou executar Monaldeschi por suspeita de traição. Alguns especulam que ela teria pedido a cabeça do comparsa por ele ter ameaçado revelar a suposta homossexualidade de Cristina.","page":18},{"type":"paragraph","text":"Com a morte de Carlos X, Cristina tentou em vão recuperar o trono sueco. Então voltou definitivamente para Roma, onde morreu em 1689, sendo sepultada na basílica de São Pedro. Apesar dessa grande honra, Cristina teve alguns atritos com a Igreja, como na ocasião em que condenou, nos seus escritos, as perseguições aos judeus e aos huguenotes ou protestantes franceses. Embora sincera na sua devoção, a rainha nunca abandonou a sua vocação iluminista.","page":18},{"type":"paragraph","text":"A Descartes escreveu certa vez:","page":18},{"type":"paragraph","text":"Se nós concebermos o mundo na vasta extensão que você lhe dá, é impossível que o homem conserve dentro dele sua honorável posição. Ao contrário, ele deve considerar-se, juntamente com a terra que habita, apenas uma pequena parte, desproporcional ao enorme tamanho do resto. Ele provavelmente vai achar que as estrelas abrigam habitantes, ou até mesmo que os planetas ao redor delas estão todos repletos de criaturas mais inteligentes e melhores do que ele; ele vai deixar de achar que esta infinita extensão do mundo é feita para ele ou pode lhe ser de alguma serventia.","page":18},{"type":"heading","lvl":1,"title":"O PRÍNCIPE","id":"h_o_pr_ncipe_nicolau_maquiavel_7","page":20},{"type":"heading","lvl":2,"title":"Nicolau Maquiavel ao Magnífico Lourenço de Médici","id":"h_o_pr_ncipe_nicolau_maquiavel_8","page":20},{"type":"paragraph","text":"Nicolau Maquiavel ao Magnífico","page":20},{"type":"paragraph","text":"Lourenço de Médici","page":20},{"type":"paragraph","text":"Na maioria das vezes, os que desejam conseguir favores de um príncipe costumam a ele se apresentar com os bens que consideram mais caros e que ele mais aprecia. E é possível, então, vê-los frequentemente presentear o príncipe com cavalos, armas, tecidos trabalhados com ouro, pedras preciosas e adornos semelhantes, dignos de sua grandeza. Portanto, desejando oferecer a Vossa Magnificência algum testemunho de minha submissão, nada encontrei entre minhas posses que me fosse mais caro e estimado que o conhecimento das ações de grandes personagens, adquirido por meio de uma longa experiência das coisas modernas e de uma contínua lição das coisas antigas,1 as quais, diligente e longamente, perscrutei, examinei e ora resumi em um pequeno volume que envio a Vossa Magnificência.","page":20},{"type":"paragraph","text":"E, embora julgue esta obra indigna de vossa presença, confio que, por sua humanidade, ela será aceita, considerando o fato de que eu não poderia lhe oferecer um presente maior ao lhe proporcionar a condição de poder, e, em pouco tempo, compreender tudo o que eu conheci, em tantos anos, com dificuldades e perigos. Esta obra, eu não a enfeitei e nem tampouco a preenchi com cláusulas amplas e nem com palavras difíceis ou pomposas, ou com qualquer outro artifício ou ornamento extrínseco com os quais muitos costumam descrever e enfeitar as suas obras.2 Pois eu quis que nada a valorizasse senão o apreço da variedade da matéria e da gravidade do assunto.","page":20},{"type":"paragraph","text":"Tampouco desejo que seja reputada presunção o fato de um homem, de reles e humilde condição, ousar discutir e estabelecer regras para os governos de príncipes, porque, assim como os que desenham paisagens se posicionam num baixo plano para contemplar a natureza das montanhas3 e das altitudes, e se posicionam em lugares altos para contemplar as baixas planícies,4 assim também se faz necessário ser príncipe para conhecer bem a natureza dos povos; e para conhecer bem a natureza dos príncipes, faz-se necessário pertencer ao povo.5","page":20},{"type":"paragraph","text":"Receba, portanto, este pequeno donativo com o mesmo espírito com o qual o enviei, e se o ler e considerar diligentemente, nele encontrará o meu grande desejo de que Vossa Magnificência alcance a grandeza que a fortuna e as suas outras qualidades lhe prometem. E se Vossa Magnificência, do ápice de sua altura, voltar alguma vez o olhar para estes lugares inferiores, conhecerá o quanto eu, indignamente, suporto minha grande e contínua malignidade da sorte.","page":21},{"type":"heading","lvl":2,"title":"I Dos vários tipos de principados e por quais meios são adquiridos","id":"h_o_pr_ncipe_nicolau_maquiavel_9","page":22},{"type":"paragraph","text":"Dos vários tipos de principados e por quais meios são adquiridos","page":22},{"type":"paragraph","text":"Todos os Estados, todos os governos que tiveram ou têm domínio sobre os homens, foram e são repúblicas ou principados. Os principados são: hereditários, quando o sangue de seu senhor foi príncipe durante um longo tempo, ou novos. Os principados novos são totalmente novos,1 como Milão foi para Francisco Sforza, ou são como membros agregados ao Estado hereditário do príncipe que os conquista, como o reino de Nápoles é para o rei da Espanha. Esses domínios, assim adquiridos, estão acostumados a viver subordinados a um príncipe ou habituados a viver livres e são conquistados pelas armas de outros exércitos ou pelas próprias, pela sorte ou por virtude.","page":22},{"type":"heading","lvl":2,"title":"II Dos principados hereditários","id":"h_o_pr_ncipe_nicolau_maquiavel_10","page":23},{"type":"paragraph","text":"Dos principados hereditários","page":23},{"type":"paragraph","text":"Deixarei de me referir às repúblicas, pois já falei longamente a respeito em outra ocasião. Tratarei apenas dos principados;1 descreverei os princípios mencionados acima e apresentarei a forma pela qual esses principados podem ser governados e mantidos.","page":23},{"type":"paragraph","text":"Portanto, afirmo que nos Estados hereditários e subordinados ao sangue de seu príncipe, as dificuldades em mantê-los são bem menores que nos novos Estados,2 pois basta ao príncipe não ultrapassar os limites estabelecidos por seus antepassados para então temporizar com os acontecimentos;3 de maneira que, se esse príncipe for dotado de uma capacidade normal, saberá se manter no poder, a menos que uma força extraordinária e excessiva venha a destroná-lo.4 Mas, embora destituído e por mais temível que seja o usurpador, ele voltará a recuperá-lo.5","page":23},{"type":"paragraph","text":"Por exemplo, temos na Itália o duque de Ferrara, que, em 1484, resistiu aos ataques dos venezianos e, em 1510, aos do papa Júlio II, pelo único motivo de sua família já pertencer ao lugar havia muito tempo. Na realidade, um príncipe hereditário tem menos motivos e menos necessidade de ofender quem quer que seja, donde se conclui que seja mais amado, e no caso de que estranhos vícios não o façam ser odiado,6 é então razoável concluir, também, que ele seja naturalmente estimado e amado por seu povo.7 E na ancianidade e continuidade de um domínio apagam-se as memórias e as inovações, pois uma mudança sempre deixa uma base para a edificação de outra.8","page":23},{"type":"heading","lvl":2,"title":"III Dos principados mistos","id":"h_o_pr_ncipe_nicolau_maquiavel_11","page":24},{"type":"paragraph","text":"III","page":24},{"type":"paragraph","text":"Dos principados mistos","page":24},{"type":"paragraph","text":"Mas é no principado novo que incidem as dificuldades. Em primeiro lugar, se ele não for totalmente novo, mas agregado como membro de outro (que, no conjunto, pode ser chamado de quase misto1), suas variações nascem primeiro de uma dificuldade natural, inerente a todos os principados novos, ou seja, de que os homens preferiram mudar de senhor na esperança de que houvesse uma melhora2 e essa esperança faz que se armem contra o atual senhor; mas eles se enganam porque logo percebem, pela experiência, que as condições pioraram. Isso depende de outra necessidade comum e natural que faz com que o novo príncipe precise ofender seus súditos com a intervenção de seus soldados e outras infinitas injúrias, o que decorre como consequência da nova conquista.3","page":24},{"type":"paragraph","text":"De modo que o príncipe tornou inimigos todos aqueles que ele ofendera ao ocupar esse principado sem poder manter a amizade daqueles que ali o puseram, por não ter conseguido satisfazer o poder que almejavam, e por não poder usar contra os mesmos os métodos cujo reconhecimento o obriga a se abster;4 porque, qualquer que seja o poder que um príncipe tenha por meio de seu exército, ele sempre precisará do favor dos provinciais para entrar numa província.","page":24},{"type":"paragraph","text":"Eis por que Luís XII, rei da França, conquistou Milão para perdê-la logo em seguida;5 para tanto, bastaram inicialmente as forças de Ludovico, porque aqueles que lhe haviam aberto as portas, vendo-se enganados e frustrados em suas esperanças das vantagens que esperavam conseguir,6 não puderam suportar os incômodos causados pelo novo príncipe.","page":24},{"type":"paragraph","text":"É bem verdade que, ao reconquistar as regiões rebeldes, é mais difícil perdêlas novamente, porque o senhor, prevalecendo-se da derrota sofrida com a rebelião, torna-se mais rigoroso pelos meios que impõe para assegurar sua conquista, seja punindo os culpados, seja buscando os suspeitos, seja reforçando as partes deficientes de suas fortificações.7","page":24},{"type":"paragraph","text":"De maneira que, se para fazer a França perder Milão na primeira vez bastou que o duque Ludovico espalhasse um boato sobre as fronteiras, para fazer que perdesse Milão pela segunda vez foi necessário que todos se reunissem contra ela, que seus exércitos fossem totalmente dispersos e expulsos da Itália,8 o que ocorreu pelas razões acima mencionadas. Contudo, tanto na primeira como na segunda vez, Milão foi retomada da França.","page":25},{"type":"paragraph","text":"Os motivos da primeira retomada já foram expostos; resta, agora, saber sobre a segunda e ver quais meios Luís XII podia usar e quais haviam que aderissem aos seus termos para melhor se manter em suas novas conquistas.9 Portanto, digo que esses Estados que são conquistados e agregados a um Estado antigo são ou não da mesma província e da mesma língua, ou não são. Sendo do mesmo meio, é muito fácil mantê-los, principalmente por não estarem acostumados a viver livres,10 e para possuí-los com segurança basta extinguir a linhagem do príncipe que os dominava,11 porque, em outros aspectos, ao manter as velhas condições e não havendo deformidade de costumes, os homens continuam vivendo tranquilamente, tal como aconteceu na Borgonha, na Bretanha, na Gasconha e na Normandia, que tanto tempo foram da França,12 e apesar de algumas diferenças na língua, os costumes eram semelhantes e eles puderam facilmente conviver. E quem os conquistar e os quiser conservar, precisará adotar duas medidas: a primeira, a de extinguir a linhagem do antigo príncipe;13 a outra, a de não alterar suas leis ou seus impostos,14 de modo que em breve tempo tudo deverá se tornar um só corpo com o antigo principado.15","page":25},{"type":"paragraph","text":"Porém, ao conquistar territórios com idiomas, costumes e leis diferentes, é preciso ter sorte e habilidade para conservá-los.16 Um dos melhores e mais eficientes métodos seria o conquistador neles fixar residência. Isso tornaria mais segura e mais durável a sua posse, como fez o Turco com a Grécia, que, certamente, e apesar de todas as medidas implementadas, não a teria conseguido conservar se não houvesse nela fixado residência.17 Sua presença faz que o príncipe perceba as desordens assim que começam a nascer, tendo condições de reprimi-las imediatamente. Se estiver longe, virá a conhecê-las quando já cresceram demais, sem ter condições de remediá-las.","page":25},{"type":"paragraph","text":"Além disso, sua presença impede que seus oficiais saqueiem a província,18 o que permite aos súditos os recursos de se queixar ao príncipe, fazendo que seja amado19 caso queiram ser bons cidadãos, ou, caso contrário, que seja temido.20","page":25},{"type":"paragraph","text":"Em todos os casos, o forasteiro que quisesse assaltar esse Estado teria mais dificuldade para conquistá-lo tendo o príncipe presente no território. Outro melhor meio é o de estabelecer colônias em um ou dois lugares que sejam postos avançados ou, então, manter no Estado um forte e numeroso exército.21 Como o gasto com as colônias não é grande, o príncipe pode, com pouca despesa, controlá-las e mantê-las; ele apenas prejudica aqueles dos quais tira os campos para doálos aos novos habitantes que constituirão uma mínima parte desse Estado. Os que foram assim prejudicados, ficando dispersos e pobres, não poderão causar qualquer dano,22 enquanto os que não foram privados de suas terras permanecem à parte, inofensivos, temendo atrair a ira do conquistador.23","page":26},{"type":"paragraph","text":"Concluo acreditando que essas colônias de poucos gastos são mais fiéis e ofendem menos, e os ofendidos nada podem fazer havendo perdido tudo que tinham, e acabam se dispersando, como já foi mencionado, sem condições de criar dificuldades.24 Donde se chega à conclusão de que os homens devem ser aconchegados ou eliminados, pois podem se vingar de pequenas ofensas,25 mas não das graves, porque a ofensa causada a um homem deve ser feita de maneira a não temer a sua vingança.26","page":26},{"type":"paragraph","text":"Porém, se em vez de estabelecer colônias determina-se manter um forte contingente de tropas, a despesa correspondente cresce sem limite e todas as rendas do Estado são consumidas para a sua manutenção.27 E assim, a aquisição torna-se uma verdadeira perda28, o que ofende muito mais, pois prejudica todo o Estado com a mudança de alojamento de seu exército, causando um transtorno para todos e transformando os habitantes em inimigos, podendo causar danos ao príncipe, permanecendo abatidos, em suas próprias casas.29 De qualquer forma, essa garantia é tão inútil quanto aquela das colônias é útil.","page":26},{"type":"paragraph","text":"Quem estiver à frente de uma província diferente, conforme já foi mencionado, deve ainda tornar-se chefe e defensor dos vizinhos mais fracos e procurar enfraquecer os seus poderosos,30 e cuidar para que, porventura, nenhum forasteiro mais poderoso tente ali penetrar.31 E sempre intervirá aquele que for apoiado pelos insatisfeitos ou por demasiada ambição ou medo:32 foi assim que aconteceu com os romanos que foram introduzidos na Grécia pelos etólios e cuja entrada em todos os outros países lhes foi aberta pelos próprios habitantes.33 E, assim que um forasteiro poderoso entra numa província, todos os menos poderosos juntam-se a ele movidos pela inveja de quem lhes seja superior;34","page":26},{"type":"paragraph","text":"tanto é assim que, com respeito a esses menos poderosos, o intruso não terá dificuldade em angariá-los à sua causa, pois logo todos acabam formando um só bloco com o Estado que ele veio a conquistar.35 Ele só tem de cuidar para que não adquiram muito poder e autoridade36, podendo facilmente abater os que ainda são poderosos com suas próprias forças e com o apoio dos menos poderosos, a fim de tornar-se o senhor absoluto da província.37 Quem não souber administrar bem essa parte logo perderá o que estiver adquirindo.38 E, enquanto puder conservá-la, ele ainda terá grandes dificuldades e transtornos.39","page":27},{"type":"paragraph","text":"Nas províncias que conquistaram, os romanos observaram bem esses pontos: estabeleceram colônias, fizeram amizade com os menos poderosos e não deixaram que os poderosos forasteiros adquirissem reputação.40 Quero aqui deixar a província da Grécia como exemplo. Os romanos abordaram os aqueus e os etólios e expulsaram Antíoco.41 Mas, apesar dos méritos dos aqueus e dos etólios, os romanos não permitiram que seus Estados crescessem.42 Todos os pedidos de Filipe nunca conseguiram fazer que os romanos se tornassem seus amigos, sem que com isso ele perdesse qualquer coisa, e todo o poder de Antíoco nunca conseguiu levá-los a consentir que ele possuísse o menor Estado nessas regiões.43","page":27},{"type":"paragraph","text":"Nessas circunstâncias, os romanos fizeram o que todo príncipe inteligente deve fazer, ou seja, pensar não apenas nos problemas presentes, mas também naqueles que poderiam sobrevir, a fim de que os pudessem remediar por todos os meios que a prudência lhes indicasse.44 De fato, ao prevê-los com tempo suficiente, é possível facilmente remediá-los; mas, quando se espera que surjam, não há mais como remediar, pois o mal se tornou incurável. Então, ocorre como afirmam os médicos a respeito da tuberculose: no início, a doença é fácil de curar, embora difícil de conhecer. Porém, com a progressão do mal, ele é reconhecido facilmente, mas difícil de curar.45 É o que acontece com os assuntos de Estado porque, ao prever os problemas com antecedência — o que é possível somente àqueles que são dotados de prudência —, eles podem ser remediados a tempo,46 mas, quando não são previstos, crescem a ponto de, apesar de reconhecidos, não ser mais possível corrigi-los.47","page":27},{"type":"paragraph","text":"Portanto, prevendo com antecipação os eventuais inconvenientes, os romanos sempre conseguiam remediá-los sem dar-lhes tempo de crescer, a fim de evitar uma guerra. Eles sabiam que ela era inevitável e que, se fosse adiada, isso beneficiaria somente o inimigo.48 Foi por esse motivo que quiseram ir contra Filipe e Antíoco na própria Grécia, a fim de não ter de combatê-los na Itália, apesar de poder tê-la evitado se quisessem. Tampouco nunca gostaram do que diziam os sábios dos nossos dias, que “é melhor gozar do benefício do tempo”;49 mas preferiram o conselho de sua virtude e de sua prudência, pois o tempo leva adiante todas as coisas, podendo trazer consigo o bem como o mal, ou o mal como o bem.50","page":28},{"type":"paragraph","text":"Mas voltemos à França e analisemos se ela fez alguma das coisas que acabei de expor. E me referirei a Luís e não a Carlos, pois foi ele que por mais tempo manteve suas conquistas na Itália, onde melhor teve progresso: é possível ver como ele agiu ao contrário do que era necessário fazer para manter um Estado diferente.51","page":28},{"type":"paragraph","text":"O rei Luís foi introduzido na Itália pela ambição dos venezianos, que quiseram, por esse meio, conseguir para si mesmos metade do Estado da Lombardia.52 Não quero censurar o partido tomado pelo rei, que querendo ter um pé na Itália e não tendo amigos nessa província — ao contrário, teve todas as portas fechadas pelo comportamento do rei Carlos —, foi obrigado a fazer uso das amizades ao seu alcance,53 e o partido que ele tomou teria sido bemsucedido se não houvesse cometido nenhum erro. E assim, uma vez conquistada a Lombardia, Luís readquiriu a reputação que Carlos o fizera perder. Gênova cedeu; os florentinos tornaram-se seus amigos; o marquês de Mântua, o duque de Ferrara, Bentivoglio, a senhora de Forli, os senhores de Faenza, de Pesaro, de Rimini, de Camerino, de Piombino, os luqueses, os pisanos e os sienenses, todos foram ao seu encontro para se tornar amigos.54 Somente então os venezianos puderam considerar a temeridade do que haviam feito55 para conseguir a posse de duas cidades na Lombardia: fizeram que o rei se tornasse senhor de dois terços da Itália.56","page":28},{"type":"paragraph","text":"Considere-se, agora, com quão pouca dificuldade o rei poderia ter mantido a sua reputação na Itália caso tivesse observado as regras descritas acima e houvesse conseguido assegurar e defender todos esses amigos, que por serem numerosos, fracos e temerosos da Igreja57 ou dos venezianos, precisavam de apoio, sendo forçados a ser-lhe fiéis, e por meio dos quais poderia facilmente defender-se dos que ainda possuíam algum poder.58","page":28},{"type":"paragraph","text":"Mas assim que chegou a Milão, ele fez exatamente o contrário, ajudando o papa Alexandre a ocupar a Romanha. Ele nem percebeu que esse gesto o enfraqueceu, privando-o dos amigos que praticamente se jogaram em seus braços e fortalecendo a Igreja59 ao acrescentar-lhe poder espiritual e proporcionandolhe, ao mesmo tempo, autoridade e força temporal.60","page":29},{"type":"paragraph","text":"O primeiro erro levou-o a cometer outros, até que, para pôr um fim à ambição de Alexandre,61 que almejava se tornar senhor da Toscana, teve de ir pessoalmente à Itália.","page":29},{"type":"paragraph","text":"Mas o fato de ter fortalecido a Igreja e de ter perdido os amigos não foi suficiente, e ansioso por possuir o reino de Nápoles, decidiu dividi-lo com o rei da Espanha,62 de maneira que onde ele era o único árbitro da Itália, Luís acabou introduzindo um rival ao qual todos os ambiciosos e todos os insatisfeitos da província puderam recorrer; e quando poderia ter deixado no trono um rei que se considerasse honrado de lhe ser subordinado,63 ele o destronou para substituí-lo por outro rei que tinha todas as condições de derrubá-lo.64","page":29},{"type":"paragraph","text":"O desejo de conquistar é uma coisa muito natural e comum,65 e sempre que têm a possibilidade, os homens que o fazem são mais louvados que censurados. Mas quando não têm essa possibilidade e querem fazê-lo apesar de tudo, é quando erram e são censurados.66 Consequentemente, se a França possuía forças suficientes para atacar o reino de Nápoles, tinha de fazê-lo, e se não as possuía, então não o deveria ter repartido.67 E se a divisão da Lombardia com os venezianos veio a ser desculpada foi porque Luís deu à França o meio de pôr o pé na Itália; mas a divisão do reino de Nápoles, que não precisava ser dividido, merece censura.68","page":29},{"type":"paragraph","text":"Portanto, Luís cometeu cinco erros na Itália: arruinou os fracos;69 aumentou a força de um poderoso; introduziu um poderoso rei estrangeiro; nunca foi à Itália para ali fixar residência e nunca estabeleceu colônias.","page":29},{"type":"paragraph","text":"Entretanto, enquanto viveu, esses cinco erros poderiam não ter sido funestos se não cometesse um sexto, o de querer tomar os territórios dos venezianos.70 De fato, se não houvesse fortalecido a Igreja nem introduzido um forasteiro poderoso na Itália, eles deveriam ter sido enfraquecidos, mas nunca permitindo que fossem arruinados, pois, sendo poderosos, eles teriam impedido que os inimigos do rei atacassem a Lombardia, e isso porque os venezianos jamais consentiriam em sua ruína, a menos que eles mesmos se tornassem os senhores; além disso, ninguém se aventuraria a tirá-la da França para entregá-la aos venezianos, e, finalmente, seria perigoso demais combater os franceses e os venezianos ao mesmo tempo.71 Se alguém me dissesse que o rei Luís cedeu a Romanha a Alexandre e compartilhou o reino de Nápoles com a Espanha para evitar a guerra, eu responderia com o que já disse, que a desordem jamais deveria ser ignorada; pois a guerra não é evitada, é apenas adiada, contra o seu próprio interesse.72 E se outros alegassem que o rei dera ao papa a promessa de conquistar essa província em seu nome, a fim de obter a dissolução de seu casamento e o chapéu de cardeal ao arcebispo de Ruão, eu respondo com o que se dirá, mais adiante, a respeito da palavra dos príncipes e de como ela deve ser considerada.73","page":29},{"type":"paragraph","text":"Portanto, o rei Luís perdeu a Lombardia por não ter feito uso de nenhuma das regras empregadas por outros que conquistaram uma província e quiseram conservá-la. Não há nenhum milagre nisso. Trata-se de uma coisa simples e razoável. E sobre esse assunto falei em Nantes com o cardeal de Ruão, quando o Valentino (apelido de César Bórgia, filho do papa Alexandre VI) ocupava então a Romanha; pois, dizia-me o cardeal que os italianos nada entendiam de guerra, e eu respondi que os franceses nada entendiam de assuntos de Estado, e que, se entendessem, não teriam deixado a Igreja atingir tanta grandeza.74 E a experiência demonstrou que a grandeza da Igreja e da Espanha, na Itália, foi causada pela França, e, como consequência, a ruína desta última foi obra das duas,75 da Igreja e da Espanha. Donde se extrai uma regra geral que nunca ou raramente falha: aquele que permite a outro tornar-se poderoso está destinado à própria ruína,76 pois essa potência é conseguida por meio da esperteza ou da força, e esses dois meios são suspeitos para quem se tornou poderoso.77","page":30},{"type":"heading","lvl":2,"title":"IV Por qual motivo o reino de Dario, conquistado por Alexandre, não se revoltou contra os sucessores após a morte do conquistador","id":"h_o_pr_ncipe_nicolau_maquiavel_12","page":31},{"type":"paragraph","text":"Por qual motivo o reino de Dario, conquistado por Alexandre, não se revoltou contra os sucessores após a morte do conquistador1","page":31},{"type":"paragraph","text":"Ao considerar as dificuldades enfrentadas na preservação de um Estado recémconquistado, é possível maravilhar-se com a forma pela qual Alexandre Magno tornou-se senhor da Ásia em poucos anos,2 vindo a morrer logo após a sua ocupação. Seria razoável pensar que todo aquele Estado viesse a aproveitar-se da oportunidade para rebelar-se. No entanto, seus sucessores3 não tiveram outra dificuldade senão aquela que nasceu em seu meio pela própria ambição.4 Responderei que todos os principados que conhecemos e dos quais ainda permanece alguma memória são governados de duas maneiras diferentes: seja por um príncipe e todos os seus servos, os quais, por sua graça e concessão, ele tornou ministros a fim de ajudá-lo a governar o Estado; seja por um príncipe e barões, os quais, não por graça do senhor,5 mas pela ancianidade do sangue, atingiram esse grau. Esses barões possuem Estados e súditos próprios que os reconhecem como senhores e têm por eles um afeto natural.6","page":31},{"type":"paragraph","text":"Os Estados que são governados por um príncipe7 e seus servos consideramno com mais autoridade porque em toda a sua província ele é o único reconhecido como superior, e quando seus súditos obedecerem a outrem, eles o consideram apenas como seu ministro ou oficial e não lhe dedicam qualquer afeto pessoal.8","page":31},{"type":"paragraph","text":"Os exemplos desses dois tipos de governos são, em nossa época, a Turquia e a França. Toda a monarquia turca é governada por um senhor; os outros são seus servos. Ele divide seu reino em sandjaks ou divisões administrativas, para as quais envia os seus administradores, mudando e variando suas posições a seu próprio critério.9","page":31},{"type":"paragraph","text":"Na França, ao contrário, o rei encontra-se no seio de uma multidão de senhores de estirpe antiga, reconhecidos como tais e amados por seus súditos, e gozam de privilégios que o rei não lhes pode negar sem se colocar em perigo.10","page":32},{"type":"paragraph","text":"Se raciocinarmos sobre a natureza desses dois Estados, verificaremos a dificuldade de conquistar o império turco,11 mas, uma vez ocupado, haverá grande facilidade em conservá-lo.12 A dificuldade em ocupar a Turquia é o fato de não poder ser chamado pelos senhores desse império, nem tampouco esperar por uma rebelião daqueles que o cercam a fim de poder facilitar a empresa;13 é o que resulta pelos motivos citados. Pois, sendo todos escravos e subjugados, eles são mais difíceis de corromper, e mesmo que se conseguisse corrompê-los, seriam de muito pouca utilidade devido à falta de capacidade de levar o povo à rebelião,14 pelos motivos já mencionados. Portanto, quem estiver pensando em atacar os turcos pode ter certeza de que os encontrará unidos para enfrentá-lo; e deverá contar mais com as próprias forças que com a desordem dos outros.15","page":32},{"type":"paragraph","text":"Entretanto, uma vez vencido o monarca e derrotado em batalha de maneira que não possa reagrupar seus exércitos,16 a única coisa a temer é o sangue do príncipe, que uma vez extinto,17 nada mais há a temer, já que os demais não possuem crédito suficiente entre o povo. De maneira que, se antes da vitória não havia nada a esperar dos súditos, assim também depois dela nada haverá a temer por parte deles.18","page":32},{"type":"paragraph","text":"O contrário ocorre nos Estados governados como o da França.19 Pode ser fácil de entrar obtendo os favores de alguns senhores do reino, pois é sempre possível encontrar alguns insatisfeitos e os que desejam inovar.20 Pelos motivos já mencionados, eles podem efetivamente abrir os caminhos do reino e facilitar a vitória. Mas para mantê-lo haverá dificuldades,21 tanto por parte daqueles que ajudaram como daqueles que foram oprimidos.22 Tampouco será de ajuda extinguir o sangue do príncipe,23 pois sempre há os senhores que assumem a liderança de novas mudanças, e como o conquistador não consegue contentar a todos nem destruí-los,24 ele perderá sua conquista assim que a oportunidade se apresentar.25","page":32},{"type":"paragraph","text":"Ora, se considerarmos a natureza do governo de Dario, veremos que se assemelha ao reino turco.26 Entretanto, Alexandre precisou antes combater contra todas as suas forças e derrotá-lo em campanha. Depois da vitória, e com a morte de Dario, Alexandre conseguiu manter um Estado seguro pelos motivos que expus acima. E se os seus sucessores houvessem ficado unidos, poderiam ter gozado da mesma tranquila ociosidade, pois em todo o reino somente houve problemas que eles mesmos criaram.","page":33},{"type":"paragraph","text":"Por outro lado, os Estados governados, como os da França, é impossível conservá-los com tanta tranquilidade.27 Foi assim que nasceram as frequentes rebeliões da Espanha, da França e da Grécia contra os romanos. Essas rebeliões tiveram como causa principal os numerosos principados ali existentes,28 cuja memória, enquanto durou, sempre foi uma fonte de incertezas e de inquietudes para os romanos. Mas bastou apagar essa memória por meio do poder e do domínio do império para que os romanos se tornassem possuidores seguros.29","page":33},{"type":"paragraph","text":"Foi quando eles começaram a lutar entre si mesmos, cada um levando para si parte daquelas províncias, conforme a influência que nelas haviam conseguido, as quais, extinto o sangue dos antigos senhores, somente reconheciam a autoridade dos romanos.","page":33},{"type":"paragraph","text":"Portanto, considerando o todo, ninguém ficará surpreso com a facilidade com que Alexandre manteve sua conquista da Ásia,30 e com as dificuldades que outros tiveram para conservar o que conquistaram, tal como Pirro e muitos outros. Isso não depende de maior ou menor virtude do vencedor, mas das diferentes naturezas dos Estados conquistados.","page":33},{"type":"heading","lvl":2,"title":"V De que maneira devem ser governadas as cidades ou principados que, antes de conquistados, viviam pelas próprias leis","id":"h_o_pr_ncipe_nicolau_maquiavel_13","page":34},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p34_87.jpeg","page":34,"width":120,"height":34},{"type":"paragraph","text":"De que maneira devem ser governadas as cidades ou principados que, antes de conquistados, viviam","page":34},{"type":"paragraph","text":"pelas próprias leis","page":34},{"type":"paragraph","text":"Quando os Estados conquistados, conforme já mencionei, estão acostumados a viver por suas próprias leis e em liberdade, o conquistador pode conservá-los agindo de três formas: a primeira forma é destruindo-os;1 a segunda é residir neles pessoalmente, e a terceira é deixá-los viver sob suas leis,2 limitando-se a cobrar um tributo e estabelecendo um governo pouco numeroso que os mantenham amigáveis,3 pois o governo criado pelo conquistador sabe que não pode conservar o Estado sem sua amizade e poder. Aliás, uma cidade acostumada a viver livre é mais facilmente governada por seus próprios cidadãos que por outros.4","page":34},{"type":"paragraph","text":"Os espartanos e os romanos podem muito bem servir-nos de exemplo. Os espartanos mantiveram Atenas e Tebas criando um governo de poucas pessoas, mas voltaram a perdê-las. Por outro lado, para dominar as cidades de Cápua, Cartago e Numância, os romanos preferiram destruí-las a perdê-las. Na Grécia, quiseram seguir o exemplo dos espartanos, tornando-a livre e deixando que vivessem por suas próprias leis. Mas isso não deu certo e foram obrigados a destruir muitas cidades daquela província a fim de poder conservar o país. Pois é verdade! Não há meio mais seguro de possuir um Estado do que a sua destruição.5 E aquele que conquista uma cidade e a deixa viver livre, sem destruí-la, pode esperar por ela ser destruído, pois, acostumados a viver livres, os cidadãos sempre se apoiarão na rebelião em nome dessa mesma liberdade e de suas antigas leis, das quais nunca se esquecerão, nem pela passagem do tempo, nem tampouco pelos benefícios que viessem a receber. Não importa quanto se faça e se beneficie, se o Estado não for dissolvido e seus habitantes não forem dispersos, a lembrança das antigas instituições, jamais esquecidas, fará com que recorram a todos os tipos de tumultos, tal como fez Pisa ao quebrar as correntes da escravidão depois de cem anos de domínio florentino.6","page":34},{"type":"paragraph","text":"Contudo, quando as cidades ou as províncias estão acostumadas a ser governadas por um príncipe, uma vez extinta a sua dinastia, de um lado habituados à obediência e de outro não sabendo escolher um novo príncipe e sem liderança própria, pois não sabem viver livres,7 os habitantes dificilmente optam por tomar as armas; de maneira que o conquistador pode, sem dificuldade, atraí-los a seu favor e assegurar o seu domínio.8 Nas repúblicas, ao contrário, existe um princípio de vida mais arraigado, um ódio mais profundo e um maior desejo de vingança que não deixam nem podem deixar em esquecimento a antiga liberdade,9 portanto resta apenas ao conquistador optar pela destruição10 desses Estados ou passar a residir neles.","page":35},{"type":"heading","lvl":2,"title":"VI Dos novos principados conquistados pelas próprias armas e pela virtude","id":"h_o_pr_ncipe_nicolau_maquiavel_14","page":36},{"type":"paragraph","text":"Dos novos principados conquistados pelas próprias armas e pela virtude","page":36},{"type":"paragraph","text":"Que ninguém se surpreenda se, ao falar dos principados totalmente novos, de príncipes e de Estado, eu vier a apresentar grandes exemplos, porque os homens trilham sempre os mesmos caminhos trilhados por outros, agindo por imitação; mas é impossível seguir à risca os caminhos daqueles que os precederam ou equiparar a virtude daqueles que se procura imitar.1 Um homem prudente deve empreender sempre os caminhos trilhados por grandes homens e tomar por modelo os que foram excelentes, a fim de que, mesmo que não consiga alcançar as mesmas virtudes e glória, possa, ao menos, reproduzir seus princípios.2 Ele deve agir como os arqueiros prudentes, que ao determinar que o alvo proposto esteja além da capacidade de seus arcos, levantam a mira, não para alcançar altura,3 mas para que suas flechas cheguem ao ponto que desejam atingir.4","page":36},{"type":"paragraph","text":"Portanto, digo que no principado totalmente novo, onde há um novo príncipe, encontra-se maior ou menor dificuldade para mantê-lo, dependendo da maior ou menor habilidade de quem o conquiste.5","page":36},{"type":"paragraph","text":"O fato de tornar-se príncipe pressupõe habilidade ou sorte,6 e quer seja uma ou outra, sempre haverá muitas dificuldades. Aquele que conta menos com a sorte terá mais sucesso em seu empreendimento.7 Mais facilidade ainda terá o príncipe que, por não possuir outros Estados, seja forçado a ali estabelecer sua própria residência.8 De qualquer forma devo dizer que, dentre os que conseguiram ser príncipes9 por virtude própria e não por sorte, os mais notáveis são Moisés, Ciro, Rômulo, Teseu e outros semelhantes a eles.","page":36},{"type":"paragraph","text":"Embora não se deva discutir sobre Moisés, pois ele foi um mero executor da palavra de Deus,10 é preciso admirá-lo senão pela única graça que o tornava digno de falar com Deus.","page":36},{"type":"paragraph","text":"Mas, se considerarmos as ações e a conduta de Ciro e dos outros conquistadores e fundadores de reinos, eles todos serão admirados11 de igual forma e encontraremos uma grande semelhança entre eles e Moisés, apesar de este último ter sido dirigido por um mestre tão especial.12 E, ao analisarmos suas ações e vidas, verificaremos que da sorte apenas tiveram a oportunidade que lhes proporcionou matéria à qual puderam dar a forma que julgaram conveniente.13","page":37},{"type":"paragraph","text":"Sem essa oportunidade, as qualidades de suas almas seriam inúteis.14 Por outro lado, sem essas qualidades, a oportunidade teria aparecido em vão. Portanto, era necessário que Moisés encontrasse o povo de Israel escravizado e oprimido no Egito para que o desejo de sair da escravidão15 os animasse a segui-lo. Foi preciso que Rômulo não nascesse em Alba, mas em Roma, e que quisesse tornarse rei e fundador dessa pátria.16 Também foi preciso que Ciro encontrasse os persas descontentes com o domínio dos medos, que se tornaram amolecidos e efeminados pelo longo período de paz.17 Teseu não poderia ter demonstrado sua virtude se não houvesse encontrado os atenienses dispersos.18","page":37},{"type":"paragraph","text":"Consequentemente, essas oportunidades fizeram a felicidade desses homens e suas grandes qualidades fizeram que as oportunidades fossem conhecidas, proporcionando glória e nobreza a suas pátrias.19","page":37},{"type":"paragraph","text":"Os homens que por suas virtudes, semelhantes às virtudes desses famosos personagens, conquistarem o principado com dificuldades, com facilidade o conservarão. Porém, as dificuldades aparecerão, em parte, com as novas instituições e os novos sistemas que serão obrigados a introduzir a fim de estabelecer seu governo para sua própria segurança.20 E é preciso considerar que não há nada mais difícil de dirigir, mais dúbio de sucesso e mais perigoso de manejar que a introdução das novas ordens.21 Pois essa introdução tem por inimigos todos aqueles que se beneficiavam das instituições antigas,22 e fracos defensores23 há naqueles para quem as novas ordens seriam úteis.24 Essa fraqueza nasce, em parte, do medo dos adversários que têm a seu favor as leis existentes, e por outra parte, da descrença própria dos homens que somente passam a acreditar em tudo que é novo depois de ser convencidos pela experiência.25","page":37},{"type":"paragraph","text":"Daí decorre que os inimigos aproveitarão qualquer oportunidade para atacar com todo o calor do espírito do partido, enquanto os outros se defenderão com frieza, de maneira que, aliados a eles, corre-se sério perigo.26 Portanto, para uma melhor compreensão desta parte, é preciso analisar se esses inovadores são autossuficientes ou se dependem de outros, ou seja, se para levar adiante sua empresa eles precisam pedir ajuda ou se possuem o poder de impor.27","page":37},{"type":"paragraph","text":"Na primeira hipótese, eles sempre acabam mal e não levam a nada;28 mas quando são autossuficientes e podem impor, dificilmente correm perigo. Daí resulta que todos os profetas armados venceram29 e os desarmados pereceram.30","page":38},{"type":"paragraph","text":"Pois, além do que foi dito, é preciso acrescentar que a natureza dos povos não é constante e é fácil persuadi-los de alguma coisa, mas é difícil firmá-los nessa persuasão.31 Portanto, é preciso estar preparado para que, quando deixarem de acreditar, seja possível fazê-los acreditar pela força.32","page":38},{"type":"paragraph","text":"Caso estivessem desarmados,33 Moisés, Ciro, Teseu e Rômulo não teriam conseguido impor por muito tempo suas constituições; tal como ocorreu, em nossa época, ao frei Girolamo Savonarola, cujas reformas fracassaram a partir do momento em que um grande número de pessoas passou a desacreditá-lo sem que ele possuísse meios para firmar os que ainda acreditavam nem tampouco fazer com que os descrentes passassem a acreditar.","page":38},{"type":"paragraph","text":"Contudo, os grandes homens aos quais nos referimos têm grandes dificuldades e os perigos se encontram em seu próprio caminho. Convém que esses perigos sejam superados com virtude, 34 e uma vez superados, comecem a ser venerados, pois havendo eliminado aqueles que tinham inveja de suas qualidades, permanecem poderosos, seguros, honrados e felizes.35","page":38},{"type":"paragraph","text":"A esses grandes exemplos quero acrescentar outro menor, mas nem por isso desproporcional aos anteriores. Quero que ele seja suficiente para todos os semelhantes. Refiro-me a Hierão de Siracusa,36 que de particular tornou-se príncipe sem nada dever à sorte e apenas soube aproveitar-se das oportunidades.37 Aconteceu que os siracusanos oprimidos o elegeram capitão, e por meio de seus serviços mereceu que o tornassem seu príncipe.38 Ele foi de tanta virtude, até mesmo em sua vida privada, que assim escreveram a seu respeito: “Para reinar bem só lhe faltava um reino”.39 Além disso, eliminou a velha milícia para estabelecer uma nova,40 e abandonou as velhas alianças para fazer outras. E então, com amigos e soldados de sua confiança, ele pôde edificar as obras que quis: tanto que lhe custou muita fadiga para conquistar e pouca para manter.41","page":38},{"type":"heading","lvl":2,"title":"VII Dos novos principados que se conquistam pelas armas e sorte de outros","id":"h_o_pr_ncipe_nicolau_maquiavel_15","page":40},{"type":"paragraph","text":"VII","page":40},{"type":"paragraph","text":"Dos novos principados que se conquistam pelas armas e sorte de outros","page":40},{"type":"paragraph","text":"Aqueles que se tornam príncipes apenas favorecidos pela sorte e com pouco empenho terão, por outro lado, muitas dificuldades1 para manter sua posição;2 nenhum obstáculo encontram ao longo do caminho pelo qual voam. Porém, todo tipo de dificuldade3 aparecerá ao pensarem ter atingido o objetivo. Isso acontece àqueles a quem é concedido um Estado, seja por dinheiro, seja por favorecimento de quem o conceda. É o que ocorreu a muitos na Grécia, nas cidades de Helesponto e da Jônia, onde príncipes foram eleitos por Dario para que as mantivessem em segurança para sua própria glória.4 Foi assim também que foram eleitos os imperadores que, de cidadãos comuns, foram elevados a esse status pela corrupção dos exércitos.5 A permanência desses príncipes dependia exclusivamente de dois fatores volúveis e instáveis: da vontade e da sorte daqueles que os elegiam; eles próprios não sabem nem podem manter sua posição:6 não sabem porque, não sendo dotados de grande engenhosidade e virtude, é pouco provável que homens com pouca experiência e que sempre viveram como cidadãos comuns7 saibam governar;8 e não podem por não possuírem forças amigas e leais.9","page":40},{"type":"paragraph","text":"Além disso, os Estados repentinamente formados são como todas as coisas que, pela ordem da natureza, nascem e crescem precocemente: não podem ter raízes e estruturas suficientemente profundas para fazer frente à primeira adversidade do tempo e acabam sendo extintas.10 A menos que, como eu disse, os que se tornaram príncipes de repente tenham suficiente habilidade11 para logo se preparar a fim de preservar o que a sorte lhes colocou nas mãos, e estabeleçam, como tantos outros fizeram, as bases de seu poder.12","page":40},{"type":"paragraph","text":"Com relação a esses dois modos apresentados acima, de se tornar príncipe por virtude ou por sorte,13 quero referir-me a dois exemplos que fazem parte de nossa memória: o de Francisco Sforza e o de César Bórgia.","page":41},{"type":"paragraph","text":"Francisco Sforza, com os devidos meios e grande virtude,14 de cidadão comum tornou-se duque de Milão,15 e o que havia conquistado com grandes dificuldades manteve com pouco esforço. Por outro lado, César Bórgia, chamado vulgarmente de duque Valentino, adquiriu o Estado com a fortuna do pai, o papa Alexandre VI, e com ela o perdeu, e isso apesar de ter feito tudo o que um homem prudente e hábil poderia fazer para aprofundar as suas bases no Estado que as armas e a fortuna alheias lhe haviam concedido.16 Conforme já disse antes, quem não prepara as bases com antecedência pode habilmente estabelecêlas depois de sua ascensão ao poder,17 embora isso seja feito a desconforto do arquiteto e a perigo da edificação.18","page":41},{"type":"paragraph","text":"Portanto, se considerarmos todos os progressos do duque, veremos que, afinal, acabou estabelecendo grandes bases para a futura potência;19 julgo útil comentar a respeito,20 pois eu não poderia apresentar a um príncipe novo um melhor exemplo que essas suas ações. E se essas disposições não beneficiaram o duque, não foi por culpa própria, mas por causa de uma extraordinária e extrema má sorte.21","page":41},{"type":"paragraph","text":"Ao querer enaltecer o duque, seu filho, o papa Alexandre VI deparou-se com grandes dificuldades presentes e futuras. Primeiro, ele não via outro meio senão torná-lo senhor de um Estado que fosse dominado pela Igreja,22 e ao tentá-lo, sabia que o duque de Milão e os venezianos não consentiriam com seu plano, pois Faenza e Rimini já estavam sob a proteção dos venezianos. Além disso, sabia que todas as forças da Itália, especialmente as que poderiam ser-lhe úteis, estavam nas mãos dos que temiam o seu engrandecimento e em quem ele não poderia confiar por estarem todos sob a dependência dos Orsini, dos Colonna e de seus partidários. Era, então, necessário semear a desordem em todos esses Estados23 a fim de tomar posse de algum.24 Isso foi-lhe fácil, pois encontrou os venezianos, que movidos por outros motivos,25 estavam decididos a fazer que os franceses voltassem à Itália, com o que não somente concordou, como a própria execução do plano foi facilitada com a anulação do primeiro casamento do rei","page":41},{"type":"paragraph","text":"Luís.26 O rei, então, foi para a Itália com a ajuda dos venezianos27 e o consentimento de Alexandre VI. Assim que chegou a Milão, o papa obteve do rei tropas para uma expedição à Romanha que se tornou possível pela reputação do próprio rei.","page":42},{"type":"paragraph","text":"Assim, havendo conquistado a Romanha e derrotado os Colonna, o duque Valentino, querendo preservar essa sua conquista e continuar mais adiante, deparava-se com duas dificuldades: a primeira era a desconfiança em suas tropas e a segunda era a vontade da França; i.e., de um lado, ele temia que as tropas dos Orsini, das quais se valera, não somente o impedissem de conservar suas conquistas, como também lhe tomassem o que conquistara; e, de outro, que o rei da França fizesse o mesmo.28 Quanto às tropas dos Orsini, ele já tivera provas de suas disposições depois da tomada de Faenza, quando percebeu a conduta fria com a qual atacaram Bolonha. O duque também percebeu as intenções do rei quando, depois de tomar o ducado de Urbino e querendo dirigir suas tropas contra a Toscana, o monarca o fez desistir de sua empresa.","page":42},{"type":"paragraph","text":"Foi quando o duque decidiu não depender mais das armas e da fortuna de outros.29 A primeira providência que tomou foi enfraquecer os partidários dos Orsini e dos Colonna em Roma, atraindo para si todos os seus simpatizantes, que faziam parte da nobreza,30 tornando-os seus gentis-homens, e segundo suas habilidades, conferindo-lhes grandes provisões e a honra de comandar tropas e de dirigir governos. De maneira que, em poucos meses, a afeição de todos os partidos voltou-se para o duque.31","page":42},{"type":"paragraph","text":"Depois de dispersar os partidários dos Colonna, ele esperou a oportunidade de destruir os partidários dos Orsini,32 e quando a ocasião surgiu, soube aproveitá-la melhor, pois os Orsini, percebendo tardiamente que o engrandecimento do duque e da Igreja seria a causa de sua própria ruína, organizaram uma conferência em Magione, na província de Perúgia. Foi dessa conferência que nasceu a rebelião de Urbino, os tumultos na Romanha e os grandes perigos para o duque,33 que soube superar todas as dificuldades, ajudado pelos franceses.34","page":42},{"type":"paragraph","text":"Recuperada a sua reputação e não confiando na França nem nas forças estrangeiras, ele recorreu à astúcia.35 Dissimulou tão bem seus sentimentos36 que conseguiu se reconciliar com os Orsini por intermédio do senhor Paulo, a quem o duque soube assegurar sua amizade, recompensando-o com dinheiro, vestes e cavalos. A simplicidade dos Orsini ainda rendeu ao duque a cidade de Sinigaglia.37","page":42},{"type":"paragraph","text":"Uma vez eliminados esses chefes e transformados seus partidários em aliados,38 o duque consolidou as bases de seu poder. Além disso, senhor da Romanha e do ducado de Urbino, ele ainda conquistou a dedicação de seus habitantes fazendo-os experimentar um início de bem-estar.39","page":43},{"type":"paragraph","text":"Como essa parte da história é digna de ser conhecida e imitada, não quero deixar de aqui comentá-la.40 Portanto, uma vez conquistada a Romanha, que fora dirigida por senhores impotentes os quais haviam apenas espoliado41 seus súditos e causado sua desunião,42 tanto que na província reinava o latrocínio, o crime e a violência,43 o duque julgou necessário torná-la pacífica e obediente ao poder real, arrogando-lhe um bom governo.44 Para isso, confiou o poder a Ramiro d’Orco, homem cruel e destemido, ao qual deu amplos poderes.45 Em pouco tempo Ramiro tornou-a pacífica e unida,46 conseguindo uma grande reputação. Mas, logo em seguida, pensando que esse tipo de autoridade não fosse mais necessário e a fim de que não se tornasse odioso,47 estabeleceu um tribunal civil no centro da província com um excelente presidente e cada cidade com o próprio advogado.48 E, ciente que estava de que os rigores passados poderiam ter dado origem a algum ódio, fez o máximo para conquistar totalmente os habitantes dessa região demonstrando que se alguma crueldade havia sido cometida, não nascera dele, mas da natureza maldosa de seu ministro.49 Aproveitando-se da oportunidade,50 ele expôs na praça pública de Cesena o corpo do ministro cortado ao meio, com um tronco de madeira e uma faca ensanguentada ao seu lado.51 A ferocidade do espetáculo fez com que os habitantes ficassem satisfeitos e, ao mesmo tempo, aterrorizados.52","page":43},{"type":"paragraph","text":"Mas, voltemos ao nosso ponto de partida. Depois de ter-se armado à sua maneira e eliminado em parte os vizinhos que poderiam prejudicá-lo, o duque achavase bastante forte e relativamente seguro quanto aos perigos correntes, para, assim, poder dar continuidade às suas conquistas. Mas, para isso, faltavalhe a consideração da França, pois o rei, havendo percebido tardiamente seu próprio erro, não autorizaria suas novas empresas. Então, ele começou a buscar novas amizades e a ser evasivo com os franceses53 quando estes decidiram marchar para o reino de Nápoles contra os espanhóis que estavam assediando Gaeta; sua intenção era garantir-se contra eles, e teria conseguido se Alexandre não viesse a falecer.54","page":43},{"type":"paragraph","text":"Essas foram suas medidas com respeito às coisas presentes. Mas, quanto às futuras, ele tinha antes a temer que o novo sucessor da Igreja não lhe fosse amigo e procurasse tomar o que Alexandre lhe havia dado.55 Pensou, então, tomar as seguintes quatro providências:56 em primeiro lugar, eliminar todas as famílias que ele espoliara para que o papa não tivesse condições de atingi-lo;57 em segundo lugar, atrair para si todos os gentis-homens de Roma para, juntos, manter o papa sob controle; em terceiro lugar, fazer o máximo para que o Sagrado Colégio ficasse a seu favor; e em quarto lugar, tornar-se o mais poderoso possível, antes que o papa morresse,58 a fim de poder, por si mesmo, resistir a um primeiro impacto.59 No momento da morte de Alexandre VI, ele já havia realizado três de suas intenções e considerava a quarta quase concluída.","page":44},{"type":"paragraph","text":"Efetivamente, ele havia eliminado quantos pôde alcançar dos senhores que havia espoliado, e poucos se salvaram;60 conseguiu realmente atrair para o seu lado os gentis-homens romanos61 e já tinha em suas mãos grande parte do Sagrado Colégio. Quanto às novas conquistas, ele planejara tornar-se senhor da Toscana e já possuía Perúgia e Piombino, e encarregou-se da proteção de Pisa, que planejava assaltar sem ser desautorizado pelos franceses, que foram derrotados pelos espanhóis e expulsos do reino de Nápoles, de maneira que, afinal, tiveram de procurar sua amizade.62 Em seguida, Lucca e Siena cederiam facilmente, em parte por medo e em parte por inveja dos florentinos; e estes últimos ficariam, então, sem recursos.","page":44},{"type":"paragraph","text":"Se o duque houvesse colocado esse plano em ação (e ele o teria conseguido durante o ano em que Alexandre morreu), teria poder e reputação suficientes para se manter sozinho e não mais depender das forças e fortuna de outros,63 mas apenas de sua própria força e valor.64 Mas Alexandre morreu cinco anos depois de ele começar a desembainhar a espada. O duque viu-se apenas com o Estado da Romanha consolidado e todos os outros sem qualquer definição, entre dois poderosíssimos exércitos inimigos e sofrendo de uma doença mortal.65","page":44},{"type":"paragraph","text":"Seguramente, o duque teria superado todas as suas dificuldades se estivesse bem de saúde66 e não tivesse os exércitos inimigos às suas portas, pois ele era dotado de uma coragem e uma habilidade impressionantes; sabia muito bem como conquistar ou destruir os homens67 e soube, em tão pouco tempo, estabelecer bases sólidas para o seu poder. Que as bases que ele estabeleceu eram sólidas é demonstrado pelo fato de a Romanha esperar por mais de um mês que ele voltasse,68 mas ele, quase à morte, permaneceu na segurança de Roma.69","page":44},{"type":"paragraph","text":"E embora os Baglioni, os Vitelli e os Orsini se apressassem para lá se dirigir, nada puderam fazer contra ele, pois apesar de não ter conseguido fazer que o seu candidato fosse eleito papa, pelo menos impediu que o fosse quem ele não queria.70 Se a saúde não lhe tivesse faltado à morte de Alexandre, tudo teria sido fácil.","page":45},{"type":"paragraph","text":"No dia em que Júlio II foi eleito, ele me disse que havia pensado em tudo que poderia acontecer caso o pai viesse a morrer e que para tudo encontrara solução, mas que nunca imaginara a hipótese de, nesse momento, ele mesmo estar à beira da morte.71","page":45},{"type":"paragraph","text":"Ao resumir todas as ações do duque, eu não saberia criticá-lo;72 ao contrário, penso que ele deveria servir como modelo para todos aqueles que alcançaram o poder por meio da fortuna ou das armas de outros.73 Dotado de grande coragem e de altas intenções, ele não poderia ter agido de outra forma,74 e somente a morte de Alexandre e a própria doença opuseram-se aos seus desígnios.75","page":45},{"type":"paragraph","text":"Portanto, aquele que, em seu principado novo,76 julgar necessário prevenir-se contra os inimigos conquistando amigos, vencer pela força ou por fraude, fazerse amar e temer pelo povo, ser seguido e respeitado pelos soldados, eliminar os que podem ou venham a ofendê-lo, renovar as instituições antigas, ser severo e grato, magnânimo e liberal, extinguir a milícia infiel e criar uma nova, manter a amizade dos reis e dos príncipes de maneira que o beneficiem com graça ou o ataquem com respeito77 não poderá encontrar exemplos mais recentes que as ações do duque Valentino.78","page":45},{"type":"paragraph","text":"Somente é possível acusá-lo pela má escolha na eleição do papa Júlio II,79 pois ele não pôde, como já disse, fazer eleger o pontífice de sua escolha,80 mas pôde evitar que fosse eleito quem ele não aprovava.81 Nunca deveria ter consentido que fosse elevado ao pontificado qualquer cardeal que por ele houvesse sido ofendido e que, depois de eleito, pudesse ter motivos para temê-","page":45},{"type":"paragraph","text":"lo,82 pois os homens ofendem por medo ou por ódio.","page":46},{"type":"paragraph","text":"Os cardeais que o duque havia ofendido eram, entre outros, São Pedro ad Vincula, Colonna, San Giorgio e Ascanio;83 todos os outros tinham motivos para temê-lo, caso viessem a ser eleitos,84 com exceção do cardeal de Ruão e dos espanhóis; estes últimos por causa de relações e obrigações recíprocas,85 e o cardeal de Ruão por ter a seu lado o reino da França, o que lhe dava grande poder. Portanto, o duque deveria ter favorecido um papa espanhol e, não sendo possível, deveria ter consentido eleger o cardeal de Ruão, e não São Pedro ad Vincula. É um engano86 pensar que novos benefícios façam com que os grandes personagens se esqueçam das antigas injúrias.87 Ao consentir com a eleição de Júlio II, o duque cometeu o erro que foi a causa de sua ruína.","page":46},{"type":"heading","lvl":2,"title":"VIII Dos que alcançaram o principado por meios criminosos","id":"h_o_pr_ncipe_nicolau_maquiavel_16","page":47},{"type":"paragraph","text":"VIII","page":47},{"type":"paragraph","text":"Dos que alcançaram o principado por meios criminosos","page":47},{"type":"paragraph","text":"Existem, ainda, duas formas de um homem comum se tornar príncipe sem depender absolutamente da sorte ou do valor, os quais não me parece certo deixar de lado, mesmo que um deles possa ser amplamente discutido em se tratando de repúblicas.1 Essas duas formas consistem em alcançar o principado por meio de infâmias e atos nefastos2 ou quando um cidadão comum é levado ao principado pelo favor de seus concidadãos.3","page":47},{"type":"paragraph","text":"E, para falar da primeira forma, apresentarei dois exemplos: um é antigo e o outro é moderno, sem, porém, entrar a fundo no mérito dos mesmos, pois acredito que sejam suficientes para quem considere necessário imitá-los.4","page":47},{"type":"paragraph","text":"O siciliano Agátocles, homem comum da mais abjeta condição, tornou-se rei de Siracusa.5 Filho de um oleiro, desde a sua juventude levou uma vida de vilão,6 juntando aos seus crimes o vigor de sua alma e corpo,7 tanto assim que ingressou na milícia e, galgando os vários graus pela força de sua maldade, alcançou a posição de pretor (comandante do exército) de Siracusa.8 Instalado no cargo e decidido a tornar-se príncipe, conseguindo pela violência e sem nenhuma devida obrigação9 o que, por direito, lhe era concedido, entrou em entendimento com Amílcar de Cartago, que, com seu exército, militava na Sicília.10 Certa manhã, ele convocou o povo e o Senado de Siracusa como se quisesse deliberar sobre assuntos importantes da república e, a um seu sinal, seus soldados assassinaram todos os senadores e as pessoas mais ricas do povo. Em seguida, ocupou e manteve o poder sobre essa cidade sem nenhuma contestação civil.11","page":47},{"type":"paragraph","text":"Embora fosse derrotado duas vezes e, depois, assediado pelos cartagineses, ele não somente defendeu a cidade, como também deixou uma parte do exército defendendo o assédio, e com a outra parte atacou a África. Em pouco tempo libertou Siracusa, deixando os inimigos na necessidade. Cartago foi forçada a aceitar um acordo que lhe garantia o domínio da África, deixando a Sicília para Agátocles.12","page":47},{"type":"paragraph","text":"Portanto, quem considerar as ações e a virtude desse indivíduo verificará quão pouco pode ser atribuído à sorte. Como já mencionei, sua elevação ao poder não ocorreu pelo favoritismo de ninguém, mas pelos graus galgados na milícia13, passando por mil dificuldades e perigos. Depois, conseguiu manter esse poder por meio de resoluções arrojadas e arriscadas.14","page":48},{"type":"paragraph","text":"Entretanto, não é possível chamar de virtude o assassinato dos próprios concidadãos, a traição aos amigos, o fato de não ter fé, piedade e religião, métodos que podem levar à conquista de impérios, mas não à da glória.15 Se considerarmos o valor de Agátocles ao enfrentar e superar os perigos, e a sua grandeza de ânimo ao suportar e vencer as adversidades,16 não há por que julgálo inferior a qualquer famoso capitão.17 No entanto, sua fria e desumana crueldade, bem como suas infinitas infâmias, não permitem que ele seja inserido entre os nomes dos homens mais ilustres.18 Por conseguinte, não é possível atribuir à sorte ou à virtude o que ele conseguiu sem a ajuda de nenhuma uma delas.19","page":48},{"type":"paragraph","text":"Em nossa época, durante o reinado de Alexandre VI, Oliverotto de Fermo,20 órfão em tenra idade, foi criado por um tio materno de nome Giovanni Fogliani e, nos primeiros anos de sua juventude, ingressou na escola militar sob as ordens de Paulo Vitelli para que, uma vez formado por essa excelente escola, pudesse alcançar uma boa graduação na milícia.21 Quando Paulo morreu, ele militou sob as ordens de Vitellozzo, irmão de Paulo, e devido à sua engenhosidade, força corporal e coragem, em pouco tempo tornou-se o primeiro homem de sua milícia. Mas parecendo-lhe servil o fato de depender dos outros, ajudado por alguns cidadãos de Fermo para quem a servidão era mais cara que a liberdade de sua pátria,22 e favorecido por Vitellozzo, planejou tornar-se senhor de Fermo.","page":48},{"type":"paragraph","text":"Seguindo seu plano, escreveu para o seu tio, Giovanni Fogliani, dizendo que, após tantos anos longe de casa, queria visitá-lo, rever sua cidade e conhecer seu patrimônio, e, ao mesmo tempo, mostrar aos seus concidadãos que havia sempre trabalhado com honradez e que o seu tempo não fora mal empregado. Disse também que seria acompanhado de cem cavaleiros, seus amigos e servidores,23 e pedia que fosse recebido pelos cidadãos de Fermo com todas as honras, o que não somente dignificaria o tio como também a si próprio, por ter sido seu aluno.","page":48},{"type":"paragraph","text":"Giovanni empreendeu todos os seus esforços para honrar o sobrinho, que foi recebido pelos habitantes de Fermo e alojado em suas próprias casas. Passados alguns dias e tomadas as providências para a realização de seu plano infame, Oliverotto promoveu uma solene reunião para a qual convidou Giovanni Fogliani e todos os homens importantes de Fermo.24 Ao final do repasto e dos entretenimentos próprios desse tipo de confraternização, Oliverotto abordou com habilidade alguns assuntos importantes, falando da grandeza do papa Alexandre VI e de César, seu filho, e de seus empreendimentos. Giovanni e os outros prestavam atenção ao que dizia quando, de repente, ele se levantou alegando ser mais discreto falar desses assuntos em particular e retirou-se para uma sala para a qual todos os convidados o seguiram. Mal haviam se sentado e de lugares ocultos saíram soldados que mataram Giovanni e todos os demais.25","page":49},{"type":"paragraph","text":"Logo após esse homicídio, Oliverotto montou em seu cavalo, percorreu a região e foi assediar o supremo magistrado em seu palácio. De maneira que, por medo, todos foram forçados a obedecer-lhe e a formar um governo do qual se fez príncipe.26 Além disso, ele eliminou todos os insatisfeitos que pudessem vir a prejudicá-lo27 e consolidou o seu poder por meio de novas resoluções civis28 e militares.29 Fez isso de tal forma que no período de um ano, durante o qual manteve o poder,30 não somente estava seguro na cidade de Fermo como também ficou sendo temido por toda a vizinhança. Sua destruição teria sido difícil, como foi difícil a de Agátocles, se ele não houvesse sido enganado por César Bórgia e por este preso em Sinigaglia, junto com os Orsini e os Vitelli, onde foi estrangulado,31 assim como Vitelozzo, seu mestre e companheiro de crimes,32 um ano depois do parricídio.33","page":49},{"type":"paragraph","text":"Algumas pessoas poderiam se surpreender pelo fato de que, com tantas traições e tanta crueldade, Agátocles e outros iguais a ele pudessem viver em segurança durante muito tempo em sua pátria, defendendo-se dos inimigos externos e, ao mesmo tempo, sem sofrer conspirações planejadas pelos próprios cidadãos, embora muitos outros, por sua crueldade, não conseguissem manter o poder nem em tempos de paz, nem em tempos de guerra. Acredito que isso decorra do bom ou mau emprego da crueldade.34 As crueldades bem empregadas (se for lícito dizer que um mal seja bem empregado) são aquelas cometidas uma só vez35 por necessidade de segurança própria,36 sem depois nelas insistir,37 mas transformando-as ao máximo possível em benefício dos súditos.38 As crueldades mal empregadas são aquelas que são poucas no início, mas que se multiplicam com o passar do tempo,39 em vez de cessar. Os que seguem o primeiro método podem, com a ajuda de Deus e dos homens, remediar suas condições, como aconteceu com Agátocles. Quanto aos outros, é impossível que se mantenham.40","page":49},{"type":"paragraph","text":"A esse respeito, é preciso observar que, ao conquistar um Estado, o conquistador deve determinar e executar as crueldades de uma só vez41 para que não tenha de repeti-las todos os dias e possa, evitando renová-las, proporcionar segurança aos súditos e conquistá-los com alguns benefícios. Aquele que agir de outra forma, por timidez42 ou por mau aconselhamento,43 terá a obrigação de viver com a espada na mão44 e jamais poderá contar com seus súditos, que, devido às recentes e constantes perseguições, nunca chegarão a depositar-lhe confiança. Pois as perseguições devem ser realizadas de uma só vez, de maneira que, quanto menos são sentidas, tanto menos ofendem.45 Os benefícios, ao contrário, devem ser concedidos gradativamente para que sejam mais bem apreciados.46","page":50},{"type":"paragraph","text":"E, acima de tudo, um príncipe deve conviver com os seus súditos para que nenhum bom ou mau acontecimento o faça mudar de política,47 pois se esperar ser obrigado pela adversidade das circunstâncias a praticar o mal ou o bem, é possível que não tenha tempo suficiente para colocar o mal em prática48 ou que o bem não o venha a beneficiar,49 pois poderia ser considerado como imposição do momento, sem que ninguém o aprecie.50","page":50},{"type":"heading","lvl":2,"title":"IX Do principado civil","id":"h_o_pr_ncipe_nicolau_maquiavel_17","page":51},{"type":"paragraph","text":"Do principado civil","page":51},{"type":"paragraph","text":"Mas, passando adiante, quando um cidadão comum se torna príncipe, não por crueldade ou por qualquer intolerável violência,1 mas pelo favoritismo de seus concidadãos, o que pode ser chamado de principado civil (para consegui-lo não é preciso habilidade nem sorte, mas uma astúcia afortunada2), eu acredito que esse principado seja alcançado pelo favoritismo do povo ou dos grandes locais.3 Pois em todas as cidades encontram-se essas duas disposições opostas de espírito. Isso ocorre quando o povo não quer mais ser comandado e oprimido pelos grandes, e os grandes querem comandar e oprimir o povo; desses dois aspectos diferentes nasce, nas cidades, um destes três efeitos: principado, liberdade ou licenciosidade (desordem).","page":51},{"type":"paragraph","text":"O principado é obra do povo ou dos grandes, dependendo da oportunidade que uma das partes tenha, pois quando os grandes percebem não poder resistir ao povo,4 começam a enaltecer a reputação de alguém de seu próprio meio5 e o tornam príncipe6 para poder, sob sua proteção, satisfazer seus ambiciosos desejos. Por outro lado, percebendo o povo não poder resistir aos grandes, enaltece alguém de seu próprio meio e o torna príncipe para que o defenda com a sua autoridade.7 Aquele que alcança o principado ajudado pelos grandes se mantém com mais dificuldade que o que se torna príncipe com a ajuda do povo,8 pois tem a seu redor pessoas que ele considera seus iguais9 e, por isso, não os consegue comandar nem tampouco manejá-los à sua maneira. Mas quem consegue alcançar o principado com o apoio popular10 encontra-se sozinho, sem ninguém ou com poucos ao seu redor que não estejam dispostos a lhe obedecer.11 Além disso, não é possível, com toda honestidade, satisfazer os grandes sem causar algum prejuízo aos demais,12 mas ao povo sim.13 Mas o","page":51},{"type":"paragraph","text":"príncipe eleito pelo povo é mais honesto que o príncipe eleito pelos grandes,14 cujo objetivo é o de oprimir, enquanto o povo quer se furtar à opressão. O príncipe que tem o povo por inimigo dificilmente estará em segurança devido ao seu grande número, enquanto, ao contrário, a hostilidade dos grandes não o fará estremecer, por serem poucos.15 O pior que um príncipe pode esperar de um povo hostil é vir a ser por ele abandonado; mas da hostilidade dos grandes, não deve apenas temer o desamparo como também recear que o afrontem, pois enxergando mais longe e sendo mais astuciosos, eles jamais perdem tempo para se salvar, procurando prestígio no partido que esperam ver vitorioso.16 É necessário, ainda, que o príncipe conviva com o mesmo povo enquanto pode muito bem dispensar os poderosos, porquanto pode elevá-los e rebaixá-los a qualquer momento, dando-lhes ou tirando-lhes a influência a seu critério.17","page":52},{"type":"paragraph","text":"E para melhor esclarecer essa parte, direi que os grandes devem ser considerados de duas maneiras principais: eles comprometem a sua conduta de forma a vinculá-la à sorte do príncipe ou não o fazem. Os que confirmarem esse vínculo e não são inclinados à rapina18 devem ser honrados e apreciados.19 Os que não o confirmarem devem ser analisados de duas maneiras: assim se comportam por pusilanimidade ou por defeito natural do espírito.20 Nesse caso é possível servir-se daqueles que sejam sensatos, pois o príncipe os honrará na prosperidade e não os temerá na adversidade.21 Mas aqueles que não confirmarem esse vínculo por razões ambiciosas22 dão sinais de que pensam mais em si próprios do que no príncipe.23 É desses últimos que o príncipe deve precaver-se e temê-los como se fossem inimigos declarados porque em toda adversidade eles conspirarão para a sua ruína.24","page":52},{"type":"paragraph","text":"Assim, aquele que se tornar príncipe mediante o favor do povo deverá mantê-lo como aliado, o que é fácil uma vez que o povo apenas pede para que seja poupado da opressão. Mas aquele que contra o povo se tornar príncipe mediante o favor dos grandes deve, antes de qualquer coisa, conquistá-lo, o que ele facilmente conseguirá ao colocá-lo sob a sua proteção.25 E como os homens, ao receber o bem de quem supunham receber apenas o mal,26 se mostram ainda mais gratos ao benfeitor, o povo logo o apreciará como se houvesse sido por ele conduzido ao principado.27 E ainda é possível conquistar o povo de várias maneiras, mas como elas variam segundo as circunstâncias, não há como criar uma única regra, e, portanto, eu as deixarei de lado. Concluirei apenas que um príncipe precisa ter consigo um povo amigo,28 do contrário sucumbirá às adversidades.29","page":52},{"type":"paragraph","text":"Nábis, príncipe dos espartanos, suportou o assédio de toda a Grécia, além de um vitorioso exército romano, defendendo a sua pátria e o seu Estado. Para enfrentar esse grande perigo bastou-lhe apenas assegurar-se de um pequeno grupo de pessoas, o que não teria sido suficiente caso não tivesse o apoio do povo. E que ninguém conteste esta minha opinião valendo-se daquele conhecido provérbio: quem se apoia no povo apoia-se no barro.30 Isso pode realmente ser verdadeiro em se tratando de um simples cidadão que conte com esse apoio, persuadido de que o povo o defenderá caso venha a ser oprimido por seus inimigos ou pelos magistrados. Essa expectativa, muitas vezes, é enganosa e decepcionante, tal como aconteceu aos Gracos em Roma e a messer Giorgio Scali em Florença. Mas em se tratando de um príncipe com poder de comandar, um homem de coração que não esmoreça na adversidade; que não deixe de tomar as medidas mais convenientes e que saiba, por meio de sua firmeza, sustentar o ânimo de seu povo, jamais será por ele enganado e poderá constatar ter nele estabelecido bases sólidas.31","page":53},{"type":"paragraph","text":"Esses principados costumam desestabilizar-se quando estão para passar da ordem civil para o poder absoluto,32 pois esses príncipes assumem o comando ou governam por meio de magistrados. Neste último caso, a situação de um príncipe é mais fraca e perigosa33 porque depende totalmente da vontade dos cidadãos que foram investidos nessa magistratura, os quais, principalmente em tempos de adversidade, podem facilmente arrebatar-lhe o Estado, seja agindo contra ele, seja desobedecendo às suas ordens.34 Nesse momento, o príncipe não terá mais condições de retomar sozinho o exercício de seu poder, pois o tempo já passou e os cidadãos e os súditos, acostumados a receber ordens dos magistrados, não estarão mais dispostos, nos momentos críticos, a obedecer às ordens que o príncipe daria.35 E assim, nesses tempos de incertezas, será difícil para o príncipe encontrar pessoas em quem confiar.36","page":53},{"type":"paragraph","text":"É que esse príncipe não pode e não deve se basear no que percebe em tempo de paz, quando os cidadãos precisam de sua autoridade e todos se apressam a fazer-lhe promessas, e com a morte distante, a querer sacrificar-se por ele.37","page":53},{"type":"paragraph","text":"Mas, nos momentos de adversidade, quando o Estado vier a precisar de todos os cidadãos, poucos serão aqueles dispostos a defendê-lo. Entretanto, essa experiência é tão perigosa que somente pode ser realizada uma única vez.38","page":54},{"type":"paragraph","text":"Entretanto, um príncipe sábio deve saber agir de maneira que os seus cidadãos, sempre e em qualquer circunstância, venham a precisar do Estado39 e dele mesmo. E então, eles lhe serão sempre fiéis.40","page":54},{"type":"heading","lvl":2,"title":"X De como devem ser medidas as forças de todos os principados","id":"h_o_pr_ncipe_nicolau_maquiavel_18","page":55},{"type":"paragraph","text":"De como devem ser medidas as forças de todos os principados","page":55},{"type":"paragraph","text":"Ao analisar as qualidades desses principados, há ainda outra consideração a fazer: a de saber se o príncipe tem um Estado suficientemente poderoso para poder, se necessário, defender-se por si só41 ou se depende sempre de forças alheias.42 Para melhor esclarecer esta minha ideia, julgo ter a capacidade de se defender, por si mesmos, os príncipes que tenham à disposição suficientes homens e dinheiro para formar um exército e enfrentar quem os queira atacar.43","page":55},{"type":"paragraph","text":"E, ao contrário, considero dependentes de forças alheias aqueles príncipes que não têm condições de enfrentar o inimigo em campo aberto e se refugiam entre suas muralhas, sob constante vigilância.44","page":55},{"type":"paragraph","text":"O primeiro caso já foi discutido, e mais adiante falaremos sobre o que pode lhes acontecer. Quanto ao segundo caso, nada pode ser dito além de exortar esses príncipes a fortificar e a prover suas terras45 sem se importar com o resto do país, pois aquele que corretamente fortificar suas terras e se comportar com os seus súditos da maneira como foi expressa acima, e conforme se dirá mais adiante, jamais será atacado sem o devido respeito e temor. O fato é que os homens evitam os empreendimentos que apresentem dificuldades e, com certeza, enfrentarão muitas ao atacar um príncipe cuja cidade é bem defendida e que, além disso, não é odiado por seus súditos.46","page":55},{"type":"paragraph","text":"As cidades da Alemanha gozam de uma grande liberdade, embora tenham um território muito limitado; elas obedecem ao imperador ao bel-prazer, não o temem e tampouco temem seus poderosos vizinhos,47 pois acreditam que, pelo fato de estarem bem protegidas e fortificadas, a tentativa de um assédio seria morosa e difícil.48 Todas têm fossos, fortes muralhas e suficiente artilharia; seus depósitos públicos têm provisões de alimentos, de bebidas e de combustível suficientes para um ano.49 Além disso, para manter a plebe alimentada e sem acarretar perdas às reservas públicas, a comunidade tem a possibilidade, durante um ano, de prover-lhe trabalho naquelas atividades que são o próprio nervo e vida dessas cidades e das indústrias que garantem à plebe a sua subsistência. Praticam, ainda, os exercícios militares executados de acordo com muitos regulamentos.50","page":55},{"type":"paragraph","text":"Portanto, um príncipe que mantém uma cidade forte e faz de tudo para não ser odiado não é passível de ser atacado. Apesar disso, caso alguém se aventurasse a tentar, acabaria se retirando envergonhado, pois a vida é tão dinâmica que seria impossível manter um exército um ano inteiro na ociosidade de um assédio.51 E se alguém me contestar dizendo que o povo não veria com bons olhos suas propriedades sendo queimadas além das muralhas, e que o longo assédio, a falta de paciência e a autocomiseração fariam que os cidadãos se esquecessem do príncipe, eu responderia que um príncipe forte e valente sempre superará todas as dificuldades, ora levando a esperança de que o mal não perdurará, ora incutindo o temor à crueldade do inimigo, ora precavendo-se com habilidade das pessoas que lhe pareçam ser por demais temerárias.52","page":56},{"type":"paragraph","text":"Além disso, é lógico pensar que o inimigo se apressaria em queimar e arrasar as propriedades vizinhas assim que chegasse, quando a combatividade dos defensores estaria no auge e o príncipe com menos motivos para se preocupar, pois, passados alguns dias, os ânimos começam a se conformar uma vez que os danos já foram consumados, os males sofridos, e não há como remediá-los. Então, os habitantes se unem ao príncipe, pois entendem que ele lhes deve uma obrigação, uma vez que foi em sua defesa que suas casas foram queimadas e que suas terras foram destruídas.53","page":56},{"type":"paragraph","text":"É próprio da natureza dos homens se obrigarem tanto pelos benefícios que proporcionam quanto pelos benefícios que recebem.54 E assim, considerando o todo, não será difícil ao príncipe prudente inspirar firmeza aos habitantes e mantê-los unidos e animados, desde que não lhes faltem provisões e meios de se defender.55","page":56},{"type":"heading","lvl":2,"title":"XI Dos principados eclesiásticos","id":"h_o_pr_ncipe_nicolau_maquiavel_19","page":57},{"type":"paragraph","text":"Dos principados eclesiásticos","page":57},{"type":"paragraph","text":"Falta, agora, falar dos principados eclesiásticos quanto às dificuldades que surgem antes que deles se tome posse, pois são conquistados pela virtude ou pelo favor da sorte (fortuna), e sem essas duas condições, eles se mantêm por serem sustentados pelas antigas instituições religiosas cujo poder é tão grande e de tal natureza que seus príncipes são mantidos no poder independentemente da forma pela qual procedem e vivem.1 Apenas esses príncipes possuem Estados que não defendem e súditos que não são governados.2 Apesar de indefesos, os Estados não lhes são tomados, e embora não governados, não se preocupam nem sequer pensam, e nem poderiam, separar-se deles.3 De maneira que esses principados são seguros e felizes.4","page":57},{"type":"paragraph","text":"Porém, sendo eles regidos por causas superiores às quais o espírito humano não consegue alcançar, deixarei de falar a esse respeito, pois sendo exaltadas e mantidas por Deus,5 seria presunçoso e temerário para o homem discuti-las ou tentar explicá-las. Contudo, se alguém procurasse indagar de que forma a Igreja conseguiu chegar a alcançar tanta grandeza temporal, e mesmo Alexandre VI6 e todos aqueles que tinham algum poder na Itália, não apenas os príncipes, mas até os menores barões e senhores feudais, pouco se incomodavam com o seu poder temporal.7 Hoje, porém, ela consegue atemorizar um rei da França,8 expulsá-lo da Itália e arruinar os venezianos,9 e embora seja de conhecimento geral,10 não me parece supérfluo relembrar parte dessa história.","page":57},{"type":"paragraph","text":"Antes de o rei Carlos, da França, invadir a Itália, essa província encontravase sob o domínio do papa, dos venezianos, do rei de Nápoles, do duque de Milão e dos florentinos.11 Esses potentados tinham duas principais preocupações: a primeira era a de que nenhum estrangeiro entrasse na Itália com exércitos12 e a segunda era a de que nenhum potentado interno expandisse seus Estados.13 A maior preocupação era com o papa e com os venezianos. E, a fim de manter os venezianos sob controle, era preciso que todos os outros potentados se mantivessem unidos, como aconteceu na defesa de Ferrara. E para controlar o papa, eles contavam com a situação dos barões de Roma,14 os quais, divididos em duas facções, Orsini e Colonna, estavam em constantes disputas armadas sob os olhos do pontífice, que, dessa forma, era mantido fraco e recluso.15 Às vezes surgia um papa decidido e corajoso que reavivava a animosidade, como foi Sisto [IV], cuja sorte e conhecimento não o conseguiram livrar desses inconvenientes. Além disso, a brevidade de vida do pontífice era a causa dessa situação, pois tinha muita dificuldade de enfraquecer uma das facções durante a média de dez anos de sua vida, e no caso de, por exemplo, conseguir a quase extinção dos Colonna,16 outro papa era eleito, inimigo dos Orsini, que os reavivava. E, por sua vez, o novo papa não tinha o tempo necessário para destruí-los. Eis por que a Itália tinha pouco respeito pelas forças temporais do pontífice.17","page":57},{"type":"paragraph","text":"Foi quando surgiu Alexandre VI, que, com dinheiro e um exército forte,18 mostrou o que um papa podia fazer para conseguir maior poder. Ele usou como instrumento o duque Valentino, o qual, aproveitando-se da invasão francesa, fez tudo o que já relatei a respeito das ações do duque. E embora sua intenção não fosse a de fortalecer a Igreja,19 suas empresas reverteram em benefício da própria, que, depois da ruína e morte do duque, herdou os frutos de suas obras.","page":58},{"type":"paragraph","text":"Logo depois, Júlio assumiu o papado, encontrando a Igreja poderosa, dominando toda a Romanha e com os barões romanos reduzidos à impotência20 pelos rigores de Alexandre VI; ele se deparou com o caminho aberto para um maior acúmulo de riquezas, o que nunca havia sido feito antes de Alexandre.21 O papa Júlio não somente seguiu os seus passos, como os quis expandir, pensando em conquistar Bolonha, eliminar os venezianos e expulsar os franceses da Itália,22 o que conseguiu com grande louvor, pois tudo que fez reverteu em benefício da Igreja23 e não em prol de qualquer particular indivíduo. Ele ainda conseguiu manter os Orsini e os Colonna nos termos em que os encontrara,24 e mesmo que houvesse entre os dois algum líder capaz de provocar uma modificação na situação, duas coisas os restringiam: a própria grandeza da Igreja,25 que os atemorizava, e o fato de não terem cardeais26 em seu meio, os","page":58},{"type":"paragraph","text":"principais causadores dos tumultos entre suas próprias facções. É a eles que devem ser atribuídos os tumultos, pois são os que fomentam os partidos dentro e fora de Roma e obrigam os barões a defendê-los. De maneira que é da ambição dos prelados que nascem as discórdias e os tumultos entre os barões.27","page":59},{"type":"paragraph","text":"Foi assim que o papa Leão encontrou o pontificado potentíssimo, e esperavase que, se seus antecessores o tornaram grande pelas armas, ele o conseguiria por sua bondade e outras de suas grandes virtudes.28","page":59},{"type":"heading","lvl":2,"title":"XII Dos vários tipos de milícias e dos soldados mercenários","id":"h_o_pr_ncipe_nicolau_maquiavel_20","page":60},{"type":"paragraph","text":"XII","page":60},{"type":"paragraph","text":"Dos vários tipos de milícias e dos soldados mercenários","page":60},{"type":"paragraph","text":"Havendo detalhado de modo particular todos os tipos de principados a respeito dos quais me havia proposto comentar, e considerando ocasionalmente algumas das causas de seu mal-estar ou bem-estar, apresentei os meios pelos quais muitos procuraram conquistálos e mantê-los; resta-me agora falar, de modo geral, a respeito dos ataques e das defesas que cada citado principado possa sofrer.","page":60},{"type":"paragraph","text":"Dissemos acima que o poder de um príncipe seja estabelecido sobre boas bases, do contrário, cairá em desgraça. Os principais fundamentos que tanto os principados novos como os velhos ou mistos devem ter são boas leis e boas armas. E como onde há boas leis convém que haja boas armas, e onde há boas armas convém que haja boas leis, deixarei, por enquanto, de falar sobre as leis para comentar sobre as armas.1","page":60},{"type":"paragraph","text":"Digo, pois, que os contingentes com os quais um príncipe defende o seu Estado são compostos dos próprios, mercenários, auxiliares ou mistos, e que os mercenários e os auxiliares não somente são inúteis, mas até mesmo perigosos.2","page":60},{"type":"paragraph","text":"O príncipe cujo poder se baseia num exército mercenário nunca estará seguro e muito menos tranquilo, pois os mercenários são desunidos, ambiciosos, indisciplinados, infiéis, corajosos entre amigos e covardes frente aos inimigos. Também não temem a Deus e não têm fé nos homens. A derrota do príncipe coincidirá com o primeiro ataque. Em tempo de paz, por eles será espoliado, e em tempo de guerra, espoliado será pelos inimigos. Eles não têm outro motivo para permanecer no campo de batalha senão o pequeno salário que recebem, o que não é suficiente para morrer em defesa dos que os empregam. Querem ser soldados, mas em tempo de paz, e não de guerra. E assim que ela for desencadeada, fogem ou desertam,3 sobre o que não terei muito trabalho em convencer, pois a própria ruína da Itália foi causada pelo longo tempo que passou contando com tropas de mercenários. Elas chegaram a favorecer alguns e se mostraram valorosas enquanto não tinham de lutar entre si; mas logo apareceu um estrangeiro e então mostraram o que eram efetivamente. Por isso é que foi fácil para Carlos VIII, rei da França, conquistar a Itália com o giz;* aquele que disse que as causas foram nossos próprios pecados dizia a verdade. Entretanto, esses pecados não eram os que ele imaginava que fossem, mas os que eu acabei de expor. E como esses eram pecados de príncipes, eles também sofreram as consequências, entre si mesmos.4","page":60},{"type":"paragraph","text":"Quero demonstrar melhor a infelicidade dessa espécie de armas. Os capitães mercenários são ou não homens excelentes: caso sejam, não se pode confiar neles, pois sempre aspirarão à própria grandeza, seja oprimindo o próprio príncipe que os emprega, seja oprimindo outros contra a vontade do príncipe.5 E se não o forem,6 aquele a quem servem logo estará arruinado. E se alguém disser que essa será a conduta daquele que tem as armas na mão, seja ele mercenário ou não, responderei que as armas devem ser usadas por um príncipe7 ou por uma república. É o príncipe que deve estar presente e assumir o papel de capitão e a república deve enviar um de seus próprios cidadãos; e se aquele que foi escolhido não for valente o suficiente, ela deverá substituí-lo; e se, ao contrário, ele tiver essa qualidade, a república deverá restringi-lo para que não ultrapasse os limites.8 A experiência demonstrou que os príncipes sozinhos e as repúblicas armadas fizeram grandes progressos, enquanto os mercenários somente causaram danos.9 Isso também demonstra que a república que conta com as próprias tropas corre menos risco de ser subjugada por um de seus cidadãos10 que por tropas externas.","page":61},{"type":"paragraph","text":"Durante muitos séculos, Roma e Esparta viveram livres e armadas. Os suíços também são bem armados e livres. Dentre os mercenários antigos, podemos citar como exemplo os cartagineses, que depois da primeira guerra contra Roma, estavam a ponto de ser oprimidos por seus soldados mercenários, apesar de ser comandados por cidadãos de Cartago. Depois da morte de Epaminondas, os tebanos confiaram o comando a Filipe da Macedônia, que depois da vitória aproveitou para tirar-lhes a liberdade. Com a morte do duque Filipe, os milaneses empregaram Francisco Sforza para lutar contra os venezianos, e depois de derrotá-los em Caravaggio, aliou-se aos próprios para oprimir os milaneses que o haviam contratado.11 O pai desse mesmo Sforza, a serviço da rainha Joana de Nápoles, deixou-a repentinamente indefesa; de maneira que, para não perder seu reino, foi forçada a jogar-se nos braços do rei de Aragão.12","page":61},{"type":"paragraph","text":"E se os florentinos e os venezianos conseguiram aumentar seus domínios com esse tipo de exército e seus capitães não os subjugaram, mas os defenderam,13 posso responder que os florentinos foram favorecidos pela sorte, porque dentre todos os capitães valorosos que podiam temer, alguns foram derrotados,14 outros sofreram oposição15 e ainda outros voltaram seus interesses para outros lugares.16","page":62},{"type":"paragraph","text":"Um dos capitães que não conseguiram ter sucesso foi Giovanni Acuto, que por não ser vitorioso, sua lealdade não era conhecida e não fora colocada à prova; mas é preciso confessar que se ele houvesse obtido êxito, os florentinos teriam ficado à sua mercê. Sforza sempre teve a oposição dos Braccio, rivalidade que fazia com que se vigiassem.17 Finalmente, Francisco18 voltou sua ambição sobre a Lombardia e Braccio voltou-se contra a Igreja e o reino de Nápoles.","page":62},{"type":"paragraph","text":"Mas vejamos o que aconteceu recentemente.19 Os florentinos nomearam Paulo Vitelli como seu capitão, um homem muito prudente que, de civil, acabara conseguindo uma grande reputação. Se ele viesse a conquistar Pisa, ninguém poderia negar que convinha aos florentinos mantê-lo em sua posição, pois se ele se aliasse aos inimigos, eles não teriam mais recursos; e se continuassem a mantê-lo a seu serviço, seriam forçados a obedecer-lhe.20","page":62},{"type":"paragraph","text":"Quanto aos venezianos, ao considerar seu progresso, é possível observar que agiram de maneira segura e gloriosa ao combater por conta própria com gentishomens e a plebe armada, que lutaram com bravura.21 Mas quando voltaram seus interesses para a terra, abandonaram essa virtude e seguiram os costumes da guerra na Itália. No início, devido ao fato de possuírem pouco território, mas uma grande reputação, eles não tinham por que temer seus capitães. No entanto, à medida que ampliaram seus domínios, perceberam o erro que haviam cometido. Isso aconteceu com o capitão Carmagnola. Cientes que eram do grande valor das vitórias conseguidas sobre o duque de Milão,22 mas, por outro lado, percebendo quanto ele se desmotivara no modo de guerrear, julgaram que nada mais conseguiriam enquanto vivesse. E como não o poderiam demitir com medo de perder o que haviam conquistado, chegaram à conclusão de que, por segurança, era necessário matá-lo. E foi o que fizeram.23","page":62},{"type":"paragraph","text":"Em seguida, tiveram como capitães Bartolomeo de Bérgamo, Roberto de Sanseverino, conde de Pitigliano e outros semelhantes, com os quais teriam menos que temer as conquistas e muito mais suas derrotas, como ocorreu, mais tarde, em Vailá, quando num só dia perderam tudo que haviam conquistado com tanto afinco em 800 anos.24 Pois com essa espécie de exércitos conseguem-se apenas conquistas lentas, tardias e fracas, e rápidas e milagrosas perdas. E como me baseei em exemplos ocorridos na Itália, que durante muitos anos foi governada por armas mercenárias, é preciso que eu as discuta de um nível mais alto a fim de que, conhecendo a origem e os progressos das mesmas, seja possível prover o melhor remédio.25","page":63},{"type":"paragraph","text":"É preciso, então, entender que nesses últimos tempos, durante os quais o império começara a ser repelido na Itália,26 e o papa, no poder temporal, conseguira reputação, a Itália foi dividida em vários Estados27 porque muitas das grandes cidades pegaram em armas contra seus nobres, que as tinham mantido oprimidas enquanto eram favorecidos pelo imperador. Agora livres, os cidadãos eram favorecidos pela Igreja, que, por seu lado, procurava melhorar a reputação que havia adquirido.28 Em outras cidades, muitos cidadãos tornaram-se príncipes.29 Assim, quase toda a Itália veio a ser dominada pela Igreja e por algumas repúblicas.30 Mas, pelo fato de o clero e os pacíficos habitantes desconhecerem o uso das armas, começaram a contratar exércitos estrangeiros. O primeiro capitão que tornou famosa essa milícia foi Alberico de Conio, nativo da Romanha, sendo que de sua escola surgiram, entre outros, Braccio e Sforza, que foram, em suas épocas, os árbitros da Itália. Em seguida vieram todos os outros que, até nossos dias, chefiaram os nossos exércitos.31 A consequência de suas virtudes foi a Itália ser atacada por Carlos, saqueada por Luís, invadida por Fernando (o Católico) e humilhada pelos suíços.32 O método seguido por esses capitães consistia principalmente em privar a infantaria de qualquer consideração. Isso eles fizeram por não possuir nenhum domínio e por não poderem alimentar um grande número de soldados;33 além disso, a infantaria não lhes proporcionava nenhuma fama. Por conseguinte, deram maior importância à cavalaria, cujos números menores permitiam que fossem mais bem alimentados e respeitados. A situação chegou a tal ponto que, num exército de 20 mil homens, apenas 2 mil faziam parte da infantaria.34","page":63},{"type":"paragraph","text":"Além disso, esses capitães utilizavam todos os meios para se proteger e, ao mesmo tempo, poupar seus homens de qualquer medo e de todo cansaço fazendo com que não se matassem uns aos outros, mas se rendessem para, a seguir, ser libertados sem resgate.35 À noite não havia investidas nem por parte dos sitiantes nem por parte dos sitiados. Os acampamentos não eram protegidos por fossos ou por estacas, e no inverno não se aventuravam a guerrear. Todas essas regras militares haviam sido engendradas a fim de permitir que fugissem, como foi dito, do esforço e do perigo.36. Assim a Itália foi levada à escravidão e à humilhação.37","page":64},{"type":"heading","lvl":2,"title":"XIII Dos exércitos auxiliares, mistos e próprios","id":"h_o_pr_ncipe_nicolau_maquiavel_21","page":65},{"type":"paragraph","text":"XIII","page":65},{"type":"paragraph","text":"Dos exércitos auxiliares, mistos e próprios","page":65},{"type":"paragraph","text":"As armas auxiliares, que incluí como inúteis, são aquelas com que um potentado é chamado para que com seu exército preste ajuda na defesa,1 como fez recentemente o papa Júlio, que presenciando o triste desempenho de suas tropas mercenárias, dirigiu-se a Fernando, rei da Espanha, para que fosse em sua ajuda com seus exércitos. Essas tropas auxiliares podem ser benéficas apenas para si mesmas,2 mas para quem as contrata são quase sempre prejudiciais, pois o contratante, sendo vencido, estará liquidado, e vencendo, se tornará prisioneiro de quem o ajudou.3","page":65},{"type":"paragraph","text":"Embora a história antiga esteja repleta de exemplos,4 quero ainda me referir a esse exemplo recente do papa Júlio II. Se a decisão que ele tomou, a de colocar-se completamente nas mãos de um estrangeiro para conquistar Ferrara, não o prejudicou foi porque sua boa sorte fez que uma terceira causa5 o preservasse dessa sua terrível determinação.","page":65},{"type":"paragraph","text":"Apesar da derrota de suas tropas auxiliares pelos franceses em Ravena, o exército de suíços que ia em sua ajuda, contra a expectativa de todos, conseguiu expulsar os vencedores (os franceses) e o papa não foi feito prisioneiro por seus inimigos pelo simples motivo de estarem em fuga, nem pelas tropas auxiliares, pois ele havia vencido realmente,6 embora com as armas de outros.","page":65},{"type":"paragraph","text":"Totalmente desarmados, os florentinos levaram 10 mil franceses para se apoderar de Pisa. Essa decisão os colocou em riscos que jamais correram em qualquer outra empresa militar.","page":65},{"type":"paragraph","text":"Para resistir aos seus vizinhos, Constantinopla enviou 10 mil turcos para a","page":65},{"type":"paragraph","text":"Grécia, os quais, depois de vencida a guerra, não a quiseram mais abandonar,7 o que deu início à servidão grega sob o domínio turco.8","page":66},{"type":"paragraph","text":"Portanto, aquele que acredita ser impotente de vencer9 deve valer-se dessas tropas auxiliares, que são muito mais perigosas que as mercenárias e que com certeza o levarão à ruína, pois elas são unidas e voltadas à obediência de outros; enquanto as tropas mercenárias, depois da vitória, levam mais tempo para agir contra quem as contrata, aguardando o momento e a ocasião mais propícios. Elas não formam um contingente uniforme e, além disso, dependem do salário que recebem, e o comandante que lhes tenha sido imposto não será capaz, em tão pouco tempo, de conseguir autoridade suficiente para poder controlá-las. Ou seja, das tropas mercenárias é preciso temer a covardia; das tropas auxiliares, o valor.10","page":66},{"type":"paragraph","text":"Assim, o príncipe sábio sempre evitou usar essas tropas auxiliares valendo-se de suas próprias armas, preferindo ser derrotado com elas a vencer com tropas estrangeiras das quais se tornaria devedor. Nunca hesitarei em citar11 o exemplo de César Bórgia e de suas ações. Esse duque entrou na Romanha com tropas auxiliares compostas de forças francesas com as quais conquistou Ímola e Forli.12 Entretanto, julgando-as inseguras, voltou-se para os mercenários acreditando serem menos perigosos e tomando a seu serviço os Orsini e os Vitelli. Mais tarde, julgando-as ainda inseguras, infiéis e perigosas, decidiu destruí-las e passou a contar com o seu próprio exército.13","page":66},{"type":"paragraph","text":"A diferença entre esses tipos de armas foi demonstrada pela diferença entre a reputação que tinha o duque quando se serviu dos franceses, dos Orsini e dos Vitelli e aquela que conseguira quando passou a contar com seus próprios soldados. A partir desse último momento, sua reputação continuou crescendo e sua estima ficou evidente quando todos perceberam que ele se tornara senhor absoluto de suas próprias tropas.","page":66},{"type":"paragraph","text":"Eu queria me ater aos recentes exemplos italianos, mas não posso deixar de lembrar aqui o exemplo de Hierão de Siracusa, que já mencionei anteriormente.14 Colocado à testa dos exércitos siracusanos, Hierão logo reconheceu a inutilidade das tropas mercenárias, pois seus chefes seguiam os mesmos métodos dos condottieri italianos. Convencido de que não poderia confiar neles nem tampouco dispensá-los, decidiu matá-los15 e, em seguida, seguiu guerreando com suas próprias tropas, e não com as de terceiros.16 A esse propósito, quero ainda chamar à memória um personagem do Antigo Testamento.17 Davi ofereceu-se a Saul para lutar contra Golias, o provocador filisteu. A fim de encorajá-lo, Saul o revestiu com suas próprias armas mas depois de experimentá-las, Davi recusou-as dizendo que elas atrapalhariam o uso de suas forças pessoais e que queria confrontar Golias com sua faca e atiradeira. De fato, as armas alheias podem ser mais pesadas no corpo, impedindo a liberdade de movimentos.","page":66},{"type":"paragraph","text":"Carlos VII, pai do rei Luís XI, havendo com sua fortuna e virtude libertado a França dos ingleses, reconheceu a necessidade de possuir exércitos próprios18 e formou, em seu reino, companhias regulares de cavalaria e de infantaria. Posteriormente, o rei Luís, seu filho, extinguiu a infantaria e começou a contratar os suíços; mas esse erro, que foi seguido por outros, foi a causa, como é possível ver, dos perigos que a França passou a enfrentar. Assim, ao armar os suíços,19","page":67},{"type":"paragraph","text":"Luís praticamente aviltou suas próprias tropas. Ele primeiro eliminou a infantaria, depois subordinou a cavalaria ao comando de outros. E assim, acostumada a militar com os suíços, a cavalaria não acreditava poder vencer sem tê-los a seu lado. Decorre, então, que os franceses não podiam enfrentar os suíços e que sem os suíços eles não podiam enfrentar tropas inimigas.20 Donde resulta que os exércitos franceses são mistos; parte mercenários e parte próprios, os quais, juntos, são muito melhores que tropas unicamente auxiliares ou unicamente mercenárias, mas muito inferiores às tropas próprias.21 E esse exemplo é suficiente para afirmar que o exército francês seria insuperável se a ordem de Carlos VII houvesse sido aperfeiçoada ou preservada.22 Porém, a pouca prudência dos homens se deixa seduzir pela bondade aparente sem perceber o veneno que esta encobre, como essas febres éticas a respeito das quais já me expressei.","page":67},{"type":"paragraph","text":"Portanto, o príncipe que não consegue perceber o mal logo de início não é verdadeiramente dotado dessa sabedoria que é própria de apenas alguns homens.23 E se considerarmos o início da queda do Império Romano, verificaremos que ele certamente se encontra na introdução do emprego dos godos; a partir desse momento, as forças romanas começaram a declinar,24 de maneira que todo o valor que perdiam revertia a favor dos bárbaros.","page":67},{"type":"paragraph","text":"Concluo, então, que sem armas próprias nenhum principado está seguro,25 pois, indefeso contra a adversidade, ele depende exclusivamente da sorte. Além disso, sempre foi a opinião e o julgamento dos homens sábios: quod nihil sit tam infirmum aut instabile quam fama potentiae non sua vi nixa (nada é mais frágil e mais instável que a fama de uma potência que não se fundamenta sobre suas próprias forças). E as armas próprias são aquelas compostas de súditos ou de cidadãos ou de criaturas do príncipe. Todas as outras são mercenárias ou auxiliares. A forma de organizar as próprias armas será fácil de encontrar26 ao refletir sobre a organização dos quatro personagens que acabei de apresentar e ao considerar a maneira pela qual Filipe, o pai de Alexandre Magno, e muitas repúblicas e príncipes se armaram e se organizaram. A esses exemplos eu me refiro integralmente pelas instruções que deles podem ser extraídas.27","page":68},{"type":"heading","lvl":2,"title":"XIV Das competências militares de um príncipe","id":"h_o_pr_ncipe_nicolau_maquiavel_22","page":69},{"type":"paragraph","text":"XIV","page":69},{"type":"paragraph","text":"Das competências militares de um príncipe","page":69},{"type":"paragraph","text":"Um príncipe deve ter como único objetivo e pensamento a arte da guerra, sua organização e a sua disciplina,1 pois essa é a única arte que compete a quem comanda. Sua virtude não somente mantém os que nasceram príncipes, mas também, tal como ocorreu muitas vezes, os homens de condição privada que conseguiram alcançar essa posição.2 Também pudemos ver soberanos perderem seus Estados por haver negligenciado as armas,3 dando preferência às delícias oferecidas pela vida na corte. Negligenciar a arte da guerra é o primeiro passo para a ruína; professá-la corretamente é o meio de elevar-se ao poder. Foi assim que Francisco Sforza, de cidadão, tornou-se duque de Milão,4 e também foi assim que seus filhos, para fugir do incômodo das armas, de duques tornaram-se cidadãos privados comuns.5","page":69},{"type":"paragraph","text":"Para um príncipe, uma das mais tristes consequências da negligência dessa arte é ser desprezado6, uma infâmia que deve ser evitada, conforme discutirei mais adiante. De fato, entre um homem armado e um homem desarmado há uma imensa desproporção, e não é lógico que o homem armado obedeça voluntariamente ao homem desarmado,7 assim como um homem desarmado não se sentirá seguro entre servidores armados,8 sendo que de um lado existe o desprezo e do outro lado a suspeita. É impossível que esses servidores possam conviver em harmonia.9 Ao mesmo tempo, o príncipe que nada entenda de militarismo, além dos infortúnios já mencionados, não terá a estima de seus soldados nem tampouco poderá confiar neles.10","page":69},{"type":"paragraph","text":"Portanto, o príncipe não pode pensar em outra coisa senão no exercício da guerra, principalmente em tempo de paz, o que ele pode fazer de duas maneiras:","page":69},{"type":"paragraph","text":"exercitando o corpo e exercitando a mente. O corpo, ele exercitará, em primeiro lugar, treinando e organizando as suas tropas, e, em segundo lugar, caçando constantemente e sujeitando-se ao desconforto e aprendendo, ao mesmo tempo, a conhecer a conformação dos lugares, a elevação das montanhas, a direção dos vales, a localização das planícies, a natureza dos rios e dos pântanos,11 prestando muita atenção a tudo. Esse conhecimento lhe proporcionará duas grandes vantagens: a primeira é que, conhecendo bem o próprio país, ele terá melhores condições de se defender; a segunda é que o conhecimento de um país torna bem mais fácil conhecer outro que possa ser necessário especular, pois as colinas, os vales, as planícies, os rios e os pântanos que existem, por exemplo, na Toscana têm certa semelhança com os de outras províncias, o que facilita o conhecimento de outros locais da região.12 Aliás, esse conhecimento é muito importante. Ao príncipe que não o tenha faltará uma das primeiras qualidades que um capitão deve possuir, pois é por meio desse conhecimento que ele saberá descobrir o inimigo, onde situar seu acampamento, dirigir a marcha de suas tropas, tomar posições vantajosas para uma batalha e a melhor estratégia para fazer investidas sobre o inimigo.13","page":70},{"type":"paragraph","text":"Dentre os elogios que foram dedicados a Filopêmenes, príncipe dos aqueus, os historiadores o elogiam principalmente pelo fato de ele pensar exclusivamente na arte da guerra14; e quando estava no campo com amigos, parava muitas vezes e raciocinavam juntos: se os inimigos estivessem em cima dessa colina e nós nos encontrássemos aqui com nosso exército, de quem seria a vantagem? Como poderíamos atacá-los mantendo a ordem das tropas? Se quiséssemos bater em retirada, de que forma deveríamos fazê-lo? E se eles se retirassem, como deveríamos persegui-los?15 E, caminhando, ele sugeria casos que um exército poderia vir a enfrentar, ouvia suas opiniões, colaborava com argumentos, de tal maneira que por meio de suas cogitações nenhum acidente poderia acontecer sem que ele tivesse a solução adequada.16","page":70},{"type":"paragraph","text":"Mas quanto ao exercício da mente, o príncipe deve ler os historiadores,17 considerar as ações dos grandes personagens, analisar suas condutas nas guerras, examinar as causas de suas derrotas e de suas vitórias a fim de evitar umas e imitar outras. Deve fazer o que muitos homens fizeram tomando por modelo algum herói célebre que foi louvado e glorificado, mantendo na memória18 suas","page":70},{"type":"paragraph","text":"ações e sua conduta e tomando-as como princípios, tal como se diz que Alexandre Magno imitava Aquiles, César a Alexandre e Cipião a Ciro. Quem se dignar a ler a vida de Ciro, escrita por Xenofonte, reconhecerá na vida de Cipião o quanto a sua proposta imitação contribuiu para a sua glória e o quanto, na castidade, na amabilidade, na humanidade e na liberalidade, Cipião se assemelhava em tudo o que havia sido escrito por Xenofonte em seu livro Ciropédia.19","page":71},{"type":"paragraph","text":"Eis como deve se comportar um príncipe sábio e, em tempo de paz, longe de ficar ocioso, ele pode aproveitar esse período investindo na prevenção contra possíveis adversidades da sorte a fim de estar preparado para enfrentá-las.","page":71},{"type":"heading","lvl":2,"title":"XV Das coisas pelas quais os homens, e especialmente os príncipes, são louvados ou vituperados","id":"h_o_pr_ncipe_nicolau_maquiavel_23","page":72},{"type":"paragraph","text":"Das coisas pelas quais os homens, e especialmente os príncipes, são","page":72},{"type":"paragraph","text":"louvados ou vituperados","page":72},{"type":"paragraph","text":"Resta agora examinar como um príncipe deve se comportar e proceder, seja com seus súditos, seja com seus amigos. Sei que muitos autores já escreveram a esse respeito, e possivelmente serei taxado de presunçoso por insistir em escrever sobre esse mesmo assunto, ainda mais que estarei contestando princípios apresentados por outros escritores.1 Mas, como a minha intenção é escrever algo de útil para quem realmente se interessa, pareceu-me mais conveniente tratar diretamente da verdade efetiva2 dos fatos do que apenas discutir fantasias imaginativas.3 Muitas pessoas imaginaram repúblicas e principados como nunca vimos e nem tampouco existiram,4 pois estão tão longe da realidade de como se vive e daquela imaginada que deveríamos viver, a ponto de a pessoa que se propõe a aplicar em sua vida esse último método apenas percorrerá o caminho da ruína em vez de se preservar, e a pessoa que se propõe a professar apenas o bem perecerá no seio de tantas outras que professam o oposto.5 Portanto, é preciso que o príncipe que queira manter a sua posição aprenda a nem sempre ser bom e a fazer uso da bondade segundo a necessidade.6","page":72},{"type":"paragraph","text":"Por conseguinte, deixemos de lado os deveres de um príncipe imaginário e tratemos do que é real. Portanto, quando analisados, atribui-se a todos os homens e, principalmente, aos príncipes, por serem mais proeminentes, algumas das seguintes qualidades pelas quais eles são elogiados ou aviltados. Assim, alguns têm a reputação de ser liberais enquanto outros são considerados miseráveis (usando o termo toscano, pois avaro em nossa língua é aquele que deseja possuir por meio da pilhagem, enquanto por miserável denominamos aquele que constantemente se abstém de usar o que possui); alguns são considerados pródigos, enquanto outros são rapinantes; alguns cruéis e outros piedosos; alguns desleais e outros fiéis à palavra; alguns efeminados e fracos, e outros ferozes e corajosos; alguns humanos e outros orgulhosos; alguns dissolutos e outros castos; alguns francos e outros astutos; alguns rígidos e outros complacentes; alguns sérios e outros levianos; alguns religiosos e outros ateus, e assim por diante.7","page":72},{"type":"paragraph","text":"Sei que todos dirão que seria muito louvável para um príncipe ter todas as boas qualidades8 descritas acima, mas como isso não é possível devido às próprias contingências das condições humanas, que não o permitem, é preciso que ele seja prudente o suficiente para evitar a infâmia das más qualidades que causariam a perda de seu Estado, e daquelas que não a viessem a causar,9 precaver-se, se for possível; no caso contrário, deixar de lado como sendo uma preocupação menor.10 Além disso, é preciso cuidar para não incorrer na infâmia dos vícios que colocariam em risco a sua posição. Caso contrário, é possível tolerá-los, mas com a quebra do devido respeito. Ele também não deve temer incorrer na infâmia de certos vícios sem os quais seria difícil salvar o Estado, pois analisando o todo, descobre-se que existem qualidades que, parecendo virtudes, levariam o príncipe à ruína, assim como há outras que parecem ser vícios, mas por meio das quais é possível conseguir segurança e bem-estar.","page":73},{"type":"heading","lvl":2,"title":"XVI Da liberalidade e da parcimônia","id":"h_o_pr_ncipe_nicolau_maquiavel_24","page":74},{"type":"paragraph","text":"XVI","page":74},{"type":"paragraph","text":"Da liberalidade e da parcimônia","page":74},{"type":"paragraph","text":"Começando, então, pelas primeiras qualidades antes mencionadas, digo que será bom para um príncipe ser reputado liberal. Contudo, a liberalidade pode ser exercida de tal maneira que possa vir a ser-lhe prejudicial, pois usada discreta e sabiamente, ela não se tornará conhecida1 e não garantirá ao príncipe a imputação de sua qualidade contrária. Por outro lado, se ele quiser obter a fama de liberal, é preciso que não tenha nenhuma reserva quanto à suntuosidade, de maneira que, assim procedendo, consumirá em ostentação toda a sua fortuna, e se ainda quiser manter essa reputação, será forçado, afinal, a cobrar mais impostos de seus súditos e a fiscalizá-los, e fazer de tudo para conseguir mais fundos, fazendo que se torne odiado pelo povo e pouco estimado por todos.2 E assim, havendo premiado poucos e ofendido muitos, a mínima dificuldade o colocará em perigo,3 colocando em risco o seu domínio,4 e caso reconheça seu erro e queira desistir dessa sua liberalidade, apenas conseguirá a má fama de miserável.5","page":74},{"type":"paragraph","text":"Não podendo, então, exercer a liberalidade de maneira que seja conhecida sem ser prejudicado, o príncipe prudente deve tomar o cuidado de não ser taxado de miserável e, com o tempo, será considerado cada vez mais liberal; as pessoas perceberão que, com sua parcimônia, sua receita é suficiente para se defender de quem lhe declara guerra, para promover empreendimentos sem sobretaxar os súditos,6 e será reputado liberal pelas infinitas pessoas das quais nada tira, assim como será considerado miserável7 por aqueles poucos a quem nada proporciona. Em nossa época, não temos visto grandes realizações senão pelos príncipes que foram reputados miseráveis, enquanto vimos os outros serem obscurecidos. Para poder alcançar o papado, o papa Júlio II fez uso da reputação de liberal para subir ao trono,8 porém, nunca pensou em consolidá-la para poder guerrear. O atual rei da França fez muitas guerras sem nunca estabelecer impostos adicionais aos seus súditos,9 mas soube ser parcimonioso com as despesas supérfluas. Se o atual rei da Espanha fosse reputado liberal, não teria realizado nem vencido tantas guerras.10","page":74},{"type":"paragraph","text":"Portanto, um príncipe precisa medir seus gastos para não ter de roubar os súditos a fim de poder se defender e para não ficar pobre e desprezado, temendo tornar-se rapinante ou ser reputado miserável, porque esse é um dos vícios que permitem que ele reine.11 Se alguém dissesse que César chegou a ser imperador de Roma por sua grande liberalidade,12 assim como muitos outros alcançaram postos elevados devido à liberalidade, eu responderia: ou o indivíduo já é, efetivamente, um príncipe ou está em vias de sê-lo. No primeiro caso, essa liberalidade é prejudicial; no segundo caso, é preciso que ele tenha essa reputação.13 César era um daqueles que pretendiam chegar ao principado de Roma. Entretanto, depois de conseguir o seu intento, tivesse ele conseguido viver mais tempo e não houvesse moderado seus gastos, ele mesmo teria derrubado o Império Romano. E se alguém replicasse que muitos foram os príncipes considerados muito liberais, que com exércitos fortes realizaram grandes feitos,14 eu responderia: ou o príncipe gasta o que é seu ou de seus súditos, ou então gasta o que é de outros; no primeiro caso, ele deve ser parcimonioso; no segundo caso, é necessário que seja reputado liberal.15","page":75},{"type":"paragraph","text":"De fato, o príncipe que com seus exércitos vive dos despojos de pilhagens, de saques e de resgates, e manipula os bens alheios, precisa dessa liberalidade; do contrário, seus soldados não o seguirão16. E do que não lhe pertence nem tampouco pertença aos seus súditos pode ser o mais generoso dos doadores, tal como foram Ciro, César e Alexandre17, pois gastar o que é dos outros não prejudica a reputação do príncipe, ao contrário, isso faz que ela aumente.18 É a prodigalidade de seus próprios bens que o pode prejudicar. Acima de tudo, é a liberalidade que devora a si própria, pois à medida que é exercida perde-se a habilidade de exercê-la, ainda mais fazendo que o príncipe se torne pobre e desprezado ou rapinante e odioso19 para fugir da pobreza.20 Dentre as coisas que um príncipe deve evitar a qualquer custo é ser desprezado e odiado, e é a essas duas consequências que a liberalidade conduz. Portanto, é mais sábio ser considerado miserável, o que não provoca o ódio e o desprezo, que optar pelo conceito de ser liberal e incorrer na possibilidade de ser qualificado como rapinante, o que gera a infâmia e o ódio.21","page":75},{"type":"heading","lvl":2,"title":"XVII Da crueldade e da clemência. É melhor ser amado ou temido?","id":"h_o_pr_ncipe_nicolau_maquiavel_25","page":77},{"type":"paragraph","text":"XVII","page":77},{"type":"paragraph","text":"Da crueldade e da clemência. É melhor ser amado ou temido?","page":77},{"type":"paragraph","text":"Seguindo adiante com as qualidades anteriormente enunciadas, digo que todo príncipe deseja ser considerado clemente e não cruel; porém, deve tomar o cuidado de não usar essa clemência e piedade inadequadamente.1 César Bórgia era considerado cruel, mas sua crueldade fez que conquistasse a Romanha, conseguiu uni-la e restabeleceu a ordem e a paz.2 Se considerarmos esse exemplo, verificaremos que ele foi mais clemente que o povo florentino, o qual, para evitar ser taxado de cruel, deixou que Pistoia fosse destruída.","page":77},{"type":"paragraph","text":"Portanto, um príncipe não deve temer a fama de cruel3 quando se trata de manter os súditos unidos e leais, pois com bem poucos exemplos demonstrará ser mais clemente que aqueles que, por excesso de clemência, deixam que a desordem impere, dando origem aos crimes e às rapinas que costumam prejudicar uma sociedade inteira; por outro lado, o rigor de um príncipe considerado cruel recai apenas sobre determinados indivíduos.4 E dentre todos os príncipes, é ao príncipe novo que é impossível fugir à reputação de cruel,5 porque nos Estados novos os perigos são muitos. Para desculpar a desumanidade do seu reinado,6 por ser novo, pela boca de Dido, Virgílio diz:","page":77},{"type":"paragraph","text":"Res dura, et regni novitas me talia cogunt moliri, et late fines custode tueri.","page":77},{"type":"paragraph","text":"(A dura necessidade e a novidade do reino me obrigam a adotar tais medidas e a defender com ampla guarda as fronteiras.)*","page":77},{"type":"paragraph","text":"Não obstante, o príncipe deve ser ponderado em suas reflexões e em seus movimentos sem criar medos imaginários,7 e proceder de maneira moderada, com prudência e humanidade, para que a excessiva confiança não o torne incauto e a excessiva desconfiança não o torne intolerável.8","page":78},{"type":"paragraph","text":"Daí nasce a seguinte questão: é melhor ser amado ou temido?9 A resposta seria que as duas vocações são necessárias; mas, como é difícil ser as duas coisas ao mesmo tempo, é mais seguro ser temido que amado10 quando é preciso renunciar a uma das duas, porque, de modo geral, é possível dizer que os homens são ingratos, volúveis, simuladores e dissimuladores, fogem do perigo e são sempre ávidos por ganhos;11 e, enquanto favorecidos, oferecem ao príncipe o próprio sangue, os bens, a vida, os filhos,12 desde que, conforme disse anteriormente, a necessidade esteja longe deles. Mas quando ela se aproxima, eles se revoltam. E o príncipe que se apoiou em suas promessas,13 totalmente despreparado de outros meios de defesa, cai na ruína, pois nas amizades adquiridas por meio de favores e não com grandeza e nobreza de alma14 — e, por conseguinte, compradas — não se pode confiar em momentos de necessidade. Além disso, os homens têm menos escrúpulos em ofender alguém que se faça amar do que em ofender aquele que se faz temer,15 pois o amor emana de um vínculo que se baseia na obrigação, vínculo que é quebrado pela própria maldade humana em todas as oportunidades que aos homens convier, enquanto o temor emana do medo do castigo, que jamais os abandonará.16","page":78},{"type":"paragraph","text":"Contudo, o príncipe deve fazer-se temer, de maneira que se lhe for impossível fazer-se amar, que evite o ódio,17 porque ser temido e não ser odiado podem coexistir perfeitamente. Isso ele conseguirá desde que se abstenha de apossar-se dos bens de seus cidadãos, de seus súditos e de suas mulheres.18 E, se apesar de tudo for necessário derramar o sangue de alguém, que o faça quando existir justificativa conveniente e causa manifesta.19 Mas, acima de tudo, deve abster-se sempre de apoderar-se dos bens alheios, porque os homens esquecem mais rapidamente a morte do pai que a perda de seu patrimônio.20 Além disso, nunca faltam oportunidades para arrebatar os bens alheios,21 e aquele que começa a viver de rapina encontrará sempre motivos para apropriar-se deles.22","page":78},{"type":"paragraph","text":"Por outro lado, os motivos para o derramamento de sangue são mais raros e esquecidos mais rapidamente.23","page":78},{"type":"paragraph","text":"Mas quando o príncipe se encontra à frente e tem sob o seu comando uma multidão de soldados, então é absolutamente necessário que não se preocupe com a fama de cruel, pois, sem ela, não conseguirá manter unido o exército nem tampouco disposto a alguma investida.24 Dentre as admiráveis ações de Aníbal enumera-se precisamente esta: à frente de um imenso exército constituído por homens de diversas raças e levado a combater em terras longínquas,25 nunca surgiu nenhuma dissensão no seio de suas tropas nem tampouco contra o príncipe,26 tanto nos momentos de boa sorte como nos de má sorte.","page":79},{"type":"paragraph","text":"O fator não era senão a sua desumana crueldade, que combinada às suas infinitas virtudes, sempre o fez temido e respeitado por seus soldados. Sem essa crueldade, suas outras virtudes não teriam sido suficientes para obter suas proezas militares.27 Os historiadores menos ponderados, de um lado, admiravam essa sua atuação, e de outro, condenavam sua causa principal.28 Para provar que a afirmação de que as suas outras virtudes não teriam sido suficientes basta considerar o caso de Cipião, homem notável não somente em sua época, mas na memória de todos os fatos conhecidos,29 contra quem o seu exército se revoltou na Espanha em consequência de sua excessiva clemência, havendo concedido aos seus soldados mais liberdade do que convinha à disciplina militar.30 Esse fato levou-o a ser censurado no Senado por Fábio Máximo, que o chamou de corruptor das tropas romanas. Tendo os locrenses sido destruídos e abatidos por um legado de Cipião, este não puniu tal agravo nem tampouco reprimiu a insolência desse legado, devido a essa sua natureza fácil e flexível; tanto assim que alguém pretendeu desculpá-lo no Senado dizendo que havia homens que sabiam melhor como não cometer erros do que como corrigi-los.31 Essa sua natureza teria, com o tempo, manchado sua fama e glória se houvesse perseverado no exercício do comando; mas, atuando sob as ordens do Senado, essa sua prejudicial peculiaridade não somente foi ocultada como, ao contrário, rendeulhe glória.32","page":79},{"type":"paragraph","text":"Voltando à questão de ser amado ou temido, concluo, pois, que os homens amam segundo a sua própria vontade e que temem segundo a vontade do príncipe; de maneira que um príncipe sábio deve se basear no que depende dele,33 e não no que depende dos outros, e apenas empenhar-se, como foi dito, em evitar o ódio.34","page":79},{"type":"heading","lvl":2,"title":"XVIII Da maneira pela qual os príncipes devem honrar a sua palavra","id":"h_o_pr_ncipe_nicolau_maquiavel_26","page":80},{"type":"paragraph","text":"XVIII","page":80},{"type":"paragraph","text":"Da maneira pela qual os príncipes devem honrar a sua palavra","page":80},{"type":"paragraph","text":"Todos sabem quão louvável é o príncipe que cumpre com a palavra dada e que vive com integridade e não com astúcia;1 contudo, a experiência de nossos tempos demonstra que são precisamente os príncipes que muito realizaram os que menos mantiveram a palavra dada, e que souberam por meio da astúcia2 transtornar a mente dos homens.3 E, afinal, conseguiram superar aqueles que se fundamentaram na lealdade.","page":80},{"type":"paragraph","text":"Por conseguinte, é preciso saber que existem duas maneiras de combater: uma, com as leis, e a outra, com a força. A primeira é própria do homem,4 enquanto a segunda é própria dos animais. Mas como muitas vezes a primeira não é suficiente, convém, então, recorrer à segunda.5 Portanto, é preciso que um príncipe saiba se comportar como homem e também como animal. Isso é o que foi amplamente ensinado aos príncipes pelos escritores antigos, que descreveram como Aquiles e muitos príncipes antigos foram confiados à educação do centauro Quíron.6 Isso nada mais significa que, como o preceptor é meio homem e meio animal, o príncipe deve ser ensinado a fazer uso das duas naturezas, e que uma não dura muito tempo sem a outra.","page":80},{"type":"paragraph","text":"Para que um príncipe saiba bem empregar a sua natureza animal, precisa tomar como modelo a raposa e o leão, porque a raposa não sabe se defender dos lobos e o leão não sabe se proteger das armadilhas. Portanto, é preciso ser raposa para conhecer as armadilhas e leão para atemorizar os lobos.7 Os príncipes que agem unicamente como leões demonstram apenas a sua pouca experiência.8","page":80},{"type":"paragraph","text":"Assim, o príncipe prudente não deve cumprir com a palavra dada quando essa observância ferir os seus interesses e quando os motivos que o levaram a empenhá-la não mais existirem.9 Se todos os homens fossem bons, este preceito não seria condizente,10 mas como são perversos11 e tampouco cumpririam as promessas que lhe fizeram, assim também o príncipe deve deixar de cumprir a palavra dada. Nunca faltaram a um príncipe motivos legítimos para justificar sua quebra de palavra.12 Também não faltarão ao príncipe razões para justificar a inobservância.13 A esse respeito, seria possível citar muitos exemplos modernos de promessas e de tratados de paz invalidados pela infidelidade dos príncipes.14","page":80},{"type":"paragraph","text":"E aquele príncipe que com mais perfeição imitou a raposa, certamente teve mais sucesso. Porém, é preciso saber bem disfarçar essa qualidade e ser hábil em fingir e dissimular.15 Os homens são tão simples e obedecem de tal forma às necessidades presentes, que aquele que engana encontrará sempre quem se deixa enganar.16","page":81},{"type":"paragraph","text":"Quero aqui apontar um dos exemplos recentes. Alexandre VI nunca fez outra coisa senão enganar os homens e sempre encontrou a oportunidade para poder assim agir.17 Nunca houve homem que tivesse maior eficiência em fazer as mais diversas promessas e tantos juramentos sem jamais cumpri-los. Entretanto, ele sempre conseguia o que desejava por meio dos enganos, pois conhecia muito bem esta parte do mundo.18","page":81},{"type":"paragraph","text":"Portanto, não é necessário que um príncipe possua todas as qualidades já mencionadas, mas é preciso, sim, parecer possuí-las.19 E eu até me atreveria a dizer que possuí-las e praticá-las sempre seria prejudicial, enquanto aparentar possuí-las é útil. Por exemplo: é útil parecer clemente, leal, humano, íntegro, religioso e sê-lo efetivamente,20 porém o príncipe deve estar sempre preparado para agir opostamente caso seja necessário. É preciso entender que um príncipe, e principalmente um príncipe novo, não deve praticar todas as qualidades consideradas boas pelos homens, pois para poder manter o Estado, sempre será forçado a agir contra a lealdade, contra a caridade, contra a humanidade, contra a religião.21 Mas é preciso que tenha um espírito disposto a ficar à mercê dos ventos e das variações determinadas pela sorte e, como já foi dito, procurando sempre fazer o bem,22 mas também estar pronto a praticar o mal sempre que necessário.","page":81},{"type":"paragraph","text":"Com isso quero dizer que um príncipe deve ter muito cuidado em não fazer sair de sua boca algo que não seja repleto das cinco qualidades supracitadas, e ao ser visto e ouvido, parecer ser um homem todo piedoso, todo íntegro, todo humano, todo religioso;23 e não há nada mais necessário do que aparentar essa última qualidade,24 pois os homens, de modo geral, julgam mais pelos olhos que pelas mãos, porque todos têm a capacidade de ver, mas poucos têm a capacidade de sentir o que somos.25 Todos podem ver o que o príncipe parece ser, mas poucos sabem o que ele realmente é, e esses poucos não se atrevem a contestar a opinião dos muitos, que são protegidos pelo Estado;26 e nas ações de todos os homens, e principalmente dos príncipes, contra quem não existe nenhum tipo de apelação, basta aguardar o resultado final. O príncipe deve, então, procurar vencer e manter o Estado, pois os meios serão sempre julgados honrados e louvados por todos porque o vulgo se deixa facilmente enganar pelas aparências e pelos resultados,27 e no mundo predominam os vulgos. Aliás, pouco contam as minorias quando às maiorias falta um arrimo onde se apoiar.28 Um príncipe dos nossos tempos, a quem não convém nomear,* apenas prega a paz e a fé das quais é inimigo ferrenho e, caso as houvesse praticado, seguramente teria perdido mais de uma vez a reputação e o Estado.","page":81},{"type":"heading","lvl":2,"title":"XIX De que maneira é preciso evitar o desprezo e o ódio","id":"h_o_pr_ncipe_nicolau_maquiavel_27","page":83},{"type":"paragraph","text":"XIX","page":83},{"type":"paragraph","text":"De que maneira é preciso evitar o desprezo e o ódio","page":83},{"type":"paragraph","text":"Devido ao fato de haver falado no capítulo anterior sobre as qualidades mais importantes, quero agora referir-me brevemente, e de modo geral, ao assunto do título. O príncipe deve tratar, como já disse, de fugir das coisas que o tornem odiado e desprezado,1 e sempre que o fizer, terá cumprido seu dever e nada terá a temer dos outros vícios.2 Como eu já disse, ele se tornará odiado, acima de tudo, se for rapinador e usurpador dos bens e das mulheres dos súditos, do que deve absolutamente se abster,3 pois não sendo privada de seus bens e de sua honra, a maioria dos homens vive feliz, havendo apenas de combater a ambição de poucos, que pode ser refreada com facilidade de várias maneiras.4","page":83},{"type":"paragraph","text":"Desprezado torna-se o príncipe considerado volúvel, leviano, efeminado, pusilânime e irresoluto, defeitos que devem ser evitados como um barco evita os rochedos e esforçando-se para que em suas ações seja reconhecida a sua grandeza, coragem, seriedade e força.5 Quanto às ações particulares dos súditos, ele deve fazer com que suas determinações sejam irrevogáveis6 e empenhar-se em fazer crer que ninguém o pode enganar ou manipular.7","page":83},{"type":"paragraph","text":"O príncipe capaz de transmitir tal impressão será sempre muito respeitado, e dificilmente se conspira contra alguém que é respeitado, assim como dificilmente se o ataca,8 desde que seja considerado excelente e reverenciado pelos súditos. Um príncipe deve temer duas coisas: uma, de natureza interna, é a rebelião de seus súditos; a outra, de natureza externa, é o ataque de potentados estrangeiros. Dessa última, ele se defende com boas armas e boas alianças, e o príncipe que tem boas armas9 terá sempre boas alianças, assim como a situação se manterá segura sempre que a situação externa seja estável, a menos que esteja sendo abalada por alguma conspiração.10 Assim mesmo, o príncipe que regrou a sua conduta e viveu conforme já me expressei anteriormente, desde que não desista, resistirá sempre a qualquer investida, como ocorreu com Nábis, o espartano, ao qual já me referi. Já quanto aos súditos, embora não exista nenhuma ameaça externa, é preciso cuidar para que não conspirem secretamente. Contudo, esse perigo pode ser conjurado evitando que o príncipe seja odiado ou desprezado e, como insisti várias vezes, empenhando-se por todos os meios em manter o povo satisfeito.11 Um dos mais poderosos remédios disponíveis ao príncipe contra as conspirações é o de não ser odiado pela maioria, pois o conspirador sempre acredita satisfazer o povo com a morte do príncipe;12 por outro lado, se considerar com isso ofendê-lo, ele não optará por tomar esse partido, pois incorreria em muitos perigos.13 A experiência demonstra que muitas foram as conspirações, mas poucas foram bem-sucedidas porque quem conspira não pode agir sozinho e nem tampouco procurar a cumplicidade de quem não esteja descontente;14 além disso, o descontente ficará satisfeito ao serlhe comunicado tal propósito, pelos benefícios que angariaria15 com a oportunidade de denunciá-lo. De maneira que, analisando a questão e percebendo que a conspiração lhe apresenta lucros de um lado16 e perigos do outro,17 a fim de que não venha a trair e se mantenha leal, é preciso que tenha uma grande amizade com o conspirador ou um ódio obstinado contra o príncipe. Em poucas palavras, o conspirador está em constante medo, ciúme e preocupado com um possível castigo, enquanto o príncipe tem a seu favor a majestade do Estado, a autoridade das leis, o apoio de seus amigos e do Estado que o defendem.18 E agregando a isso a benevolência do povo, é impossível haver alguém temerário o suficiente para conspirar contra o príncipe,19 pois, nesse caso, o conspirador não somente deverá temer os perigos que antecedem a execução, como também os que virão a seguir, contra os quais, tendo ainda o povo como inimigo,20 não lhe restará nenhum amparo.","page":83},{"type":"paragraph","text":"A esse respeito, é possível citar inúmeros exemplos,21 mas limito-me a um só, testemunho da memória de nossos pais. Messer Aníbal Bentivoglio, príncipe de Bolonha e avô do presente messer Aníbal, foi assassinado em consequência de uma conspiração tramada pelos Canneschi: de sua família somente messer Giovanni, uma criança de berço, foi salvo. Logo após o homicídio, o povo levantou-se e matou todos os Canneschi. O afeto que o povo tinha pela família Bentivoglio nessa época foi ainda muito além, pois não havendo em Bolonha nenhum membro dessa família em condições de governar o Estado após a morte de Aníbal, os bolonheses souberam da existência de um descendente dos Bentivoglio que vivia em Florença e se dizia filho de um artesão, a quem confiaram o governo dessa cidade e cuja função ele manteve até messer Giovanni atingir a idade para poder governar.22","page":84},{"type":"paragraph","text":"Concluo, portanto, que um príncipe amado por seus súditos23 tem pouco a temer as conspirações, mas quando, ao contrário, eles lhe são adversos e o odeiam, deve temer a tudo e a todos.24 Assim também, os Estados bem governados e os príncipes sábios cuidam sempre em não provocar os grandes25 e em satisfazer o povo,26 mantendo-o feliz, pois esse é um dos assuntos mais importantes que diz respeito a um príncipe.","page":85},{"type":"paragraph","text":"Dentre os reinos bem organizados e governados de nossa época é possível citar o da França, onde há um grande número de boas instituições das quais dependem a liberdade e a segurança do rei. A mais importante dessas instituições é o Parlamento, com sua autoridade.27 De fato, aquele que assim organizou esse reino, que conhecia a ambição e a insolência dos poderosos e quanto era necessário freá-los para poder corrigi-los, e, por outro lado, reconhecendo o ódio da maioria contra os grandes, originado pelo medo, e desejando consequentemente proporcionar segurança ao povo, pensou que fosse oportuno não deixar essa tarefa para o rei a fim de que não incorresse no ódio dos poderosos ao favorecer o povo, e o ódio do povo ao favorecer os poderosos. Foi por isso que ele estabeleceu um terceiro juiz que se encarregasse, sem responsabilidade por parte do rei, de conter os grandes e proteger os pequenos.28","page":85},{"type":"paragraph","text":"Sem dúvida, essa foi a instituição mais sábia e conveniente engendrada para proporcionar segurança ao príncipe e ao reino, e donde é possível extrair outra conclusão digna de nota: o príncipe deve delegar a outras pessoas os encargos que possam ser considerados odiosos, reservando para si próprio os encargos que o agraciem.29 E repito uma vez mais que um príncipe deve estimar os grandes sem fazer-se odiar pelo povo.","page":85},{"type":"paragraph","text":"Ao considerar a vida e a morte de alguns imperadores romanos, é possível que as pessoas tenham a impressão de que certos exemplos sejam contrários a essa minha opinião, e isso pelo fato de que, apesar de terem vivido de maneira exemplar e possuído grandes virtudes, não deixaram de perder seu império e acabaram sendo vítimas de conspirações.","page":85},{"type":"paragraph","text":"Para poder responder a essas questões, apresentarei as qualidades de alguns imperadores a fim de demonstrar que as causas de sua ruína não foram senão aquelas que acabei de expor. Também tomarei em consideração os eventos notáveis para as pessoas que gostam de ler sobre as ações dessa época.30","page":86},{"type":"paragraph","text":"Portanto, creio ser suficiente considerar os imperadores que sucederam ao império desde Marco Aurélio, o filósofo, até Maximino, ou seja: Marco Aurélio, seu filho Cômodo, Pertinax, Dídio Juliano, Sétimo Severo, seu filho Antonino Caracala, Macrino, Heliogábalo, Alexandre e Maximino.","page":86},{"type":"paragraph","text":"Inicialmente, é preciso notar que enquanto nos outros Estados o príncipe deve apenas enfrentar a ambição dos grandes e a insolência dos povos, os imperadores romanos deviam, ainda, superar uma terceira dificuldade: defenderse da crueldade e ambição dos soldados. Essa terceira dificuldade foi tão grande que causou a ruína de muitos príncipes, pois era muito difícil31 satisfazer ao mesmo tempo o povo e os soldados, porque os povos amavam a paz e, consequentemente, preferiam os príncipes moderados.32 Os soldados, ao contrário, amavam o príncipe de ânimo militar, insolente, cruel, ambicioso, que exercesse essas violências33 contra os povos a fim de duplicar seus salários e dar vazão à sua sede por crueldade. Desses fatos resultou a ruína daqueles imperadores que, por natureza ou por arte, não possuíssem uma grande reputação na maneira de controlar o povo e os soldados ao mesmo tempo.34 A maioria desses imperadores, principalmente os homens que recém-alcançavam o principado, percebendo a dificuldade decorrente desses dois sentimentos, tendia a satisfazer os soldados,35 sem se preocupar com a opressão do povo. Esse partido era necessário porque os príncipes, não podendo deixar de ser odiados36 por alguém, deviam procurar não ser odiados pela multidão,37 e caso não conseguissem, deviam empenhar todos os esforços para não ser odiados pelas classes mais poderosas.38 É por isso que os imperadores, tal como os príncipes novos, tendo necessidade de favores extraordinários, aderiam muito mais aos soldados que ao povo, o que somente lhes seria útil se soubessem manter sua reputação entre eles.39","page":86},{"type":"paragraph","text":"Pelos motivos que acima mencionei, ocorreu que Marco Aurélio, Pertinax e Alexandre, os três de vida modesta, amantes da justiça, inimigos da crueldade, humanos e benignos,40 tiveram todos, a partir de Marco, um triste fim.41 Apenas Marco viveu e morreu muito honrado, pois herdara o império por jure hereditario (direito de sucessão), sem nada dever aos soldados ou ao povo.42 Por meio de suas numerosas virtudes, foi respeitado e, enquanto viveu, sempre manteve a ordem do Estado dentro dos limites do dever, sem jamais ser odiado ou desprezado.43","page":87},{"type":"paragraph","text":"Quanto a Pertinax, tornou-se imperador contra a vontade dos soldados, que, acostumados a viver licenciosamente sob Cômodo, não puderam suportar a vida honesta que o primeiro queria estabelecer.44 Além do ódio que criou para si mesmo,45 sua idade avançada tornou-o desprezado,46 o que o arruinou logo no início de sua administração.","page":87},{"type":"paragraph","text":"Aqui, é preciso observar que o ódio é adquirido tanto pelas boas como pelas más obras. Mas, como eu disse acima, o príncipe que queira manter o Estado muitas vezes é obrigado a não ser bom,47 porque quando a classe de súditos da qual acredita ter necessidade, seja o povo, sejam os soldados, sejam os grandes, é corrupta, cumpre que ele se esforce por satisfazê-la48 a fim de não a ter contra si próprio, e então, as boas obras tornam-se suas inimigas.49 Mas passemos para Alexandre, que, devido à sua grande bondade e aos muitos louvores a ele atribuídos, conservou o poder durante catorze anos sem que ninguém fosse executado, a não ser por julgamento. Entretanto, por ter sido considerado efeminado50 e um homem que se deixava dominar pela mãe,51 veio a ser desprezado, conspiraram contra ele e o mataram.","page":87},{"type":"paragraph","text":"Por outro lado, falando das qualidades opostas de Cômodo, de Sétimo Severo, de Antonino Caracala e Maximino, veremos que eles foram extremamente cruéis e gananciosos, e, para satisfazer os soldados, não pouparam o povo de toda espécie de opressão e de injúria, sendo que todos tiveram um triste fim, com exceção apenas de Severo, que pela grandeza de sua coragem e de outras virtudes,52 e preservando o afeto dos soldados, embora o povo fosse sobrecarregado de impostos, pôde sempre reinar de maneira feliz, pois essa sua grandeza fazia que fosse admirado tanto pelos soldados, que o respeitavam e viviam satisfeitos, como pelo povo, que vivia atônito e aturdido.53 E como as ações de Severo foram grandes para um príncipe novo, quero apenas demonstrar como ele soube muito bem usar o modelo da raposa e do leão, cujas naturezas mencionei anteriormente, que um príncipe deve imitar.54","page":87},{"type":"paragraph","text":"Conhecendo o imperador Juliano por sua covardia, Severo convenceu o seu exército, à testa do qual se encontrava em Esclavônia (antiga Ilíria), de que convinha ir para Roma vingar a morte de Pertinax, assassinado pelos soldados pretorianos,55 e, com esse pretexto, sem demonstrar aspirar ao império, conduziu o exército contra Roma chegando à Itália sem que ninguém soubesse de seus movimentos.56 Em Roma, matou Dídio Juliano,57 e o Senado, apavorado, elegeu-o imperador.58 Depois desse início e querendo assenhorear-se de todo o Estado, restavam ainda a Severo dois obstáculos a superar: o primeiro, na Ásia, onde Pescênio Nigro, chefe dos exércitos asiáticos, fizera-se proclamar imperador; o outro, no Ocidente, onde Albino também aspirava ao império.59","page":88},{"type":"paragraph","text":"Julgando perigoso revelar-se inimigo dos dois ao mesmo tempo, decidiu atacar Nigro e enganar Albino60 enviando-lhe uma carta na qual dizia que, havendo sido eleito imperador pelo Senado, oferecia-lhe compartilhar dessa dignidade e anexava à mesma o título de César, que, por decreto do Senado, proclamava-o seu colega.61 Albino aceitou o convite acreditando que fosse sincero. Severo, então, enfrentou Nigro, venceu-o e o matou; apaziguou o Oriente e voltou para Roma, onde se queixou para o Senado de que Albino, não satisfeito com os benefícios que lhe haviam sido propostos, tentara secretamente assassiná-lo, e, por isso, era necessário que fosse punido por sua ingratidão. Então, foi para a França e tirou-lhe o Estado e a vida.62","page":88},{"type":"paragraph","text":"Ao analisar minuciosamente as ações de Severo, é possível constatar que ele agiu como um ferocíssimo leão63 e uma raposa muito astuta, e, ao mesmo tempo, sendo temido e respeitado pelos súditos sem ser odiado pelos exércitos. Portanto, não é de se surpreender que, como homem novo, conseguisse exercer tal poder sobre tão grande império, pois grande reputação64 sempre o defendeu desse ódio que o povo poderia terlhe nutrido devido às suas rapinagens. Também Antonino, seu filho, foi um homem de grandes qualidades que faziam que fosse admirado pelo povo e querido pelos soldados, porque era um militar que suportava qualquer cansaço, desprezava o alimento rebuscado e detestava a ociosidade, o que o tornava amado por todos os exércitos.65 Contudo, sua ferocidade e crueldade foram tão inauditas a ponto de tornar-se odiado por todos,66 depois de matar uma boa parte dos cidadãos de Roma e do massacre geral dos habitantes de Alexandria. Também começou a ser temido pelas pessoas que lhe eram mais próximas e acabou morto por um centurião em meio ao seu exército. A esse respeito, é preciso observar que um príncipe não pode evitar a morte quando um homem firme e endurecido em sua vingança resolve eliminálo, pois aquele que despreza a vida poderá sempre ofendê-lo. Mas, como esses casos são raros,67 o príncipe tem pouco a temer. Por outro lado, precisa cuidar para não ofender gravemente as pessoas das quais se serve68 e que estejam ao seu redor e ao redor de seu principado, um cuidado que Antonino não teve ao executar injustamente um irmão daquele centurião que ele próprio ameaçava diariamente e que, apesar disso, era mantido em sua guarda pessoal. Essa foi, sem dúvida, uma temeridade69 que o levou à morte.","page":88},{"type":"paragraph","text":"Mas passemos a Cômodo,70 filho de Marco Aurélio, que teve facilidade em manter o império havendo-o conseguido por direito de sucessão. Bastava-lhe seguir os passos do pai para satisfazer o povo e os soldados, mas o seu espírito cruel e bestial fez com que perseguisse o povo e procurasse cativar os exércitos tornando-os licenciosos. Por outro lado, descuidando de sua imagem, era constantemente visto na arena lutando com os gladiadores e, agindo de maneira vil e indigna de sua majestade imperial, acabou sendo odiado e desprezado pelo povo. Conspirou-se contra ele e foi assassinado.71","page":89},{"type":"paragraph","text":"Resta-nos, agora, falar das qualidades de Maximino. Ele era um homem extremamente belicoso e, depois da passividade e morte de Alexandre, ao qual me referi acima, foi eleito ao poder, sem, contudo, mantê-lo por muito tempo. Duas coisas contribuíram para torná-lo odiado e desprezado:72 a primeira era sua procedência inferior,73 pois fora pastor de ovelhas na Trácia (fato conhecido por todos e que muito o depreciava no conceito geral); a segunda foi a sua reputação de crueldade criada no início de seu principado, quando, ao se demorar em sua ida a Roma para tomar posse do trono imperial, mostrou-se extremamente cruel ao exercer atos de grande tirania por intermédio de seus prefeitos, em Roma e em outros lugares do império.74 De maneira que, desprezado pela inferioridade de sua origem e temido pela crueldade de suas barbáries, a primeira a rebelar-se foi a África, e, em seguida, o Senado com todo o povo de Roma. Foi quando toda a Itália conspirou contra ele, e a esse movimento juntou-se o exército, que se encontrava combatendo em Aquileia. Deparando-se com muitas dificuldades diante do assédio dessa cidade e cansados de suas crueldades, mas agora o temendo menos em vista dos muitos inimigos que ele mesmo havia criado, os soldados mataram-no.75","page":89},{"type":"paragraph","text":"Não quero, aqui, fazer comentários sobre Heliogábalo, Macrino e Juliano por considerá-los totalmente desprezíveis e porque logo foram extintos. Mas quero, sim, chegar a uma conclusão sobre esse assunto. Portanto, digo que os príncipes dos nossos tempos têm menos dificuldade em satisfazer especialmente os soldados de suas administrações,76 porque, embora seja necessário prestar-lhes alguma consideração, isso é rapidamente resolvido, pois nenhum desses príncipes tem um exército incorporado ao governo e à administração das províncias,77 tal como eram os exércitos do Império Romano. Os imperadores eram obrigados a contentar os soldados em vez de o povo porque os soldados representavam o poder; mas hoje, é o povo que os príncipes devem satisfazer — exceção feita, a esse respeito, ao sultão otomano e ao sultão do Egito — porque o povo se tornou mais poderoso que os soldados.78","page":90},{"type":"paragraph","text":"A exceção que faço ao sultão otomano é por ele estar sempre cercado por 12 mil homens de infantaria e 15 mil da cavalaria, dos quais dependem a segurança e a força de seu reino.79 Por conseguinte, é necessário que esse senhor os mantenha amigos,80 amizade que deve conservar acima de tudo.81","page":90},{"type":"paragraph","text":"Quanto ao sultão do Egito, é preciso observar que o seu Estado é diferente de todos os outros principados; é semelhante ao pontificado cristão, que não pode ser chamado de principado nem é hereditário ou principado novo,82 porque com a morte do velho príncipe não são os filhos que assumem o seu lugar a título de herança, mas o seu sucessor é eleito ao poder por aqueles que têm autoridade para elegê-lo.83 De resto, como essa ordem é antiga, não é possível chamá-la de principado novo por não apresentar as dificuldades próprias desses principados, porque embora o príncipe seja novo, as instituições desse Estado são antigas e ordenadas, o que faz com que ele seja recebido como príncipe herdeiro.84","page":90},{"type":"paragraph","text":"Mas voltemos ao nosso assunto. Eu digo que todo aquele que vier a considerar o acima exposto poderá enxergar que o ódio ou o desprezo foi a causa da ruína dos imperadores mencionados, além de entender por que, dentre alguns agindo de certa maneira e outros de maneira contrária, apenas um de cada lado teve um final feliz, enquanto os outros tiveram um triste fim. Foi inútil e prejudicial a Pertinax e a Alexandre, como príncipes novos, querer imitar Marco Aurélio, que herdou o principado por direito de sucessão;85 e, da mesma forma, foi prejudicial a Caracala, Cômodo e Maximino querer imitar as ações de Severo86 por não possuírem as grandes qualidades necessárias para poder seguir seus passos. Portanto, um príncipe novo num principado novo não pode imitar as ações de Marco Aurélio nem tampouco seguir os passos de Severo, mas deve seguir o exemplo de Severo, no que seja necessário, para estabelecer seu poder, e o exemplo de Marco Aurélio, no que possa lhe servir, para manter a estabilidade e a glória de um império já estabelecido e consolidado.87","page":90},{"type":"heading","lvl":2,"title":"XX Se as fortalezas e muitas outras coisas que um príncipe realiza cotidianamente são úteis ou não","id":"h_o_pr_ncipe_nicolau_maquiavel_28","page":92},{"type":"paragraph","text":"Se as fortalezas e muitas outras coisas que um príncipe realiza cotidianamente são úteis ou não","page":92},{"type":"paragraph","text":"A fim de manter seguro o Estado, alguns príncipes desarmaram seus súditos; alguns mantiveram divididos os países submissos; alguns alimentaram inimizades contra si mesmos; alguns procuraram atrair para si o favor daqueles que, no início de seu governo, pareceram ser suspeitos; alguns edificaram fortalezas enquanto outros as demoliram e destruíram.1 Embora não seja possível determinar uma opinião a respeito desses vários meios sem entrar nas particularidades de cada Estado, falarei a respeito de maneira genérica.2","page":92},{"type":"paragraph","text":"Nunca houve um príncipe novo que desarmasse os seus súditos; ao contrário, ao encontrá-los desarmados, ele os armou,3 acreditando que, dessa forma, essas armas passariam a lhe pertencer, que os súditos suspeitos lhe seriam mais fiéis, que os outros manteriam sua lealdade e que todos, enfim, se tornariam seus partidários. Porém, como não é possível armar todos os súditos, o príncipe não deve temer os que não foram assim beneficiados, pois os primeiros serão gratos pela recompensa e os outros acreditarão que os súditos armados foram escolhidos para enfrentar obrigações e perigos maiores enquanto eles se mantêm em segurança.4 Por outro lado, ao desarmá-los, o príncipe começa a ofendê-los, demonstrando que desconfia de sua lealdade, e essa desconfiança inspiraria o ódio contra si.5 E por não poder ficar desarmado, será necessário que o príncipe se volte para as milícias mercenárias, a respeito das quais, como já disse, por melhor que sejam6 nunca estarão à altura de defendê-lo contra inimigos poderosos e súditos duvidosos.7 Assim, todo príncipe novo num principado novo nunca deixou de organizar uma força armada.8 A história está repleta de exemplos. Mas, quando um príncipe adquire um Estado novo que é agregado a um Estado antigo, faz-se necessário que o conquistado seja desarmado, salvo aqueles que nele foram seus partidários.9 Com o tempo e a ocasião, esses partidários devem ser privados de ação e afastados,10 de maneira que o seu exército seja formado de soldados próprios, os que o defenderam no Estado antigo.11","page":92},{"type":"paragraph","text":"Nossos antepassados e aqueles que se diziam sábios costumavam dizer que era necessário manter Pistoia por meio das rivalidades partidárias e Pisa por meio de fortalezas. Tomavam o cuidado de fomentar a divisão partidária em alguns domínios conquistados a fim de poder controlá-los mais facilmente. Isso podia ser a melhor forma de proceder na época em que a Itália era, de certo modo, equilibrada; mas não acredito que isso possa ser aconselhado hoje, pois, em minha opinião, as divisões nunca proporcionaram nenhum benefício.12 Ao contrário, quando o inimigo se aproxima, as cidades divididas não demoram a cair, porque a parte mais fraca se juntará às forças externas e a outra não conseguirá resistir.13","page":93},{"type":"paragraph","text":"Acredito que, movidos pelas considerações acima, os venezianos incentivavam as facções guelfa e gibelina nas cidades submissas aos seus domínios, e embora as disputas nunca chegassem ao derramamento de sangue, fomentavam essas divergências para que os habitantes ficassem tão entretidos com suas diferenças de opinião a ponto de não se preocuparem em unir-se contra eles. Essa política não surtiu o resultado desejado, pois, conforme pudemos observar depois da derrota de Vailá, algumas cidades tomaram coragem e libertaram-se do jugo da autoridade veneziana.","page":93},{"type":"paragraph","text":"Portanto, esses meios revelam a fraqueza do príncipe,14 e um principado forte jamais permitiria semelhantes divisões, que são benéficas apenas em tempo de paz, permitindo que os súditos sejam controlados com mais facilidade.15 Mas assim que uma guerra se pronuncia, esse sistema se mostra totalmente funesto.","page":93},{"type":"paragraph","text":"Sem dúvida, os príncipes tornam-se grandes quando superam as dificuldades e as oposições com as quais se deparam.16 Mas a sorte, principalmente quando quer engrandecer um príncipe novo que precisa de mais reputação que um príncipe herdeiro, faz surgir inimigos contra os quais ele deverá lutar a fim de que tenha capacidade de vencê-los, dando-lhe a oportunidade de galgar uma escada que os próprios inimigos lhe oferecem.17 É por isso que muitas pessoas pensam que um príncipe sábio, ao ser-lhe apresentada a ocasião, deve alimentar astuciosamente alguma inimizade a fim de que, uma vez vencida, ele possa aumentar sua reputação.18","page":93},{"type":"paragraph","text":"Os príncipes, particularmente os novos, encontraram mais lealdade e utilidade nos homens que no início de seu governo lhes pareceram mais suspeitos que nos homens que eram seus confidentes.19 Pandolfo Petrucci, príncipe de Siena, governava seu Estado muito mais com os homens que lhe haviam parecido suspeitos que com os outros. Mas é impossível falar amplamente a esse respeito porque tudo depende das diversas circunstâncias.20","page":94},{"type":"paragraph","text":"Direi somente que o príncipe poderá conquistar com grande facilidade os homens que no início de um principado foram inimigos21 e precisam de apoio para manter suas posições, pois serão forçados a servi-lo com maior lealdade a fim de neutralizar e apagar a sinistra opinião que se fazia a seu respeito.22","page":94},{"type":"paragraph","text":"Assim, o príncipe sempre consegue deles uma utilidade maior que aqueles que, acostumados a servi-lo, podem chegar a negligenciar seus interesses.23","page":94},{"type":"paragraph","text":"E por exigência do próprio assunto, não quero deixar de lembrar aos príncipes que conquistaram um Estado novo por meio dos favores intrínsecos de habitantes do mesmo Estado que devem analisar com cuidado os motivos que os levaram a agir em seu favor. Caso o tenham ajudado por insatisfação com o governo anterior e não por simpatia ou afeto natural, o príncipe novo terá grande dificuldade em mantê-los amigos, porque será quase impossível contentá-los.24","page":94},{"type":"paragraph","text":"Ao analisar os exemplos que os tempos antigos e modernos nos oferecem, é possível deduzir que seja mais fácil ao príncipe tornar amigos os homens que se contentavam com o regime anterior25 e, portanto, seus inimigos, que os homens que se tornaram amigos por estarem descontentes26 e o favoreceram na conquista do Estado.27","page":94},{"type":"paragraph","text":"Para poder manter seu Estado com maior segurança era costume dos príncipes construir fortalezas que fossem a brida e o freio para os que os desejassem enfrentar28 e para ter um refúgio seguro contra um ataque surpresa.29","page":94},{"type":"paragraph","text":"Louvo esse método por ter sido usado desde tempos remotos. Entretanto, em nossos dias, messer Niccolò Vitelli demoliu duas fortalezas na Cidade de Castelo para poder conservar esse Estado. Guido Ubaldo, duque de Urbino, havendo reconquistado o seu domínio, do qual havia sido expulso por César Bórgia, destruiu, desde seus alicerces, todas as fortalezas dessa província por entender que, sem elas, seria mais difícil perder o Estado novamente.30 Ao voltar para Bolonha, os Bentivoglio fizeram o mesmo. Portanto, segundo as circunstâncias, as fortalezas podem ou não ser úteis e se, por um lado, são benéficas, por outro são prejudiciais. E a esse respeito quero me pronunciar da maneira a seguir.","page":94},{"type":"paragraph","text":"O príncipe que teme mais a seu povo que aos estrangeiros31 precisa erguer fortalezas, mas aquele que teme mais aos estrangeiros que a seu povo deve evitar fazê-lo. O castelo de Milão, construído por Francisco Sforza, fez e fará mais guerra à casa Sforza que qualquer outra desordem naquele Estado. A melhor fortaleza que um príncipe pode ter é o afeto de seu povo,32 pois se for odiado nenhuma fortaleza o salvará,33 e uma vez que o povo pega em armas, sempre encontrará estrangeiros para apoiá-lo.34","page":95},{"type":"paragraph","text":"Em nossos tempos, pudemos ver que as fortalezas não beneficiaram príncipe algum, com exceção da condessa de Forli, quando o conde Girolamo, seu consorte, foi assassinado e ela pôde se refugiar em uma fortificação para fugir do ímpeto popular e esperar o socorro de Milão, por meio do qual recuperou o Estado.35 Nesse momento, as circunstâncias eram tais que o estrangeiro não pôde ajudar o povo.36 Entretanto, de nada lhe valeu a fortaleza37 quando ela foi atacada por César Bórgia, a quem o povo se aliou por odiá-la. Portanto, teria sido mais seguro para ela não ser odiada pelo povo que possuir fortalezas.38","page":95},{"type":"paragraph","text":"Considerando o todo, louvarei tanto aquele que construir fortalezas como aquele que não o fará, mas censurarei todo príncipe que, contando com as fortalezas, não temerá incorrer no ódio do povo.39","page":95},{"type":"heading","lvl":2,"title":"XXI Como um príncipe deve se comportar para que seja apreciado","id":"h_o_pr_ncipe_nicolau_maquiavel_29","page":96},{"type":"paragraph","text":"XXI","page":96},{"type":"paragraph","text":"Como um príncipe deve se comportar para que seja apreciado","page":96},{"type":"paragraph","text":"Nada pode fazer que um príncipe seja apreciado senão suas grandes campanhas1 e seus notáveis exemplos. Em nossos tempos, é possível citar Fernando de Aragão, atual rei da Espanha. Ele pode ser chamado de príncipe novo2 porque de um rei considerado fraco tornou-se, por meio da fama e da glória, o primeiro rei dos cristãos.3 E, tomando em consideração suas ações, verifica-se que todas foram grandiosas e algumas até extraordinárias.4 No início de seu reinado atacou Granada,5 e essa empresa foi a base de sua grandeza. Empreendeu essa guerra enquanto estava em paz com os vizinhos e sabendo que ninguém o impediria. Com essa ação, desviou a atenção dos barões de Castela, que, preocupados com essa guerra, não cogitavam inovar, e, dessa maneira, ele adquiriu autoridade e reputação sem que de nada desconfiassem.6 Com dinheiro do povo e da Igreja pôde manter os exércitos que foi formando na sequência de um longo período de guerra e pelos quais foi depois honrado.7 Além disso, a fim de poder iniciar empresas de maior envergadura e sempre se servindo da religião, entregou-se a uma piedosa crueldade, expulsando e livrando seu reino dos mouros,8 um exemplo que não pode ser considerado miserável e nem tampouco admirável. Com esse mesmo pretexto invadiu a África, fez a campanha da Itália e, recentemente, atacou a França. E foi assim que continuou fazendo planos e executando-os, mantendo sempre o espírito de seus súditos na admiração e no aguardo dos acontecimentos.9 Todas essas ações foram sendo executadas sucessivamente e ligadas umas às outras,10 de tal maneira que não permitiam nenhum espaço para quem eventualmente quisesse fazer-lhe frente.11","page":96},{"type":"paragraph","text":"Um príncipe ainda se beneficia ao dar de si mesmo exemplos notáveis com respeito à sua administração,12 exemplos semelhantes aos que se conta de messer Barnabò de Milão, quando a oportunidade surge para que alguém realize algo extraordinário, bom ou mau, na vida civil, e a maneira como é recompensado13 ou punido14 pelos amplamente comentados grandes serviços ou grandes crimes que cometeu. Em suas ações, o príncipe deve procurar dar de si, principalmente, o conceito de sua grandeza e de sua excelência.15","page":96},{"type":"paragraph","text":"Além disso, o príncipe é apreciado quando demonstra ser um verdadeiro amigo ou inimigo, ou seja, quando demonstra abertamente estar a favor de alguém e contra outro,16 o que é sempre o melhor partido a tomar, antes que permanecer neutro,17 pois se dois poderosos vizinhos entrarem em conflito, uma de duas coisas pode acontecer: que o príncipe tenha a temer ou não a vitória de um dos dois.18 Em qualquer um dos casos, será útil para o príncipe haver declarado abertamente sua simpatia por uma das partes,19 pois, caso contrário, ele seria sempre vítima do vencedor,20 para o prazer e satisfação do vencido.21","page":97},{"type":"paragraph","text":"Por conseguinte, nenhum dos dois terá qualquer motivo para defendê-lo nem tampouco para lhe dar asilo, porque o vencedor evitará os amigos suspeitos ou aqueles que não o ajudem em momentos de dificuldade; e o vencido não lhe oferecerá refúgio por ele não haver compartilhado de sua sorte empunhando as próprias armas.22","page":97},{"type":"paragraph","text":"Antíoco foi chamado à Grécia pelos etólios para que expulsasse os romanos. Enviou embaixadores aos aqueus, amigos dos romanos, para convencê-los a ficar neutros enquanto os romanos pediam que tomassem as armas e a eles se juntassem. O assunto foi debatido no conselho dos aqueus, e quando o enviado de Antíoco solicitou a neutralidade, o representante romano respondeu: Quod autem isti dicunt non interponendi vos bello, nihil magis alienum rebus vestris est;23 sine gratia, sine dignitate, praemium victoris eritis (O conselho desses homens para não intervir na guerra é contra seus interesses: sem respeito e dignidade, vocês serão a presa dos vencedores).","page":97},{"type":"paragraph","text":"Sempre acontecerá que aquele que não é seu amigo exigirá sua neutralidade e aquele que é amigo exigirá que demonstre seus sentimentos com as armas. Para evitar os perigos iminentes, os príncipes indecisos quase sempre decidem seguir o caminho da neutralidade e, de modo geral, fracassam.24 Mas quando o príncipe se declara abertamente por uma das partes, caso essa parte com a qual se aliou venha a vencer, embora seja poderosa e o príncipe permaneça à sua discrição, sempre haverá um vínculo de reconhecimento e de amizade; os homens nunca são desonestos a ponto de oprimir quem os ajudou e dar prova de tamanha ingratidão.25","page":97},{"type":"paragraph","text":"Além disso, as vitórias não são tão completas a ponto de que o vencedor não tenha nenhum respeito e, principalmente, não seja justo.26 Por outro lado, se o aliado perder, o príncipe será por ele ajudado dentro de suas possibilidades e terá a possibilidade de se tornar companheiro de uma fortuna que poderá ressurgir.27","page":98},{"type":"paragraph","text":"No segundo caso, quando os beligerantes não são poderosos o suficiente para que o príncipe os tema, a necessidade de se definir a favor de uma das partes é ainda maior, pois isso significaria o fracasso de um com o auxílio daquele que o príncipe, fosse ele previdente, deveria salvar,28 porque, no caso de esse último vencer, sempre será devedor do príncipe;29 e é impossível que com essa ajuda não vença.","page":98},{"type":"paragraph","text":"Aqui, é preciso observar que um príncipe deve tomar o cuidado de nunca se aliar a alguém mais poderoso que ele para atacar terceiros, a não ser que as circunstâncias o obriguem,30 porque, se vencer, conforme mencionei acima, tornar-se-á seu prisioneiro,31 e os príncipes devem evitar ao máximo ficar à discrição de outros.32","page":98},{"type":"paragraph","text":"A aliança com a França que os venezianos fizeram contra o duque de Milão, que poderia ter sido evitada, resultou em sua própria ruína.33 Mas, quando esse tipo de aliança é inevitável, como aconteceu aos florentinos quando o papa e a Espanha levaram seus exércitos contra a Lombardia, então o príncipe deve aderir pelos motivos acima expostos. Além disso, um Estado não deve pensar que sempre adotará medidas seguras;34 ao contrário, deve pensar que será muitas vezes forçado a tomar decisões duvidosas. Essa é realmente a ordem das coisas: fugir de um inconveniente significa incorrer em outro.35 A prudência consiste em saber discernir a natureza dos inconvenientes e adotar como melhor o menos prejudicial.","page":98},{"type":"paragraph","text":"Um príncipe deve, ainda, mostrar-se amante das virtudes e honrar aqueles que são excelentes em uma arte.36 Assim como deve incentivar seus cidadãos a exercer tranquilamente suas atividades no comércio, na agricultura e em qualquer outra função, e a que não se abstenham de enfeitar suas propriedades com receio de lhes serem tomadas, ou de abrir um comércio com receio dos impostos.37 Deve promover prêmios para quem realizar tais coisas e para quem queira, de alguma forma, engrandecer a cidade ou o Estado.38 Além disso, durante épocas convenientes do ano, é necessário que entretenha o povo com festas e espetáculos. E como todas as cidades são divididas em associações artísticas e grupos sociais,39 a eles o príncipe deve dar atenção40 e com eles deve se reunir41 ocasionalmente, dando de si exemplos de humanidade e de generosidade sem, todavia, esquecer-se de manter sua apropriada dignidade, em todas as ocasiões.","page":98},{"type":"heading","lvl":2,"title":"XXII Dos ministros dos príncipes","id":"h_o_pr_ncipe_nicolau_maquiavel_30","page":100},{"type":"paragraph","text":"XXII","page":100},{"type":"paragraph","text":"Dos ministros dos príncipes","page":100},{"type":"paragraph","text":"Para um príncipe, a eleição de seus ministros é muito importante, pois eles serão bons ou maus segundo o caráter e sabedoria do próprio príncipe.1 A primeira conjetura a respeito da capacidade de uma pessoa é feita observando-se os indivíduos que a cercam.2 Assim, quando os ministros de um príncipe são capazes e leais,3 é sempre possível reputá-lo sábio porque soube reconhecê-los e mantê-los fiéis.4 Mas, caso contrário, é sempre possível fazer mau juízo do príncipe, pois o primeiro erro que pode vir a cometer é justamente nessa eleição.5","page":100},{"type":"paragraph","text":"Todos os que conheceram messer Antonio de Venafro, ministro de Pandolfo Petrucci, julgaram esse príncipe de Siena extremamente valoroso por tê-lo como ministro.6 Existem três tipos de homens inteligentes: aqueles que têm discernimento próprio;7 aqueles que discernem o que os outros entendem;8 e aqueles que não discernem nem entendem o que os outros discernem.9 Os primeiros são excelentes, os segundos são muito bons e os terceiros são inúteis.10 Portanto, era inevitável que se Pandolfo não se enquadrasse no primeiro caso, se enquadraria no segundo, pois aquele que tem a capacidade de discernir o bem e o mal que uma pessoa faça ou diga reconhecerá, mesmo que não as consiga descobrir sozinho, as obras boas ou más de um ministro e poderá corrigir umas e elogiar outras, e o ministro, que não pode pensar em enganá-lo, se manterá fiel.","page":100},{"type":"paragraph","text":"Há um método infalível pelo qual um príncipe pode conhecer o ministro. Quando um ministro pensa mais em si próprio que no príncipe e que em todas as ações, procura o interesse próprio, e conclui-se que jamais será um bom ministro, e nele o príncipe nunca poderá confiar;11 aquele que tem o Estado de outro em suas mãos nunca deve pensar em si mesmo, mas exclusivamente no príncipe,12 lembrando-lhe coisas que dizem respeito apenas a ele.13 O príncipe, por outro lado, a fim de mantê-lo fiel e honesto, deve pensar no ministro honrando-o, enriquecendo-o e fazendo-o participar de honras e de funções para que este perceba que não pode ficar sem a sua proteção; isso, para que as muitas honras não o façam almejar outras;14 para que a riqueza não o faça ambicionar riqueza maior, e para que as muitas responsabilidades o façam temer as mudanças.15 Portanto, quando os príncipes e os ministros assim se comportam, a confiança é recíproca;16 mas, ao se comportar de maneira diferente, as consequências podem ser prejudiciais, tanto para os príncipes como para os ministros.17","page":100},{"type":"heading","lvl":2,"title":"XXIII Como evitar os aduladores","id":"h_o_pr_ncipe_nicolau_maquiavel_31","page":102},{"type":"paragraph","text":"XXIII","page":102},{"type":"paragraph","text":"Como evitar os aduladores","page":102},{"type":"paragraph","text":"Não posso deixar aqui de tratar de um ponto importante e um erro do qual os príncipes se defendem com muita dificuldade quando são imprudentes ou não sabem escolher bem os seus ministros. Quero referir-me aos aduladores, dos quais as cortes estão repletas,1 porque os homens se vangloriam tanto de suas próprias obras e se iludem de tal forma que é com muita dificuldade que os príncipes se defendem dessa escória. E quando tentam se defender, expõem-se ao perigo de ser desprezados.2 A única maneira de se defender da adulação é fazer que os homens entendam que a verdade não ofende ninguém.3 Mas se todas as pessoas tivessem a liberdade de dizer a verdade a um príncipe,4 ele logo seria desrespeitado. Portanto, um príncipe sábio deve dar preferência a uma terceira maneira, ou seja, escolhendo em seu Estado homens sábios aos quais deve dar a liberdade de falar franca e verdadeiramente sobre o que lhes pergunte, exclusivamente.5 Deve consultá-los sobre todos os assuntos6 e ouvir suas opiniões para poder deliberar sozinho e ao seu único critério.7 Deve comportarse com os conselheiros e com cada um deles de maneira que todos entendam que quanto mais francamente falarem, tanto mais serão apreciados. E, finalmente, pode não ouvir mais ninguém, e deve colocar em prática sua determinação e ter firmeza em suas decisões.8 Aquele que não procede dessa forma torna-se presa fácil dos aduladores ou muda constantemente de opinião pela diversidade de pareceres, donde resulta sua total falta de confiança.9","page":102},{"type":"paragraph","text":"Sobre esse assunto, quero referir-me a um exemplo moderno. Padre Luca (bispo Luca Rinaldi), embaixador do atual imperador Maximiliano, falando a respeito de sua majestade disse que ele não se aconselhava com ninguém e que tudo fazia à sua maneira, por ser contrário ao que foi exposto acima.10 Pois o imperador é um homem reservado que nunca revela suas ideias nem pede qualquer opinião. Mas, ao colocá-las em prática, elas começam a ser conhecidas, reveladas e contestadas pelas pessoas que o rodeiam,11 o que não o incomoda, pois desiste delas facilmente.12 Resulta, então, que as coisas que são feitas num dia são desfeitas no outro, e que ele nunca entende o que quer ou o que deseja fazer, e ninguém pode se basear em suas deliberações.13","page":102},{"type":"paragraph","text":"De maneira que um príncipe deve aconselhar-se sempre, porém, quando o considere conveniente, e não quando outros sugerirem que o faça. Por isso, deve impedir que as pessoas expressem qualquer opinião sem que sejam solicitadas.14","page":103},{"type":"paragraph","text":"Mas também é necessário que seja questionador, que ouça as respostas autênticas com paciência, e ao desconfiar que alguém, por respeito, não lhe diz a verdade, que demonstre o seu aborrecimento.15 Há muitas pessoas que acreditam que um príncipe é considerado sábio devido aos bons conselheiros que mantém ao seu redor, e não por sua própria natureza, mas elas se enganam,16 pois existe uma regra geral que nunca falha: o príncipe que não é sábio não pode ser bem aconselhado, a menos que confie num só ministro que o guie em tudo17 e que seja muito prudente. Nesse caso, poderia dar certo, mas seria por pouco tempo, porque o verdadeiro governante rapidamente lhe tomaria o Estado. E se esse príncipe, pouco sábio,18 se aconselhasse com mais de um ministro, nunca teria conselhos uniformes e ficaria sem saber como harmonizá-los. Cada conselheiro pensará em seus próprios interesses e ele não os saberá corrigir nem tampouco conhecer.19 E é impossível encontrar outro tipo de conselheiros porque os homens sempre se comportam mal20 até que alguma necessidade os obrigue a agir diferentemente. Mas a conclusão é que os bons conselhos, de qualquer fonte que sejam, devem nascer da prudência do príncipe, e não da prudência que resultou dos bons conselhos proporcionados ao príncipe.21","page":103},{"type":"heading","lvl":2,"title":"XXIV Por qual motivo os príncipes da Itália perderam seus Estados","id":"h_o_pr_ncipe_nicolau_maquiavel_32","page":104},{"type":"paragraph","text":"XXIV","page":104},{"type":"paragraph","text":"Por qual motivo os príncipes da Itália perderam seus Estados1","page":104},{"type":"paragraph","text":"Prudentemente, colocar em prática o que foi exposto até aqui fará que um príncipe novo pareça um príncipe antigo, tornando-o mais seguro e firme no Estado e consolidando-o como se fosse antigo,2 pois um príncipe novo é muito mais observado em suas ações que um príncipe hereditário. Ao serem essas ações reconhecidas como virtuosas, os súditos se sentirão mais atraídos e ligados a ele que numa tradição hereditária,3 porque os homens são muito mais afetados pelas coisas presentes que pelas do passado.4 E ao encontrar o bem nas coisas presentes, ficarão satisfeitos e não pensarão em mais nada; ao contrário, estarão prontos para manter e defender o príncipe,5 desde que ele não se faça desmerecer em outras coisas.6 E assim, ele terá duplicado sua glória ao criar um principado novo e tê-lo melhorado e organizado com boas leis, boas armas, bons amigos e bons exemplos,7 em oposição àquele príncipe hereditário que, duplamente vergonhoso, teria perdido seu Estado por falta de prudência.8","page":104},{"type":"paragraph","text":"E ao considerar o comportamento dos príncipes da Itália que em nossos tempos perderam seus Estados, como o rei de Nápoles, o duque de Milão e outros, notase logo que, em primeiro lugar, há um defeito comum com respeito às armas pelos motivos anteriormente expostos. Em seguida, verifica-se que alguns atraíram para si o ódio do povo,9 ou, mesmo tendo seu favor, não souberam cativar os grandes.10 Sem esses defeitos é impossível perder Estados que possuam recursos suficientes para manter um exército em campanha.11","page":104},{"type":"paragraph","text":"Filipe da Macedônia, não o pai de Alexandre, mas o que foi vencido por Tito Quinto, tinha um pequeno Estado em comparação à grandeza dos romanos e da","page":104},{"type":"paragraph","text":"Grécia que, juntos, o invadiram.","page":105},{"type":"paragraph","text":"Entretanto, por ser um guerreiro, soube agradar o povo e assegurar-se dos grandes, conseguindo resistir a esses exércitos durante muitos anos,12 e embora afinal perdesse algumas cidades, ainda manteve o seu reino.13","page":105},{"type":"paragraph","text":"Portanto, esses nossos príncipes, que durante muitos anos ficaram no poder, não podem colocar a culpa na sorte por tê-lo perdido, mas à própria inépcia, pois em tempo de paz nunca pensaram que as coisas pudessem mudar (um defeito comum dos homens é que, durante a bonança, não se preocupam com a tempestade),14 e quando surgiram tempos adversos, em vez de se defender, preferiram fugir,15 esperando que o povo, cansado da insolência dos vencedores, os chamasse de volta.16 Quando não há outros recursos esse ainda é um bom caminho a seguir. Mas é terrível abandonar outros caminhos por esse, pois ninguém pode pensar em cair acreditando que haja alguém que o recolha. Isso não acontece, mas, se acontecer, não haverá segurança na salvação, pois a defesa foi desonrosa e não dependeu do próprio príncipe.17 As únicas defesas boas, seguras e duráveis são as que dependem do próprio príncipe e de suas virtudes.18","page":105},{"type":"heading","lvl":2,"title":"XXV De quanto a sorte influi nas coisas humanas e de como lhe opor resistência","id":"h_o_pr_ncipe_nicolau_maquiavel_33","page":106},{"type":"paragraph","text":"XXV","page":106},{"type":"paragraph","text":"De quanto a sorte influi nas coisas humanas e de como lhe opor resistência","page":106},{"type":"paragraph","text":"Estou ciente de que muitas pessoas acreditaram e acreditam que as coisas do mundo são regidas pela sorte e por Deus, de maneira que os homens, com sua prudência, não as poderiam modificar nem tampouco remediar.1 Assim, seria possível deduzir que não vale a pena se preocupar muito com as situações, mas sim deixar-se governar pela sorte. Esta opinião tem recebido um crédito maior em nossos tempos devido às grandes transformações que foram observadas e que se observam todos os dias, superando todas as conjeturas humanas.2 Pensando nisso, eu mesmo cheguei a me sentir, de certa forma, inclinado a compartilhar do mesmo parecer. Contudo, e a fim de que nosso livre arbítrio não seja anulado, acredito que a sorte governe realmente metade de nossas ações, deixando que a outra metade, ou quase, seja por nós governada.3 Eu a comparo a um rio torrencial que, enraivecido,4 inunda as planícies, destrói árvores e edifícios e desloca terras de um lado para outro; todos fogem e cedem ao seu furor sem poder fazer-lhe frente. Embora esse fato não possa ser evitado, isso não impede que, em épocas de calmaria, os homens providenciem anteparos e diques5 para que, na época de cheia, as águas do rio possam escoar por um canal ou quebrar o ímpeto para que o rio não seja tão descontrolado nem tão avassalador.6 Assim também ocorre com a sorte7, que demonstra o seu poder onde não há obstáculos para refreá-la.","page":106},{"type":"paragraph","text":"E se considerarem a Itália, que é a sede dessas transformações engendradas pela própria sorte, poderão ver que se trata de uma planície sem diques e sem qualquer anteparo, e que se ela estivesse mais prevenida com os recursos necessários,8 como Alemanha, Espanha e França, essa cheia não teria provocado tais convulsões9 ou não teria ocorrido.10 Acredito que tenho falado o suficiente a respeito da oposição que, de modo geral, pode ser feita à sorte.11","page":106},{"type":"paragraph","text":"Mas, restringindo-me mais ao detalhe, pergunto-me por que o príncipe que hoje prospera amanhã cai em desgraça sem que tenha mudado a sua natureza ou a sua conduta.12 Acredito que isso ocorra, em primeiro lugar, pelos motivos extensamente expostos anteriormente, ou seja, o príncipe que se apoia totalmente na sorte sofre suas variações.13 Creio, ainda, que é feliz o príncipe que concilia a sua maneira de operar com as condições de sua época, e que, da mesma forma, é infeliz aquele príncipe cujo procedimento não esteja harmonizado com as condições da época.14","page":107},{"type":"paragraph","text":"Podemos observar que os homens agem de maneiras diferentes nas coisas que os induzam a perseguir as metas que se propõem, i.e., glórias e riquezas: um com cautela, outro com ímpeto; um com violência, outro com arte; um com paciência, outro com seu oposto; e por esses meios, cada um pode alcançar o seu objetivo.15 Entretanto, é possível observar que entre dois homens cautelosos um consegue seu objetivo, enquanto o outro, não; da mesma forma, podemos ver dois homens alcançarem o mesmo êxito agindo de maneiras diferentes: um age com cautela; outro com ímpeto. Isso resulta apenas da harmonia ou desarmonia das condições de diferentes épocas às quais se adaptem ou não na forma de agir de cada um.16 Daí resulta o que já disse: que dois príncipes agindo de maneiras diferentes obtêm o mesmo resultado, e que entre dois príncipes que agem de maneira semelhante um alcança o objetivo e o outro não. Disso ainda depende a variação do êxito, porque se um príncipe agir com prudência e paciência, e os tempos e as circunstâncias forem compatíveis com seu modo de agir, terá êxito; mas se os tempos e as circunstâncias mudarem e ele não mudar sua forma de agir, então fracassará. É pouco provável encontrar um homem que saiba se adequar a essa situação, seja porque não consegue se desviar do que a sua própria natureza17 o induz a fazer, seja porque não consegue se desviar de um caminho que sempre lhe foi favorável.18","page":107},{"type":"paragraph","text":"É por isso que quando é necessário agir com ímpeto19 e não sendo essa a sua índole, o homem cauteloso fracassa. Por outro lado, se ele mudasse a sua conduta de acordo com as circunstâncias, a sua sorte não mudaria.","page":107},{"type":"paragraph","text":"O papa Júlio II sempre agiu de forma impetuosa20 e deparou-se com os tempos e as circunstâncias condizentes com aquele modo de agir, por isso sempre teve êxito em seus objetivos. Consideremos a primeira campanha que ele empreendeu contra Bolonha, quando messer Giovanni Bentivoglio ainda estava vivo. Os venezianos não viam essa empresa com bons olhos e ela era objeto de discussão entre os reis da Espanha e da França. Mas, devido à sua ferocidade e ímpeto, Júlio II iniciou pessoalmente21 a expedição fazendo que a Espanha e os venezianos suspendessem suas ações; os venezianos, por medo; e a Espanha porque queria recuperar o reino de Nápoles por inteiro. Por outro lado, atraiu o apoio do rei da França, que vendo-o em movimento e interessado numa aliança que tornasse os venezianos vulneráveis,22 julgou não poder lhe negar suas tropas sem ofendê-lo de maneira manifesta.","page":107},{"type":"paragraph","text":"Com sua marcha impetuosa Júlio fez o que um papa, com toda a sua humana prudência, jamais fizera.23 Pois se houvesse esperado estabelecer todos os planos e procurado deixar todos os assuntos resolvidos antes de sair de Roma, como qualquer outro pontífice teria feito,24 seus intentos teriam fracassado. De fato, o rei da França teria encontrado mil maneiras para se desculpar e os outros lhe teriam causado mil temores.25","page":108},{"type":"paragraph","text":"Deixarei de falar de outras suas ações, pois todas foram conduzidas da mesma maneira e também tiveram êxito, e a brevidade de sua vida26 não deixou que experimentasse o revés, porque se houvessem surgido tempos e condições que exigissem cautela, ele certamente fracassaria devido ao seu modo de agir induzido por sua própria natureza de caráter.27","page":108},{"type":"paragraph","text":"Concluo, pois, que devido à inconstância da sorte e à obstinação dos homens em seus diversos modos de agir, eles serão felizes enquanto com a sorte estiverem em harmonia e infelizes quando dela divergirem. Pessoalmente, acredito que seja melhor ser impetuoso que cauteloso,28 porque a sorte é feminina, e ao querer dominá-la, é preciso surrá-la e contrariá-la. É possível observar que ela se deixa mais facilmente dominar pelos homens que fazem uso da violência que por aqueles que agem friamente. E por ser feminina, é amiga dos jovens, porque são menos cautelosos, mais afoitos e a dominam com maior audácia.29","page":108},{"type":"heading","lvl":2,"title":"XXVI Exortação à tomada da Itália para libertá-la das mãos dos bárbaros","id":"h_o_pr_ncipe_nicolau_maquiavel_34","page":109},{"type":"paragraph","text":"XXVI","page":109},{"type":"paragraph","text":"Exortação à tomada da Itália para libertá-la das mãos dos bárbaros1","page":109},{"type":"paragraph","text":"Ao tomar em consideração tudo que já foi exposto e pensando comigo mesmo se na Itália, no presente momento, as condições seriam propícias para que um príncipe novo, prudente e virtuoso introduzisse uma nova forma de governo pela qual fizesse a felicidade do povo italiano2 e, ao mesmo tempo, angariasse honra para si mesmo; pareceu-me serem tantas as condições a favor de um príncipe novo que dificilmente ocorreria um momento mais oportuno.3 E se, como já disse, para que Moisés pudesse demonstrar todas as suas virtudes fosse necessário que o povo de Israel estivesse escravizado no Egito; e para que Teseu mostrasse a sua excelência os atenienses estivessem dispersos, assim também para que se revelem as virtudes do espírito italiano seria necessário que a Itália se encontrasse nas condições atuais, ou seja, que fosse mais escravizada que os hebreus, mais subjugada que os persas e mais dispersa que os atenienses o foram anteriormente, sem liderança e sem organização; batida, despojada, dilacerada, invadida e havendo sofrido todo tipo de desgraça.4","page":109},{"type":"paragraph","text":"Embora tenha surgido certo vislumbre de esperança com relação a algum príncipe parecendo ter sido um enviado por Deus para a redenção da Itália,5 viuse como, no apogeu de sua carreira, ele foi abandonado pela sorte. De maneira que, quase sem vida, a Itália espera aquele que será capaz de curar suas feridas, de pôr um fim aos saques da Lombardia, à tributação do reino de Nápoles e da Toscana e que a cure de suas feridas gangrenadas já há muito tempo.6 O país está implorando a Deus que lhe envie alguém que o possa redimir dessas crueldades e insolências bárbaras.7 É possível ver que a Itália está pronta e disposta a seguir uma bandeira, desde que haja quem a empunhe.","page":109},{"type":"paragraph","text":"Neste momento, não se vê em quem ela poderia confiar suas esperanças senão em sua ilustre Casa8, que, com sua sorte e virtude, amparada por Deus e pela Igreja, e da qual sois agora príncipe (papa Leão X da Casa dos Médicis), poderia assumir o comando dessa redenção.9 Isso não lhe parecerá difícil se procurar seguir as ações e vida dos príncipes aqui mencionados.10 E embora esses homens fossem raros e brilhantes, não deixaram de ser homens11 e nenhum deles contou com uma oportunidade melhor que a presente, porque seus empreendimentos não foram mais justos e nem mais fáceis que este,12 e Deus não foi mais amigo deles do que está sendo de Vossa Magnificência. E aqui é justo dizer: Iustum enim est bellum quibus necessarium, et pia airma ubi nulla nisi in armis spes est (É justa a guerra para quem é necessária e honestas as armas para aqueles cuja esperança repousa somente nelas). Aqui há uma grande disposição e dificuldade, a menos que se tomem os homens que propus como modelos. Além disso, é possível ver, aqui, exemplos extraordinários emanados de Deus: as águas do mar se abriram; uma nuvem revelou o caminho; água brotou da pedra e o maná choveu do céu;13 tudo concorre para o seu engrandecimento. O resto dependerá de suas ações.14 Deus não quer realizar tudo para não nos tolher o livre arbítrio e a parte dessa glória que nos corresponde.15","page":110},{"type":"paragraph","text":"E não é de se admirar se algum dos italianos já citados não conseguiu fazer o que é esperado de sua ilustre casa, nem tampouco é estranho que depois de tantas revoluções e revoltas pareça ter sido extinto o valor militar de nossos compatriotas. Disso resulta que as antigas instituições militares não eram eficientes e que ninguém soubesse como inová-las.16 Nada pode proporcionar mais honra a um homem que acaba de subir ao poder que as novas leis e as novas instituições por ele criadas.17 Quando são bem fundamentadas e encerram grandeza, elas o tornam digno de respeito e de admiração. Na Itália não falta espaço para a implantação de todos os tipos de inovações.18 Aqui há grande valor nas tropas se esse valor não faltar aos chefes. Observem nos duelos e nos combates quanto os italianos são superiores na força, na destreza e na astúcia. Contudo, no que diz respeito aos exércitos, por culpa exclusiva da fraqueza dos chefes, o seu desempenho deixa a desejar. Isso acontece porque os que sabem comandar não são obedecidos, sendo que todos afirmam ser capacitados, mas sem haver ninguém, até agora, que saiba se impor e que, por sorte ou por habilidade, faça que os outros cedam.19 Daí decorre que, durante tanto tempo e em tantas guerras, nos últimos vinte anos os exércitos italianos fracassaram sempre. Testemunhas disso são Taro, Alexandria, Cápua, Gênova, Vailá, Bolonha e Mestri.","page":110},{"type":"paragraph","text":"Portanto, querendo sua ilustre casa seguir o exemplo dos excelentes homens que redimiram suas províncias, será necessário, acima de tudo e como verdadeiro fundamento de qualquer empreendimento, prover-se de tropas próprias, pois não há outras mais leais, mais seguras e com melhores soldados. E ainda que cada um seja bom, todos juntos serão melhores ao sentir que são comandados pelo próprio príncipe, que os incentiva e os honra.20 Por conseguinte, é necessário preparar esses exércitos para poder, com virtude italiana, defender-se dos estrangeiros.21","page":111},{"type":"paragraph","text":"E embora as infantarias suíça e espanhola sejam consideradas muito fortes, as duas possuem pontos fracos, o que permitiria a um terceiro tipo de infantaria enfrentá-las e vencê-las.22 Isso porque os espanhóis não resistiriam à cavalaria e os suíços temeriam uma infantaria que demonstrasse ser tão aguerrida quanto ela mesma. E, por experiência, já vimos os espanhóis serem derrotados pela cavalaria francesa e os suíços serem derrotados pela infantaria espanhola. Embora nesse último caso não se tenha uma prova plena, foi possível ter uma amostra na campanha de Ravena, quando a infantaria espanhola enfrentou as tropas alemãs, que praticam a mesma tática dos suíços. Mais leves e mais ágeis que os alemães, os espanhóis com seus pequenos escudos conseguiram infiltrarse por debaixo das lanças alemãs, matando-os sem ser atingidos. Teriam dizimado a infantaria alemã se não houvessem sido atacados pela cavalaria inimiga. Portanto, conhecendo os defeitos das duas, seria possível organizar uma infantaria diferente que resistisse à cavalaria e não se amedrontasse diante da infantaria, criando uma nova geração de armas e novas táticas de ataque e defesa.23 Uma vez implantadas e organizadas, essas são as inovações que proporcionariam prestígio e glória a um príncipe novo.24","page":111},{"type":"paragraph","text":"Por conseguinte, é preciso aproveitar essa oportunidade para que a Itália, depois de tanto tempo, possa vir a conhecer o seu redentor.25 Não tenho palavras para exprimir com quanto amor ele seria recebido em todas as províncias que tanto sofreram com as invasões estrangeiras; com que sede de vingança, com que inabalável fé, com que piedade e com que lágrimas. Quem lhe fecharia as portas? Quais povos lhe negariam obediência? Qual inveja se lhe oporia? Qual italiano lhe negaria o seu respeito?26 A todos repugna esse domínio bárbaro. Assuma, então, a sua ilustre casa essa incumbência com esse ânimo e com essa esperança com que se abraçam as causas justas para que, sob sua bandeira, essa pátria27 seja finalmente libertada e elevada à sua grandeza, confirmando a citação de Petrarca:","page":111},{"type":"paragraph","text":"Virtù contro a furore","page":112},{"type":"paragraph","text":"Prenderà l’arme, e fia el combatter corto;","page":112},{"type":"paragraph","text":"Chè l’antico valore","page":112},{"type":"paragraph","text":"Nell’italici cor non è ancor morto.28","page":112},{"type":"paragraph","text":"(Coragem contra o furor","page":112},{"type":"paragraph","text":"Tomará as armas, e curto será o embate;","page":112},{"type":"paragraph","text":"Pois o antigo valor","page":112},{"type":"paragraph","text":"Nos itálicos corações ainda não esmoreceu.)","page":112},{"type":"heading","lvl":1,"title":"CRONOLOGIA","id":"h_o_pr_ncipe_nicolau_maquiavel_35","page":113},{"type":"paragraph","text":"CRONOLOGIA","page":113},{"type":"paragraph","text":"1453 Tomada de Constantinopla pelos turcos.","page":113},{"type":"paragraph","text":"1454 A Paz de Lodi inaugura um período de equilíbrio entre os Estados italianos.","page":113},{"type":"paragraph","text":"1469 Maquiavel nasce em Florença, a 3 de maio. Morre Pedro de Médici, sendo sucedido por seu filho Lourenço, o Magnífico.","page":113},{"type":"paragraph","text":"1475 Eleição do papa Sisto IV.","page":113},{"type":"paragraph","text":"1476 Maquiavel inicia-se no estudo da matemática e do latim.","page":113},{"type":"paragraph","text":"1477 É mandado para a escola de Battista de Poppi, na igreja de San Benedetto.","page":113},{"type":"paragraph","text":"1492 Morte de Lourenço de Médici. Eleição do papa Alexandre VI. Cristóvão Colombo descobre a América.","page":113},{"type":"paragraph","text":"1494 Os Médicis são expulsos de Florença, onde se instala o regime do fanático monge Savonarola. Carlos VIII, rei da França, invade a Itália.","page":113},{"type":"paragraph","text":"1498 Savonarola é condenado à fogueira por heresia. Maquiavel torna-se segundo-chanceler da República de Florença. Vasco da Gama descobre o caminho para as Índias.","page":113},{"type":"paragraph","text":"1500 Missão de Maquiavel junto ao rei Luís XII da França.","page":113},{"type":"paragraph","text":"1501 Maquiavel se casa com Marietta Corsini.","page":113},{"type":"paragraph","text":"1502 Inicia missão junto à corte de César Bórgia em Ímola.","page":113},{"type":"paragraph","text":"1503 Missão de Maquiavel junto a Pandolfo Petrucci, governante de Siena. Missão de Maquiavel na corte papal. Eleição do belicoso papa Júlio II.","page":113},{"type":"paragraph","text":"1504 Os franceses perdem Nápoles. Miguel Ângelo esculpe o Davi.","page":114},{"type":"paragraph","text":"1505 Maquiavel é nomeado secretário dos Nove da Milícia.","page":114},{"type":"paragraph","text":"1507 Maquiavel é enviado em missão à corte de Maximiliano, imperador do Sacro Império RomanoGermânico.","page":114},{"type":"paragraph","text":"1509 Os venezianos são derrotados em Agnadello pelas tropas da Liga de Cambrai. Júlio II retoma a posse das cidades da Romanha.","page":114},{"type":"paragraph","text":"1511 Maquiavel realiza embaixadas em Milão e na França.","page":114},{"type":"paragraph","text":"1512 Os Médicis retornam a Florença. Miguel Ângelo conclui a Capela Sistina.","page":114},{"type":"paragraph","text":"1513 Maquiavel é processado por conspiração, torturado e encarcerado. Exilado em San Casciano, começa a escrever as suas principais obras: O príncipe e Discursos sobre a primeira década de Tito Lívio.","page":114},{"type":"paragraph","text":"1518 Escreve a comédia A mandrágora, obra-prima da dramaturgia italiana.","page":114},{"type":"paragraph","text":"1519 Carlos V torna-se sacro imperador romano-germânico.","page":114},{"type":"paragraph","text":"1520 Em Luca, Maquiavel trata dos interesses mercantis de Florença. Escreve A vida de Castruccio Castracani.","page":114},{"type":"paragraph","text":"1521 Publica A arte da guerra. Morre Leão X.","page":114},{"type":"paragraph","text":"1522 Eleição do papa holandês Adriano VI.","page":114},{"type":"paragraph","text":"1523 Júlio de Médici torna-se papa sob o nome de Clemente VII.","page":114},{"type":"paragraph","text":"1525 Maquiavel vai a Roma oferecer ao pontífice a sua concluída História de Florença. Francisco Sforza é reconhecido como duque de Milão.","page":115},{"type":"paragraph","text":"1527 Os Médicis são novamente expulsos de Florença. Maquiavel falece em 21 de junho.","page":115},{"type":"paragraph","text":"1532 Publicação póstuma de O príncipe.","page":115},{"type":"paragraph","text":"1559 O príncipe é incluído no Index de livros proibidos da Igreja Católica.","page":115},{"type":"heading","lvl":1,"title":"Notas de Rodapé","id":"h_o_pr_ncipe_nicolau_maquiavel_36","page":116},{"type":"heading","lvl":2,"title":"Nicolau Maquiavel ao Magnífico Lourenço de Médici","id":"h_o_pr_ncipe_nicolau_maquiavel_37","page":116},{"type":"paragraph","text":"1 As duas escolas dos grandes homens. (Cristina da Suécia)","page":116},{"type":"paragraph","text":"2 Como Tácito e Gibbon. (Napoleão general)","page":116},{"type":"paragraph","text":"3 É o contrário. (Cristina da Suécia)","page":116},{"type":"paragraph","text":"4 Assim comecei e assim convém começar. Conhece-se melhor o fundo dos vales quando se está no cimo da montanha. (Napoleão primeiro-cônsul)","page":116},{"type":"paragraph","text":"5 Isso é falso – 1684. (Cristina da Suécia)","page":116},{"type":"heading","lvl":2,"title":"I Dos vários tipos de principados e por quais meios são adquiridos","id":"h_o_pr_ncipe_nicolau_maquiavel_38","page":117},{"type":"paragraph","text":"1 Tal será o meu, se Deus me der vida. (Napoleão general)","page":117},{"type":"heading","lvl":2,"title":"II Dos principados hereditários","id":"h_o_pr_ncipe_nicolau_maquiavel_39","page":118},{"type":"paragraph","text":"1 De todas as coisas, essa é a única boa, por mais que digam o contrário; mas, até nova ordem, preciso cantar no mesmo tom que eles. (Napoleão general)","page":118},{"type":"paragraph","text":"2 Hei de evitá-las, tornando-me o decano dos soberanos da Europa. (Napoleão general) Sem dúvida. (Cristina da Suécia)","page":118},{"type":"paragraph","text":"3 Não é suficiente. (Cristina da Suécia)","page":118},{"type":"paragraph","text":"4 É difícil príncipes hereditários serem destronados. (Cristina da Suécia)","page":118},{"type":"paragraph","text":"5 Tem razão. (Cristina da Suécia) Veremos. O que me favorece é que não o tirei dele, mas de um terceiro, que não passava de um lodaçal de republicanismo. O odioso da usurpação não recai sobre mim. Os forjadores de frases a meu soldo já de tal o persuadiram: “Ele só destronou a anarquia”. Meus direitos ao trono da França não estão mal fundamentados no romance de Lemont. Quanto ao trono da Itália, terei uma dissertação de Montga... Isso é necessário para os italianos, que gostam de oradores. Para os franceses era suficiente um romance. O vulgo, que não lê, terá as homilias dos bispos e dos curas que eu criar, bem como um catecismo aprovado pelo núncio apostólico, e não poderá resistir a essa magia. Não falta coisa alguma, já que o papa ungiu minha testa imperial. Sob esse aspecto, devo parecer mais ferrenho ainda que qualquer Bourbon. (Napoleão imperador)","page":118},{"type":"paragraph","text":"6 Os vícios dos príncipes não são detestados. (Cristina da Suécia)","page":118},{"type":"paragraph","text":"7 Isso é verdade. (Cristina da Suécia)","page":118},{"type":"paragraph","text":"8 Quantas pedras de espera me deixam! Todos os demais estão ainda aí, e seria mister que não ficasse nem sequer um só para eu perder todas as esperanças. Voltarei a encontrar aí minhas águias, meus N., meus bustos, minhas estátuas e, quem sabe, até a carruagem imperial de minha coroação. Tudo isso fala incessantemente em meu favor aos olhos do povo e ativa a lembrança de minha pessoa. (Napoleão em Elba)","page":118},{"type":"heading","lvl":2,"title":"III Dos principados mistos","id":"h_o_pr_ncipe_nicolau_maquiavel_40","page":119},{"type":"paragraph","text":"1 Como há de ser o meu no Piemonte, na Toscana, em Roma, etc. (Napoleão cônsul)","page":119},{"type":"paragraph","text":"2 Os homens mudam sempre uma coisa em busca de outra que quase nunca encontram. (Cristina da Suécia)","page":119},{"type":"paragraph","text":"3 Pouco se me dá: o triunfo justifica. (Napoleão cônsul)","page":119},{"type":"paragraph","text":"4 Que tratantes! Dão-me a conhecer cruelmente essa verdade. Não conseguisse eu desembaraçar-me da tirania deles, sacrificar-me-iam. (Napoleão imperador)","page":119},{"type":"paragraph","text":"5 Não me tê-lo-iam tomado os austro-russos, em 1798, se eu lá houvesse permanecido. (Napoleão cônsul)","page":119},{"type":"paragraph","text":"6 Eu, pelo menos, não frustraria as esperanças dos que me haviam aberto suas portas em 1796. (Napoleão cônsul)","page":119},{"type":"paragraph","text":"7 Foi ao que eu me dediquei ao recuperar esse país no ano de 1800. Perguntese ao príncipe Carlos se me saí bem na empreitada. Não entendem nada disso e, para mim, tudo corre segundo os meus desejos. (Napoleão imperador)","page":119},{"type":"paragraph","text":"8 Isso não acontecerá mais. (Napoleão cônsul)","page":119},{"type":"paragraph","text":"9 A esse respeito, sei mais que Maquiavel. (Napoleão cônsul) — Esses meios, eles nem sequer os suspeitam, e aconselham-me outros contrários. Ótimo! (Napoleão em Elba)","page":119},{"type":"paragraph","text":"10 Ainda que estivessem, eu saberia dobrá-los. (Napoleão general)","page":119},{"type":"paragraph","text":"11 Não me esquecerei disso em todas as partes onde estabelecerei meu domínio. (Napoleão general)","page":119},{"type":"paragraph","text":"12 A Bélgica, que há apenas pouco tempo oferece, graças a mim, um belo exemplo disso. (Napoleão cônsul)","page":119},{"type":"paragraph","text":"13 Auxiliá-lo-ão. (Napoleão general)","page":119},{"type":"paragraph","text":"14 Ingenuidade de Maquiavel. Podia ele conhecer tão bem quanto eu todo o poder da força? Demonstrar-lhe-ei já o contrário em seu próprio país, na Toscana, assim como no Piemonte, em Parma, Roma, etc., etc. (Napoleão imperador)","page":119},{"type":"paragraph","text":"15 Tudo isso não está mal observado. (Cristina da Suécia)","page":119},{"type":"paragraph","text":"16 Outra ingenuidade! A força! (Napoleão imperador)","page":119},{"type":"paragraph","text":"17 Suprirei essa lacuna por meio de vice-reis, ou reis, que não passarão de dependentes meus: nada farão, a não ser por minha ordem, do contrário serão destituídos! (Napoleão imperador)","page":120},{"type":"paragraph","text":"18 Convém certamente que enriqueçam, se, por outro lado, eles me servirem a contento. (Napoleão cônsul)","page":120},{"type":"paragraph","text":"19 Temem-me; é quanto me basta. (Napoleão imperador)","page":120},{"type":"paragraph","text":"20 No que me diz respeito, é impossível. O terror do meu nome valerá aí pela minha presença. (Napoleão cônsul)","page":120},{"type":"paragraph","text":"21 Ad abundantiam juris. Faz-se uma coisa e outra. (Napoleão cônsul)","page":120},{"type":"paragraph","text":"22 É mister tomar cuidado com os que, embora nada tendo a perder, possuam coração. (Cristina da Suécia) Essa reflexão é muito boa. Aproveitar-me-ei dela. (Napoleão primeirocônsul)","page":120},{"type":"paragraph","text":"23 É assim que os quero. (Napoleão cônsul)","page":120},{"type":"paragraph","text":"24 Realizarei tudo isso no Piemonte, ao incorporá-lo à França. Disporei ali, para as minhas colônias, dos bens confiscados antes de eu chegar e a que se convencionou chamar de nacionais. (Napoleão general) Tudo isso não seria mau, se não fosse ímpio. (Cristina da Suécia)","page":120},{"type":"paragraph","text":"25 Não vejo senão fazê-las mais do que leves aos meus por espírito de bondade; nem por isso deixarão de se vingar delas em benefício meu. O abecê da arte de reinar é conhecido, ignorando que desagradar um pouco é o mesmo que desagradar muito. (Napoleão em Elba)","page":120},{"type":"paragraph","text":"26 Não observei bem essa regra; porém, eles armam aqueles a quem ofendem, e esses ofendidos me pertencem. (Napoleão em Elba)","page":120},{"type":"paragraph","text":"27 Não deixa de ter razão. (Cristina da Suécia)","page":120},{"type":"paragraph","text":"28 Façam-se bem pesados os impostos a fim de que as rendas sejam bastante amplas para deixar sobras. (Napoleão cônsul)","page":120},{"type":"paragraph","text":"29 Os inimigos domésticos são inegavelmente mais perigosos. (Cristina da Suécia) Não os temo quando os obrigo a ficar nelas; e delas não sairão, pelo menos não para se reunir contra mim. (Napoleão cônsul)","page":120},{"type":"paragraph","text":"30 Tudo isso não está mal achado e conheço muita gente que se deu bem por têlo posto em prática. (Cristina da Suécia)","page":120},{"type":"paragraph","text":"31 Não há para isso melhor meio que arrancar-lhe o poder e ficar com seus despojos. Módena, Piacenza, Parma, Nápoles, Roma e Florença proporcionaram outros. (Napoleão cônsul)","page":121},{"type":"paragraph","text":"32 O mundo já não é assim. (Cristina da Suécia) A esse respeito, espero a Áustria na Lombardia. (Napoleão cônsul)","page":121},{"type":"paragraph","text":"33 Como os suecos na Alemanha. (Cristina da Suécia) Os que podem ser chamados à Lombardia não são romanos. (Napoleão general)","page":121},{"type":"paragraph","text":"34 Isso ocorreu à Suécia na Alemanha. (Cristina da Suécia) Quanto auxílio encontraria a Áustria contra mim nas fracas potências atuais da Itália! (Napoleão general).","page":121},{"type":"paragraph","text":"35 Atraí-los! Não me daria a esse trabalho. Serão obrigados pela minha força a me obedecer, especialmente dentro do plano da Confederação Romana. (Napoleão imperador)","page":121},{"type":"paragraph","text":"36 Isso não deixa de acontecer nunca. (Cristina da Suécia)","page":121},{"type":"paragraph","text":"37 É o que se faz amiúde. (Cristina da Suécia) Bom para consultar no que diz respeito aos meus projetos sobre a Itália e a Alemanha. (Napoleão general)","page":121},{"type":"paragraph","text":"38 Tem razão. (Cristina da Suécia)","page":121},{"type":"paragraph","text":"39 Nós, suecos, conhecemos bem isso. (Cristina da Suécia) Maquiavel admirar-se-ia da arte com que eu soube evitá-los. (Napoleão imperador)","page":121},{"type":"paragraph","text":"40 Cuida-se de desacreditá-los ali. (Napoleão cônsul)","page":121},{"type":"paragraph","text":"41 E por que não os restantes? (Napoleão cônsul)","page":121},{"type":"paragraph","text":"42 Isso não era suficiente: os filhos de Rômulo precisariam de minha escola. (Napoleão imperador)","page":121},{"type":"paragraph","text":"43 Foi o melhor que eles fizeram. (Napoleão cônsul)","page":121},{"type":"paragraph","text":"44 Tem razão. (Cristina da Suécia)","page":121},{"type":"paragraph","text":"45 Comparação admirável. (Cristina da Suécia) Ao escrever isso, Maquiavel devia estar enfermo de espírito ou havia acabado de consultar o seu médico. (Napoleão imperador)","page":121},{"type":"paragraph","text":"46 Tudo consiste nessa previdência. (Cristina da Suécia)","page":121},{"type":"paragraph","text":"47 São verdades incontestáveis. (Cristina da Suécia)","page":122},{"type":"paragraph","text":"48 Isso é bonito e verdadeiro. (Cristina da Suécia)","page":122},{"type":"paragraph","text":"49 Eis a política dos reis, a única de fato sólida. (Cristina da Suécia) São uns covardes, e se alguns conselheiros desse calibre se me apresentarem, eu os... (Napoleão cônsul)","page":122},{"type":"paragraph","text":"50 Verdade incontestável. (Cristina da Suécia)","page":122},{"type":"paragraph","text":"51 Tornei ali obrigatório o uso da língua francesa, a começar pelo Piemonte, a província mais próxima da França. Nada mais eficaz para introduzir os costumes de um povo em outro estrangeiro que exigir que este fale a língua dele. (Napoleão general)","page":122},{"type":"paragraph","text":"52 Penso que ainda têm esse desejo. (Cristina da Suécia)","page":122},{"type":"paragraph","text":"53 Era-me bem mais fácil comprar os genoveses, que, por especulação fiscal, me deixaram entrar na Itália. (Napoleão general)","page":122},{"type":"paragraph","text":"54 Já soube proporcionar igual honra a mim mesmo e não cometerei, certamente, os mesmos erros. (Napoleão general)","page":122},{"type":"paragraph","text":"55 Temerários ao extremo, sem dúvida. (Cristina da Suécia)","page":122},{"type":"paragraph","text":"56 Os lombardos, aos quais fingi dar a Valtellina e as regiões de Bérgamo, Mântua, Bréscia, etc., infundindo-lhes a mania republicana, já me prestaram o mesmo serviço. Uma vez dono de seu território, logo terei o resto da Itália. (Napoleão general)","page":122},{"type":"paragraph","text":"57 Quem teme hoje o P. P.? (Cristina da Suécia)","page":122},{"type":"paragraph","text":"58 Não carecerei deles para conseguir essa vantagem. (Napoleão general)","page":122},{"type":"paragraph","text":"59 Erro imenso. (Napoleão general)","page":122},{"type":"paragraph","text":"60 É absolutamente necessário que eu embote os dois fios de sua faca. Luís XII não passava de um idiota. (Napoleão general)","page":122},{"type":"paragraph","text":"61 Valoroso P. P. (Cristina da Suécia)","page":122},{"type":"paragraph","text":"62 Fá-lo-ei também; mas essa partilha não me arrebatará a supremacia e meu bom José não ma contestará. (Napoleão imperador)","page":122},{"type":"paragraph","text":"63 Como será o que eu ali puser. (Napoleão imperador)","page":122},{"type":"paragraph","text":"64 Esse rei tributário teria feito a mesma coisa. (Cristina da Suécia) Se me for preciso tirar dali o meu José, não deixarei de ter alguns receios quanto ao sucessor que lhe der. (Napoleão imperador)","page":122},{"type":"paragraph","text":"65 É coisa frequente. (Cristina da Suécia)","page":123},{"type":"paragraph","text":"66 Também é coisa frequente. (Cristina da Suécia) Às minhas conquistas nada faltará. (Napoleão general)","page":123},{"type":"paragraph","text":"67 Isso é bem observado. (Cristina da Suécia)","page":123},{"type":"paragraph","text":"68 Cria-se a necessidade. (Napoleão general)","page":123},{"type":"paragraph","text":"69 Não seria erro se não houvesse cometido os outros. (Napoleão general)","page":123},{"type":"paragraph","text":"70 O seu erro consistiu em não ter calculado bem o tempo para isso. (Napoleão general)","page":123},{"type":"paragraph","text":"71 Máxima admirável. (Cristina da Suécia)","page":123},{"type":"paragraph","text":"72 Ao primeiro sinal de descontentamento, declaro a guerra; essa rapidez de decisão, uma vez conhecida, torna prudentes os inimigos. (Napoleão general).","page":123},{"type":"paragraph","text":"73 Nisso reside a maior parte da política e o meu lema é que a tal respeito nunca possuiremos o bastante. (Napoleão general)","page":123},{"type":"paragraph","text":"74 Não cometerão mais esse erro. (Cristina da Suécia) Que mais era preciso para Roma anatematizar Maquiavel? (Napoleão general)","page":123},{"type":"paragraph","text":"75 Contudo, um príncipe católico nunca pode se tornar grande senão engrandecendo ao mesmo tempo a Igreja. (Cristina da Suécia) Hão de pagar-me isso bem caro. (Napoleão imperador)","page":123},{"type":"paragraph","text":"76 O que não farei nunca. (Napoleão general)","page":123},{"type":"paragraph","text":"77 Os inimigos não parecem receá-lo. (Napoleão general)","page":123},{"type":"heading","lvl":2,"title":"IV Por qual motivo o reino de Dario, conquistado por Alexandre, não se revoltou contra os sucessores após a morte do conquistador","id":"h_o_pr_ncipe_nicolau_maquiavel_41","page":124},{"type":"paragraph","text":"1 Atenção a isto: não espero vir a reinar mais de trinta anos e desejo ter filhos idôneos para me suceder. (Napoleão imperador)","page":124},{"type":"paragraph","text":"2 Seis anos. (Cristina da Suécia)","page":124},{"type":"paragraph","text":"3 Continha-se somente o poder do nome de Alexandre. (Napoleão imperador)","page":124},{"type":"paragraph","text":"4 Carlos Magno mostrou-se mais avisado que aquele louco Alexandre, que pretendeu que os seus sucessores celebrassem suas exéquias de armas em punho. (Napoleão imperador)","page":124},{"type":"paragraph","text":"5 Esses barões são quiméricos. Semelhantes Estados são uma espécie de caos, como a Alemanha. (Cristina da Suécia)","page":124},{"type":"paragraph","text":"6 Antiguidades feudais que receio me ver forçado a ressuscitar, se os meus generais continuarem a insistir nisso. (Napoleão imperador)","page":124},{"type":"paragraph","text":"7 Os Estados regidos por um príncipe não têm outra forma de governo senão a monárquica, que é a melhor. (Cristina da Suécia)","page":124},{"type":"paragraph","text":"8 Excelente! Tudo farei para consegui-lo. (Napoleão imperador)","page":124},{"type":"paragraph","text":"9 São sempre respeitáveis os caprichos dos imperadores. Eles têm seus motivos para concebê-los. (Napoleão imperador)","page":124},{"type":"paragraph","text":"10 Ao menos esse tropeço eu não tenho, embora tenha outros equivalentes. (Napoleão imperador)","page":124},{"type":"paragraph","text":"11 Conquistá-lo-á. (Cristina da Suécia)","page":124},{"type":"paragraph","text":"12 A primeira dificuldade é grande, mas a segunda não é absolutamente menor. (Cristina da Suécia)","page":124},{"type":"paragraph","text":"13 Há outras dificuldades não menores. (Cristina da Suécia) Descubramos meios extraordinários, porque é absolutamente necessário que o império do Oriente volte a se unir ao do Ocidente. (Napoleão imperador)","page":124},{"type":"paragraph","text":"14 Proverá Deus achar-me eu na França em situação parecida! (Napoleão primeiro-cônsul)","page":124},{"type":"paragraph","text":"15 Isso se chama falar como grande homem; eu subscrevo a sua opinião. (Cristina da Suécia) Minhas forças e meu nome. (Napoleão imperador)","page":124},{"type":"paragraph","text":"16 Isso não ocorrerá facilmente. (Cristina da Suécia)","page":124},{"type":"paragraph","text":"17 Duvido que o império do mundo valha esse preço. (Cristina da Suécia)","page":124},{"type":"paragraph","text":"18 Porque não posso fazer mudar juntamente de lugar a Turquia e a França! (Napoleão imperador)","page":125},{"type":"paragraph","text":"19 Isso mudou. (Cristina da Suécia)","page":125},{"type":"paragraph","text":"20 Cortar-lhes-ei os braços e levantar-lhes-ei a tampa da cabeça. (Napoleão primeiro-cônsul)","page":125},{"type":"paragraph","text":"21 Ainda que a grande política possa não gostar de ouvi-lo, direi que, em minha opinião, a França é fácil de conquistar e não é difícil de manter. (Cristina da Suécia)","page":125},{"type":"paragraph","text":"22 Exemplos disso tenho eu visto de sobra. (Napoleão imperador)","page":125},{"type":"paragraph","text":"23 Seria uma grande obra. (Cristina da Suécia)","page":125},{"type":"paragraph","text":"24 Ambas as coisas são impraticáveis. (Cristina da Suécia) Havia-se começado tão bem no ano de 1793... (Napoleão imperador)","page":125},{"type":"paragraph","text":"25 Isso é perfeitamente certo. (Napoleão imperador)","page":125},{"type":"paragraph","text":"26 Dario, porém, não estava no mesmo nível de Alexandre como... (Napoleão primeiro-cônsul)","page":125},{"type":"paragraph","text":"27 Quanto a isso, já providenciei, e mais hei de providenciar. (Napoleão imperador)","page":125},{"type":"paragraph","text":"28 Quem resolvesse estabelecer residência na França, após tê-la conquistado, facilmente os dominaria. (Cristina da Suécia)","page":125},{"type":"paragraph","text":"29 No que me toca, possuo as mesmas vantagens. (Napoleão imperador)","page":125},{"type":"paragraph","text":"30 Faz-se aqui injustiça ao nosso Alexandre. (Cristina da Suécia)","page":125},{"type":"heading","lvl":2,"title":"V De que maneira devem ser governadas as cidades ou principados que, antes de conquistados, viviam pelas próprias leis","id":"h_o_pr_ncipe_nicolau_maquiavel_42","page":126},{"type":"paragraph","text":"1 Isso de nada vale no século em que estamos. (Napoleão general)","page":126},{"type":"paragraph","text":"2 Mau ditame. A continuação é o melhor que existe aí. (Napoleão general)","page":126},{"type":"paragraph","text":"3 Nenhuma dessas máximas é infalível. (Cristina da Suécia)","page":126},{"type":"paragraph","text":"4 Em Milão, uma junta executiva de três adeptos, assim como o meu triunvirato diretorial em Gênova. (Napoleão primeiro-cônsul).","page":126},{"type":"paragraph","text":"5 É o pior meio e o mais cruel. (Cristina da Suécia) Mas isso se pode fazer, literalmente, de muitos modos sem destruí-lo, como mudando a sua Constituição (Napoleão general).","page":126},{"type":"paragraph","text":"6 Gênova poderia dar-me alguma preocupação; porém, nada tenho a recear dos venezianos. (Napoleão primeiro-cônsul)","page":126},{"type":"paragraph","text":"7 As nações acostumadas à monarquia não podem se adaptar a outra forma de governo. (Cristina da Suécia)","page":126},{"type":"paragraph","text":"8 Especialmente quando diz trazer liberdade e igualdade ao povo. (Napoleão general)","page":126},{"type":"paragraph","text":"9 Tudo morre neste mundo. (Cristina da Suécia)","page":126},{"type":"paragraph","text":"10 Reprimir e revolucionar são suficientes. (Napoleão general)","page":126},{"type":"heading","lvl":2,"title":"VI Dos novos principados conquistados pelas próprias armas e pela virtude","id":"h_o_pr_ncipe_nicolau_maquiavel_43","page":127},{"type":"paragraph","text":"1 Às vezes, poderei fazê-lo mentir. (Napoleão general)","page":127},{"type":"paragraph","text":"2 A lição é boa. (Cristina da Suécia) Admitamos que seja certo. (Napoleão general)","page":127},{"type":"paragraph","text":"3 Bonita comparação. (Cristina da Suécia)","page":127},{"type":"paragraph","text":"4 Demonstrarei que, alvejando aparentemente mais baixo, é possível chegar lá com maior facilidade. (Napoleão general)","page":127},{"type":"paragraph","text":"5 É no que tudo consiste. (Cristina da Suécia)","page":127},{"type":"paragraph","text":"6 Nem sempre. Algumas vezes é a maior desgraça. (Cristina da Suécia) O valor é mais necessário que a sorte; ele é que a faz nascer. (Napoleão general)","page":127},{"type":"paragraph","text":"7 Não se deve confiar na sorte nem dela desesperar. (Cristina da Suécia)","page":127},{"type":"paragraph","text":"8 Essa constrição não é uma grande desgraça. (Cristina da Suécia)","page":127},{"type":"paragraph","text":"9 Isto me diz respeito. (Napoleão general)","page":127},{"type":"paragraph","text":"10 Sem dúvida, merece admiração. (Cristina da Suécia) Não aspiro a tamanha altura: dispenso-a. (Napoleão general)","page":127},{"type":"paragraph","text":"11 Aumentarei essa lista. (Napoleão general)","page":127},{"type":"paragraph","text":"12 Nada há que não venha de Deus. (Cristina da Suécia)","page":127},{"type":"paragraph","text":"13 Já não é necessária; virá, estejamos prontos para colhê-la. (Napoleão general)","page":127},{"type":"paragraph","text":"14 Como isso é dito divinamente! (Cristina da Suécia) O valor, antes de tudo. (Napoleão general)","page":127},{"type":"paragraph","text":"15 É a condição e situação dos franceses. (Napoleão general)","page":127},{"type":"paragraph","text":"16 Minha loba benéfica tive-a em Brienne. Rômulo, serás eclipsado! (Napoleão general)","page":127},{"type":"paragraph","text":"17 Tolice! (Napoleão general)","page":127},{"type":"paragraph","text":"18 Pobre herói! (Napoleão general)","page":127},{"type":"paragraph","text":"19 Bastaria em nossos tempos essa partícula de sabedoria? (Napoleão general)","page":127},{"type":"paragraph","text":"20 Isso se consegue com alguma astúcia. (Napoleão primeiro-cônsul)","page":127},{"type":"paragraph","text":"21 Isso é verdade. (Cristina da Suécia) Pois não sabemos ter às nossas ordens alguns manequins legislativos? (Napoleão general)","page":127},{"type":"paragraph","text":"22 Saberei frustrar-lhes as atividades. (Napoleão general)","page":128},{"type":"paragraph","text":"23 O homenzinho não sabia como se arranjam defensores entusiásticos que fazem que os outros desistam. (Napoleão primeiro-cônsul)","page":128},{"type":"paragraph","text":"24 Como tudo isso é bem dito! (Cristina da Suécia)","page":128},{"type":"paragraph","text":"25 Não deixam de ter razão. (Cristina da Suécia) Isso não acontece, a não ser com os povos um tanto cultos e que conservam ainda alguma liberdade. (Napoleão primeiro-cônsul)","page":128},{"type":"paragraph","text":"26 Estou prevenido contra tudo isso. (Napoleão primeiro-cônsul)","page":128},{"type":"paragraph","text":"27 Como isso está bem dito! (Cristina da Suécia)","page":128},{"type":"paragraph","text":"28 Grande descoberta! Quem pode ser bastante covarde para dar semelhante demonstração de fraqueza? (Napoleão general)","page":128},{"type":"paragraph","text":"29 Os oráculos são, então, infalíveis. (Napoleão general)","page":128},{"type":"paragraph","text":"30 A força é a chave para que tudo tenha bom êxito. (Cristina da Suécia) Nada mais natural. (Napoleão general)","page":128},{"type":"paragraph","text":"31 Eles me têm hoje em dia, mormente depois do testemunho do papa, na conta de um pio restaurador da religião e de enviado do céu. (Napoleão primeirocônsul)","page":128},{"type":"paragraph","text":"32 Não é possível levar as pessoas a acreditar à força; mas é possível obrigá-las a fingir que acreditam, e isso basta. (Cristina da Suécia) Terei sempre meios para isso. (Napoleão general)","page":128},{"type":"paragraph","text":"33 É esse o grande milagre da religião cristã. (Cristina da Suécia)","page":128},{"type":"paragraph","text":"34 Isso não me embaraça. (Napoleão general)","page":128},{"type":"paragraph","text":"35 Ainda não penetrei bem este último ponto e devo contentar-me com os outros três (Napoleão imperador) É necessário saber triunfar da inveja sem matar os invejosos. Seria prestar-lhes demasiada honra. (Cristina da Suécia)","page":128},{"type":"paragraph","text":"36 Nunca me saiu do pensamento, desde os estudos da minha meninice. Era de um país vizinho ao meu e eu pertenço, talvez, à mesma família. (Napoleão general)","page":128},{"type":"paragraph","text":"37 Já é dever-lhe muito. (Cristina da Suécia)","page":128},{"type":"paragraph","text":"38 Com alguma ajuda, sem dúvida. Oxalá tenha eu aqui a mesma sorte que ele. (Napoleão primeiro-cônsul)","page":128},{"type":"paragraph","text":"39 Minha mãe disse amiúde o mesmo de mim, amo-a por causa de seu prognóstico. (Napoleão imperador)","page":129},{"type":"paragraph","text":"40 Não o louvarei por isso. É ato digno conquistar novos amigos sem fazer injustiça aos velhos. (Cristina da Suécia)","page":129},{"type":"paragraph","text":"41 Nisso está a dificuldade. (Cristina da Suécia) É de bom augúrio. (Napoleão imperador)","page":129},{"type":"heading","lvl":2,"title":"VII Dos novos principados que se conquistam pelas armas e sorte de outros","id":"h_o_pr_ncipe_nicolau_maquiavel_44","page":130},{"type":"paragraph","text":"1 Como todos os que se deixam levar e nada sabem fazer sozinhos. (Napoleão general)","page":130},{"type":"paragraph","text":"2 É impossível. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"3 Tudo há de ser obstáculo para gente dessa espécie. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"4 Dar Estados a outrem pode contribuir para a própria glória; não, porém, para a própria segurança, que passará então a correr perigo. (Cristina da Suécia) Os aliados não tiveram outro alvo a não ser este. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"5 Nem sempre eram corrompidos. (Cristina da Suécia)","page":130},{"type":"paragraph","text":"6 Há muitos outros que se acham no mesmo caso. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"7 Como simples particular e longe dos Estados onde se é enaltecido; é a mesma coisa. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"8 É, sem dúvida, muito difícil. (Cristina da Suécia)","page":130},{"type":"paragraph","text":"9 E nisso eu os espero. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"10 Tudo isso é verdade. (Cristina da Suécia) Por mais sorte que tivera ao nascer, quando uma pessoa viveu vinte e três anos de vida privada, como em família, longe de um povo cuja índole mudou quase por completo e é levada de repente até ele nas asas da fortuna e por mãos estrangeiras para governar, encontra um Estado novo do tipo dos que menciona Maquiavel. Os antigos e convencionais prestígios morais interromperam-se demasiado longamente e não podem existir de outra forma a não ser de nome. Este oráculo é mais seguro que o de Calchas. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"11 É melhor dizer: bastante afortunados. Uma pessoa é mais hábil quando é afortunada. (Cristina da Suécia)","page":130},{"type":"paragraph","text":"12 Já havia lançado as minhas bases antes de chegar ao principado. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"13 O meu caso é o deles. (Napoleão em Elba)","page":130},{"type":"paragraph","text":"14 Habilidade e sorte devem andar de acordo; caso contrário, nada se fará de bom. (Cristina da Suécia)","page":130},{"type":"paragraph","text":"15 Com quem me pareço mais? Excelente agouro! (Napoleão primeiro-cônsul)","page":130},{"type":"paragraph","text":"16 Este exemplo demonstra o que foi dito acima. (Cristina da Suécia) Amiúde bem. Algumas vezes mal. (Napoleão general)","page":130},{"type":"paragraph","text":"17 Talento para reinar, é claro. O de outra espécie é uma tolice inútil. (Napoleão em Elba)","page":131},{"type":"paragraph","text":"18 Sem sorte, nada se faz de bom. (Cristina da Suécia) Principalmente se constroem às cegas, timidamente. (Napoleão em Elba)","page":131},{"type":"paragraph","text":"19 Melhor que eu? É difícil. (Napoleão general)","page":131},{"type":"paragraph","text":"20 Sem dúvida, eu desejaria que não o houvesse dito a ninguém senão a mim. Em todo caso, como não sabem ler, vem a ser a mesma coisa. (Napoleão general)","page":131},{"type":"paragraph","text":"21 Tenho de me queixar deles, mas corrigi-los-ei. (Napoleão em Elba)","page":131},{"type":"paragraph","text":"22 Conseguirei eu triunfar de um obstáculo desse gênero para dar menos ao meu José, ao meu Jerônimo? Quanto a Luís, talvez sobre algum do qual eu não saiba o que fazer. (Napoleão imperador) Muita razão tinha eu de hesitar a esse respeito. Mas que ingrato foi Joaquim! Que covarde e traidor! Há de remir suas culpas. (Napoleão em Elba)","page":131},{"type":"paragraph","text":"23 O Alexandre de tiara não me reconheceria melhor que o Alexandre de elmo. (Napoleão imperador)","page":131},{"type":"paragraph","text":"24 Uma parte! É pouquíssimo para mim. (Napoleão imperador)","page":131},{"type":"paragraph","text":"25 Soube dar origem a outras mais dignas de mim e do meu século, e que melhor correspondiam aos meus interesses. (Napoleão imperador)","page":131},{"type":"paragraph","text":"26 A experiência que já fiz, cedendo o ducado de Urbino para lograr a assinatura da concordata, persuadiu-me de que em Roma, como em outros lugares, hoje como outrora, uma das mãos lava a outra, e isso promete... (Napoleão primeiro-cônsul)","page":131},{"type":"paragraph","text":"27 Os genoveses abriram-me as portas da Itália com a louca esperança de que seus fabulosos créditos na França seriam pagos integralmente. Quid non cogit auri sacra fames? (O que a abominável fome de ouro não nos obriga a fazer?) Pelo menos, eles terão sempre a minha simpatia, muito mais que os demais italianos. (Napoleão primeiro-cônsul)","page":131},{"type":"paragraph","text":"28 Caro me custou não ter tido igual desconfiança em relação aos meus favorecidos da Alemanha. (Napoleão em Elba)","page":131},{"type":"paragraph","text":"29 Único procedimento acertado de todo homem que possua espírito e coração (Cristina da Suécia)","page":131},{"type":"paragraph","text":"Porque não havia outro remédio! (Napoleão em Elba)","page":132},{"type":"paragraph","text":"30 Os meus Colonna são realistas; os meus Orsini, os jacobinos, e os meus fidalgos serão os chefes de uns e de outros. (Napoleão general)","page":132},{"type":"paragraph","text":"31 Eu já havia iniciado uma parte disso antes de chegar ao consulado, e me dou por feliz por ter completado essas operações todas. (Napoleão imperador)","page":132},{"type":"paragraph","text":"32 Encontrei-a no senatus consulto sobre a máquina infernal de Nivoso e em minha maquinação de Arena e Topino na ópera. (Napoleão primeiro-cônsul)","page":132},{"type":"paragraph","text":"33 Vi outros semelhantes... Pichegru, Mallet. De todos triunfei sem precisar de estrangeiros. (Napoleão imperador)","page":132},{"type":"paragraph","text":"34 Fi-lo sem carecer de ajuda de ninguém. (Napoleão imperador)","page":132},{"type":"paragraph","text":"35 A resolução que tomou era celerada e há meios nobres e seguros para não ficar dependente de outros. (Cristina da Suécia)","page":132},{"type":"paragraph","text":"36 Qui nescit dissimulares nescit regnare (Quem não sabe fingir não sabe reinar). Luís XI não o sabia bastante. Deveria dizer: Qui nescit fallere, nescit regnare (Quem não sabe equivocar-se não sabe reinar). (Napoleão imperador)","page":132},{"type":"paragraph","text":"37 O que mais formidável restava contra mim, entre os meus Colonna e Orsini, não teve melhor sorte. (Napoleão imperador)","page":132},{"type":"paragraph","text":"38 Creio ter feito muito bem uma coisa e outra. (Napoleão imperador)","page":132},{"type":"paragraph","text":"39 Acaso conhecia a França, há vinte anos, a ordem de que goza hoje e que só o meu braço podia restabelecer? (Napoleão imperador)","page":132},{"type":"paragraph","text":"40 Ela é mil vezes mais proveitosa para os povos que odiosa para alguns fazedores de frases. (Napoleão imperador)","page":132},{"type":"paragraph","text":"41 Como os artífices de repúblicas francesas. (Napoleão primeiro-cônsul)","page":132},{"type":"paragraph","text":"42 Como na França republicana. (Napoleão primeiro-cônsul)","page":132},{"type":"paragraph","text":"43 Exatamente como na França antes de eu aí reinar. (Napoleão primeirocônsul)","page":132},{"type":"paragraph","text":"44 Pois não foi o que fiz! Havia necessidade de firmeza e rigor para conter a anarquia. (Napoleão imperador)","page":132},{"type":"paragraph","text":"45 E... serás o meu Orco. (Napoleão primeiro-cônsul)","page":132},{"type":"paragraph","text":"46 Por isso eu não tinha necessidade de ti. (Napoleão imperador)","page":132},{"type":"paragraph","text":"47 Por isso acabo com teu ministério e agrego-te à aposentadoria do meu Senado. (Napoleão imperador)","page":133},{"type":"paragraph","text":"48 Hei de criar uma comissão senatorial da liberdade individual que, contudo, só fará o que eu quiser. (Napoleão imperador)","page":133},{"type":"paragraph","text":"49 Ninguém está, mais que ele, condenado pela opinião pública a ser o meu bode expiatório. (Napoleão imperador)","page":133},{"type":"paragraph","text":"50 Estou furioso por não poder fazê-lo cair em desgraça sem inutilizá-lo. (Napoleão imperador)","page":133},{"type":"paragraph","text":"51 Ação indigna. (Cristina da Suécia) Bons tempos aqueles em que se podiam aplicar esses castigos que o povo achasse meritórios. (Napoleão imperador)","page":133},{"type":"paragraph","text":"52 Mau preceito, satisfazer o povo sacrificando os ministros. (Cristina da Suécia)","page":133},{"type":"paragraph","text":"53 Muito bem-feito. (Napoleão primeiro-cônsul)","page":133},{"type":"paragraph","text":"54 Esses malditos me fazem perder a paciência. (Napoleão primeiro-cônsul)","page":133},{"type":"paragraph","text":"55 É preciso prever tais contratempos. (Napoleão primeiro-cônsul)","page":133},{"type":"paragraph","text":"56 Muito bem achadas. (Napoleão primeiro-cônsul)","page":133},{"type":"paragraph","text":"57 Em podendo, não deixe de fazê-lo, e procure estar em condições de poder. (Napoleão primeiro-cônsul)","page":133},{"type":"paragraph","text":"58 Francisco II. (Napoleão imperador)","page":133},{"type":"paragraph","text":"59 O último era o mais seguro. (Cristina da Suécia)","page":133},{"type":"paragraph","text":"60 Não estou ainda tão adiantado como ele. (Napoleão imperador)","page":133},{"type":"paragraph","text":"61 Não pude executar até agora senão metade dessa manobra. Ci vuol tempo... (É preciso tempo...) (Napoleão imperador)","page":133},{"type":"paragraph","text":"62 Supondo que eu tenha induzido a isso todos os príncipes da Alemanha; pensemos no meu famoso projeto do Norte. Acontecerá o mesmo com resultados que nenhum conquistador conheceu. (Napoleão imperador)","page":133},{"type":"paragraph","text":"63 Livre de qualquer condição análoga, irei muito mais longe. (Napoleão imperador)","page":133},{"type":"paragraph","text":"64 É o único segredo, e quando este não basta, nada basta. (Cristina da Suécia) Convém não conhecer outra dependência. (Napoleão imperador)","page":133},{"type":"paragraph","text":"65 Péssimo para ele. Cumpre não estar nunca enfermo e tornar-se invulnerável em tudo. (Napoleão imperador)","page":134},{"type":"paragraph","text":"66 Grandes qualidades. (Cristina da Suécia)","page":134},{"type":"paragraph","text":"67 Como a França esperou por mim depois do meu desastre em Moscou. (Napoleão em Elba)","page":134},{"type":"paragraph","text":"68 Não duvido. (Cristina da Suécia)","page":134},{"type":"paragraph","text":"69 Bem que, politicamente falando, estivesse quase moribundo em Smolensk, nada tive que recear dos meus. (Napoleão em Elba)","page":134},{"type":"paragraph","text":"70 Já é muito para um moribundo. (Cristina da Suécia) Quanto a isso, não tive dificuldades. A notícia do meu desembarque em Fréjus bastava para anular quaisquer escolhas que me houvessem sido contrárias. (Napoleão primeiro-cônsul)","page":134},{"type":"paragraph","text":"71 Afinal de contas, quando se quer reinar gloriosamente, mais vale, falando de um modo geral, não pensar nisso. Tal pensamento teria paralisado meus projetos mais arrojados. (Napoleão imperador.)","page":134},{"type":"paragraph","text":"72 Sua malvadez e crueldade; o resto era admirável. (Cristina da Suécia)","page":134},{"type":"paragraph","text":"73 São bem ignorantes os escritorezinhos que disseram tê-lo indicado a todos os príncipes, inclusive aos que não estão nem podem estar no mesmo caso. Não conheço outro em toda a Europa, salvo eu, a quem esse modelo pudesse convir. (Napoleão imperador)","page":134},{"type":"paragraph","text":"74 Não há glória nem riqueza dignas de ser adquiridas ao preço de crimes e nunca ninguém é grande ou feliz por esse preço. Os maus governantes tiram benefícios de sua malvadez. (Cristina da Suécia) O que de análogo fiz era-me imposto como uma necessidade de minha situação e, por conseguinte, como um dever. (Napoleão imperador)","page":134},{"type":"paragraph","text":"75 Meus revezes dependem de causas semelhantes, contra as quais nada podia fazer a minha inteligência. (Napoleão em Elba)","page":134},{"type":"paragraph","text":"76 É justamente disso que eu preciso. (Napoleão general)","page":134},{"type":"paragraph","text":"77 Tudo isso melhora mais por meio da virtude que do crime. (Cristina da Suécia)","page":134},{"type":"paragraph","text":"78 Julgo ser eu um exemplo, não apenas mais recente, senão também mais perfeito e sublime. (Napoleão imperador)","page":134},{"type":"paragraph","text":"79 Estava com a cabeça debilitada pela enfermidade. (Napoleão imperador)","page":134},{"type":"paragraph","text":"80 Tê-lo-ia deposto logo se fosse eleito contra o meu gosto. (Napoleão primeiro-cônsul)","page":135},{"type":"paragraph","text":"81 Maquiavel engana-se. (Cristina da Suécia)","page":135},{"type":"paragraph","text":"82 Todos, menos o que foi eleito, sabiam ou previam que tinham de me recear. (Napoleão primeiro-cônsul)","page":135},{"type":"paragraph","text":"83 Já passou o tempo em que o seu ressentimento podia me atemorizar. (Napoleão imperador)","page":135},{"type":"paragraph","text":"84 Bastou o meu nome para fazê-los tremer e obrigá-los-ei a vir como cordeiros até o meu trono. (Napoleão primeiro-cônsul)","page":135},{"type":"paragraph","text":"85 Que belo motivo para confiar nessa gente! Maquiavel tinha muito boa fé. (Napoleão imperador)","page":135},{"type":"paragraph","text":"86 Máxima verdadeira. (Cristina da Suécia)","page":135},{"type":"paragraph","text":"87 Parecem esquecer quando a paixão deles o quer, mas não devemos nos fiar nisso. (Napoleão imperador)","page":135},{"type":"heading","lvl":2,"title":"VIII Dos que alcançaram o principado por meios criminosos","id":"h_o_pr_ncipe_nicolau_maquiavel_45","page":136},{"type":"paragraph","text":"1 Dispenso-o. (Napoleão general)","page":136},{"type":"paragraph","text":"2 A expressão é sobremaneira condenatória. Que importância tem o caminho, desde que se chegue? Maquiavel comete um erro ao querer fazer o papel de moralista em semelhante assunto. (Napoleão general)","page":136},{"type":"paragraph","text":"3 Pode em qualquer tempo simular que o teve. (Napoleão general)","page":136},{"type":"paragraph","text":"4 Discrição de moralista, muito intempestiva em matéria de estudo. (Napoleão general)","page":136},{"type":"paragraph","text":"5 Esse, vizinho meu, como Hierão, e de época mais próxima que ele, estará também na genealogia dos meus ascendentes. (Napoleão general)","page":136},{"type":"paragraph","text":"6 A constância nessas coisas é o indício mais seguro do meu gênio resoluto e ousado. (Napoleão general)","page":136},{"type":"paragraph","text":"7 Raramente alguém é malvado se tem inteligência e coração. (Cristina da Suécia) De ânimo, sobretudo, que é essencial. (Napoleão general)","page":136},{"type":"paragraph","text":"8 Chegarei a isso. (Napoleão general)","page":136},{"type":"paragraph","text":"9 Concedam-me o consulado por dois anos; não tardarei a obtê-lo como vitalício, e veremos. (Napoleão general)","page":136},{"type":"paragraph","text":"10 Prescindo de tal auxílio, embora necessite de outros. Mas estes são fáceis de obter. (Napoleão general)","page":136},{"type":"paragraph","text":"11 Veja-se meu 18 de Brumário e seus efeitos! Tem a vantagem de ser um recurso mais amplo, sem nenhum desses crimes. (Napoleão primeiro-cônsul)","page":136},{"type":"paragraph","text":"12 Consegui muito mais. Agátocles é um simples anão comparado comigo. (Napoleão imperador)","page":136},{"type":"paragraph","text":"13 Com o mesmo custo, galguei-os eu. (Napoleão imperador)","page":136},{"type":"paragraph","text":"14 Já fiz as minhas experiências nessa matéria. (Napoleão imperador)","page":136},{"type":"paragraph","text":"15 Preocupações pueris, isso tudo! A glória acompanha sempre o bom êxito, seja qual for a maneira como o alcancemos. (Napoleão imperador) Isso está bem dito e é muito verdadeiro. (Cristina da Suécia)","page":136},{"type":"paragraph","text":"16 Triunfou delas melhor que eu? (Napoleão imperador)","page":136},{"type":"paragraph","text":"17 Tenham a bondade de excetuar-me. (Napoleão imperador) Tudo está bem dito. (Cristina da Suécia)","page":136},{"type":"paragraph","text":"18 Outra vez, moral! Esse bom homem de Maquiavel carecia de audácia. (Napoleão imperador)","page":137},{"type":"paragraph","text":"19 Eu tinha a meu favor a cooperação de ambas. (Napoleão imperador) Ao contrário; todos esses crimes não impediram que ele tivesse virtude e sorte. Nada se faz sem ela. (Cristina da Suécia)","page":137},{"type":"paragraph","text":"20 Que personagem astuto! Fez-me conceber excelentes ideias desde a minha meninice. (Napoleão general)","page":137},{"type":"paragraph","text":"21 Vaubois, foste o meu Vitelli. Sei mostrar-me reconhecido quando chega a oportunidade. (Napoleão general)","page":137},{"type":"paragraph","text":"22 Reflexo de republicano. (Napoleão general)","page":137},{"type":"paragraph","text":"23 Que esperto! Há, em toda essa história de Oliverotto, muitas coisas que saberei aproveitar no momento oportuno. (Napoleão general)","page":137},{"type":"paragraph","text":"24 Isso se assemelhava ao famoso banquete da igreja de Saint-Suplice que, ao regressar da Itália, após Frutidor, mandei que os deputados a mim o oferecessem; mas a pera ainda não estava madura. (Napoleão primeirocônsul)","page":137},{"type":"paragraph","text":"25 Ação indigna e malvada. (Cristina da Suécia)","page":137},{"type":"paragraph","text":"26 Aperfeiçoei bastante essa manobra no dia 18 de Brumário e principalmente no dia seguinte ao de Saint-Cloud. (Napoleão primeiro-cônsul)","page":137},{"type":"paragraph","text":"27 Bastava-me, no momento, assustá-los, dispersá-los e fazê-los fugir. Era necessário sustentar o que eu mandara dizer solenemente a Barras: que não me agradava ver correr sangue. (Napoleão primeiro-cônsul)","page":137},{"type":"paragraph","text":"28 Portanto, que concluam logo esse Código Civil ao qual quero dar o meu nome! (Napoleão primeiro-cônsul)","page":137},{"type":"paragraph","text":"29 Isso dependia inteiramente de mim e providenciei tudo de forma cômoda e aos poucos. (Napoleão primeiro-cônsul)","page":137},{"type":"paragraph","text":"30 Tolo, que deixa que lhe tirem a vida junto com a soberania. (Napoleão em Elba)","page":137},{"type":"paragraph","text":"31 Com tal palavra de reprovação finge Maquiavel transformar tudo isso num crime. Pobre coitado! (Napoleão primeiro-cônsul)","page":137},{"type":"paragraph","text":"32 Que horror! Deus pune o malvado por meio do malvado. (Cristina da Suécia)","page":137},{"type":"paragraph","text":"33 A gente boa dirá que Oliverotto bem o merecia e que Bórgia fora o instrumento de um justo castigo. Lastimo-o, no entanto, por Oliverotto. Esse fato não seria de bom agouro para mim se houvesse no mundo outro César Bórgia além de mim. (Napoleão imperador)","page":137},{"type":"paragraph","text":"34 Isso não está mal dito. (Cristina da Suécia)","page":138},{"type":"paragraph","text":"35 Se tivesse começado assim, como Carlos II e muitos outros, a minha causa estaria perdida. Todos esperavam por isso; ninguém o teria censurado; em breve o povo não haveria pensado mais no caso e ter-me-ia esquecido. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"36 Por sorte, isso é o que menos os preocupa. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"37 Se insistirem por muito tempo nessas operações, acabarão prejudicando a si próprios. Quando a lembrança da ação que se deve castigar envelhecer, quem a pune não parecerá mais que um homem genialmente cruel, porque aquilo que torna o castigo justo estará esquecido. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"38 Era fácil. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"39 Este método, o único que resta aos ministros, forçosamente ser-me-á favorável. (Napoleão em Elba) Há, sem dúvida, males que só podem ser curados por meio de sangue e de fogo; em política, como em cirurgia, os cirurgiões piedosos não saram as feridas, matam o enfermo. (Cristina da Suécia)","page":138},{"type":"paragraph","text":"40 Não tardaremos a ter outra prova disso. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"41 A conclusão é justa e o preceito, excelente. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"42 Tudo quanto se faz por timidez é malfeito. (Cristina da Suécia)","page":138},{"type":"paragraph","text":"43 Uma e outra causa de ruína estão ao seu lado; a segunda está toda à minha disposição. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"44 Quando lhe é permitido. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"45 Os que, tendo tomado muito tarde o caminho das injúrias, começam a fazêlas timidamente e aos mais fracos suscitam o protesto e a revolta dos mais fortes. Que isso nos sirva de guia. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"46 Engana-se. É mister fazer-se temer e amar. Toda questão reside aí. (Cristina da Suécia) Quando os distribuímos a mancheias, recebe-os muita gente que é indigna deles, e os outros não os agradecem. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"47 Punir e recompensar bem; o que significa punir lastimando e recompensar regozijando-se. (Cristina da Suécia) Como se a gente fosse cata-vento. (Napoleão em Elba)","page":138},{"type":"paragraph","text":"48 Podemos sempre nos vingar. (Cristina da Suécia) Tentá-lo-ão. (Napoleão em Elba)","page":139},{"type":"paragraph","text":"49 E então, por mais que se dê e prometa, de nada valerá, porque o povo permanece naturalmente insensível diante de quem cai por motivo de falta de previsão e longanimidade. (Napoleão em Elba)","page":139},{"type":"paragraph","text":"50 Os homens dificilmente esquecem as ofensas, mas facilmente esquecem os benefícios. (Cristina da Suécia)","page":139},{"type":"heading","lvl":2,"title":"IX Do principado civil","id":"h_o_pr_ncipe_nicolau_maquiavel_46","page":140},{"type":"paragraph","text":"1 É o que eu queria, mas é difícil. (Napoleão general)","page":140},{"type":"paragraph","text":"2 Engana-se. (Cristina da Suécia) Esse recurso não se acha, sem dúvida, fora do meu alcance e já me serviu com bom resultado. (Napoleão general)","page":140},{"type":"paragraph","text":"3 Com frequência por ambos. (Cristina da Suécia) Trataremos de reunir, ao menos, a aparência de uma dupla ajuda. (Napoleão general)","page":140},{"type":"paragraph","text":"4 É a situação do partido diretorial; recorramos a ele para aumentar a minha consideração aos olhos do povo. (Napoleão general)","page":140},{"type":"paragraph","text":"5 Ver-se-ão arrasados. (Napoleão general)","page":140},{"type":"paragraph","text":"6 Aceito esse vaticínio. (Napoleão general)","page":140},{"type":"paragraph","text":"7 Fá-lo-emos trabalhar em tal sentido para que, por um motivo totalmente oposto, dirija-se ao mesmo fim que os diretoriais. (Napoleão general)","page":140},{"type":"paragraph","text":"8 Simularei tê-lo conseguido só por ele e para ele. (Napoleão general)","page":140},{"type":"paragraph","text":"9 Sempre me embaraçam terrivelmente. (Napoleão em Elba)","page":140},{"type":"paragraph","text":"10 Não logrei persuadir que me achava nesse caso. Depois do meu regresso, procurarei trabalhar melhor para isso. (Napoleão em Elba)","page":140},{"type":"paragraph","text":"11 No entanto, eu os havia atraído até esse ponto. (Napoleão em Elba)","page":140},{"type":"paragraph","text":"12 Os meus eram insaciáveis. Esses homens, oriundos de uma revolução, nunca se dão por satisfeitos. Fizeram-na só para enriquecer e a cobiça cresce-lhes com o que adquirem. Se antecipadamente se colocarem ao lado do partido que vai triunfar e o favorecerem, será apenas para obter seus favores. Depois, destruirão aquele a quem elevaram, quando não tiver mais nada para lhes dar, porque continuarão a querer receber. Haverá sempre o maior perigo em nos servirmos de tais partidários. Mas, como dispensá-los? Especialmente eu, que careço de outro apoio! Ah, se eu tivesse o título de sucessão ao trono, esses homens não poderiam me vender nem me prejudicar. (Napoleão em Elba)","page":140},{"type":"paragraph","text":"13 Os homens nunca se satisfazem. (Cristina da Suécia)","page":140},{"type":"paragraph","text":"14 É do que se pode duvidar. (Cristina da Suécia)","page":140},{"type":"paragraph","text":"15 A questão se resume em ser o mais forte e o mais acautelado. (Cristina da Suécia)","page":140},{"type":"paragraph","text":"16 Parece incrível que eu não tenha previsto que esses ambiciosos, sempre prontos a se antecipar ao curso da fortuna, me abandonariam e até me entregariam ao inimigo tão logo eu caísse na adversidade! Farão a mesma coisa a meu favor, contra ele, enquanto me virem em situação firme, mas sempre dispostos a se recolocar contra mim oportunamente se meu poder se mostrar vacilante. Por que não pude eu formar novos grandes homens? (Napoleão em Elba)","page":141},{"type":"paragraph","text":"17 Isso não é muito fácil ou, pelo menos, não tanto quanto eu desejaria. Tentei fazê-lo a respeito de... e de F... Por causa disso, tornaram-se ainda mais perigosos. O primeiro entregou-me aos meus inimigos. O segundo, de quem preciso, conservou-se em situação dúbia, mas hei de trazê-lo para o meu lado de uma ou de outra forma. (Napoleão em Elba) Não raciocina mal de todo. (Cristina da Suécia)","page":141},{"type":"paragraph","text":"18 Não tenho quase nenhum dessa espécie. (Napoleão imperador)","page":141},{"type":"paragraph","text":"19 Palavras muito úteis. (Cristina da Suécia)","page":141},{"type":"paragraph","text":"20 O bom conselheiro nunca é tímido. (Cristina da Suécia)","page":141},{"type":"paragraph","text":"21 Isso não está mal dito. (Cristina da Suécia) Não sofro de semelhante mal. (Napoleão imperador)","page":141},{"type":"paragraph","text":"22 Assim é a maioria dos meus. (Napoleão imperador)","page":141},{"type":"paragraph","text":"23 Só um tolo duvidará disso. (Cristina da Suécia)","page":141},{"type":"paragraph","text":"24 Não conhecera bem esta verdade; o êxito fez-me compreendê-la com dureza. Poderei aproveitar-me dela no futuro? (Napoleão em Elba)","page":141},{"type":"paragraph","text":"25 Procurarei fazê-lo. (Napoleão general)","page":141},{"type":"paragraph","text":"26 Preciso, não obstante, de fortes contribuições e de numerosos soldados. (Napoleão general)","page":141},{"type":"paragraph","text":"27 Deve-se geralmente ser bondoso com todos e só fazer o mal por necessidade evidente. (Cristina da Suécia)","page":141},{"type":"paragraph","text":"28 Este era o meu ponto fraco. (Napoleão general)","page":141},{"type":"paragraph","text":"29 Mau recurso. (Cristina da Suécia) Deram-no a conhecer cruelmente. (Napoleão cônsul)","page":141},{"type":"paragraph","text":"30 Bem dito. (Cristina da Suécia) Sim, positivamente, quando o povo não passa de lama. (Napoleão general)","page":141},{"type":"paragraph","text":"31 Grandes palavras e belo raciocínio. (Cristina da Suécia) De tudo isso, faltou-me só a vantagem de ser amado pelo povo e, não obstante... Mas fazer-se amar na situação em que eu me encontrava, com as necessidades que tinha, era muito difícil. (Napoleão general)","page":142},{"type":"paragraph","text":"32 Isso depende das circunstâncias e só é verdade quando somos os mais fortes, e o queremos ser. (Cristina da Suécia)","page":142},{"type":"paragraph","text":"33 Raciocina bastante bem. (Cristina da Suécia)","page":142},{"type":"paragraph","text":"34 Veremos como isso acontece. (Napoleão em Elba)","page":142},{"type":"paragraph","text":"35 Conto com isso. (Napoleão em Elba)","page":142},{"type":"paragraph","text":"36 Ninguém deve confiar senão em si mesmo. (Cristina da Suécia) Onde os encontrará. (Napoleão em Elba)","page":142},{"type":"paragraph","text":"37 Belas palavras. (Cristina da Suécia) Não o vislumbram nestes protestos de amizade e cartas de felicitações que o tranquilizam. Não sabem, pois, ainda isso acontece! (Napoleão em Elba)","page":142},{"type":"paragraph","text":"38 Boa máxima! (Cristina da Suécia) Se eu saísse bem do apuro na primeira vez, desforrar-me-ia com vantagem enquanto pudesse, por mim ou por outro. (Napoleão em Elba)","page":142},{"type":"paragraph","text":"39 Nunca se pensa bastante nesta verdade. (Napoleão em Elba)","page":142},{"type":"paragraph","text":"40 Neste mundo, nós todos dependemos uns dos outros. Raramente é indispensável fiarmo-nos em alguém, mas amiúde é indispensável fingir que nos fiamos. (Cristina da Suécia)","page":142},{"type":"heading","lvl":2,"title":"X De como devem ser medidas as forças de todos os principados","id":"h_o_pr_ncipe_nicolau_maquiavel_47","page":143},{"type":"paragraph","text":"41 Como a França, por meio das conscrições, embargos, etc. (Napoleão general)","page":143},{"type":"paragraph","text":"42 Desgraçados os que precisam dos outros. (Cristina da Suécia) Isto não vale nada. (Napoleão general)","page":143},{"type":"paragraph","text":"43 É só o que importa. (Cristina da Suécia) Com maior razão, quando podem atacar e amedrontar os outros. (Napoleão general)","page":143},{"type":"paragraph","text":"44 Quando isso acontece, estamos perdidos. (Cristina da Suécia) Coisa bem triste! Não a desejaria para mim. (Napoleão general)","page":143},{"type":"paragraph","text":"45 Isto não me concerne. (Napoleão general)","page":143},{"type":"paragraph","text":"46 Achei-me, contudo, em tal caso; mas aproveitarei a primeira ocasião para fortificar minha capital, sem que adivinhem o verdadeiro motivo disso. (Napoleão em Elba)","page":143},{"type":"paragraph","text":"47 Isso mudou muito. (Cristina da Suécia)","page":143},{"type":"paragraph","text":"48 Isso é bom para os tempos idos. Ademais, não se trata, aqui, de atacantes franceses. (Napoleão general)","page":143},{"type":"paragraph","text":"49 Elas são venais. (Cristina da Suécia)","page":143},{"type":"paragraph","text":"50 De que servira, na Alemanha e na Suíça, estas precauções contra o nosso entusiasmo? (Napoleão primeiro-cônsul)","page":143},{"type":"paragraph","text":"51 Que praça-forte resistirá tanto tempo se for atacada e não receber socorros? (Cristina da Suécia) Não costumo ficar rondando durante um ano, ociosamente, debaixo dos muros alheios. (Napoleão primeiro-cônsul)","page":143},{"type":"paragraph","text":"52 O meio mais eficaz, ou melhor, único, é contê-los a todos empregando o terror; tiranizai-os e eles não se insurgirão nem ousarão respirar. (Napoleão imperador)","page":143},{"type":"paragraph","text":"53 Não deixa de ter razão. (Cristina da Suécia)","page":143},{"type":"paragraph","text":"54 Seja ou não assim, pouco me importa. Não preciso disso. (Napoleão imperador)","page":143},{"type":"paragraph","text":"55 Com que se defender, que é o essencial. (Napoleão imperador)","page":143},{"type":"heading","lvl":2,"title":"XI Dos principados eclesiásticos","id":"h_o_pr_ncipe_nicolau_maquiavel_48","page":144},{"type":"paragraph","text":"1 Ah, se eu pudesse, na França, tornar-me o augusto e sumo pontífice da religião! (Napoleão general)","page":144},{"type":"paragraph","text":"2 Neste ponto, todos os príncipes de hoje são eclesiásticos. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"3 Toda a Itália encontra-se nesta situação, bem como grande parte da Europa. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"4 Poderá alguém ser mais desditoso que os povos do Estado eclesiástico sob Inocêncio XI? (Cristina da Suécia)","page":144},{"type":"paragraph","text":"5 Esta ironia merecia, por certo, todos os raios espirituais do poder temporal do Vaticano. (Napoleão general) Tem razão. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"6 Digam lá o que quiserem, Alexandre VI foi um grande papa. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"7 Hoje, ninguém mais teme o poder temporal nem o espiritual. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"8 Esse tempo passou. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"9 Poder-se-ia fazer isso outra vez, bastaria querer. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"10 Julgas mal os interesses de sua reputação e a corte de Roma não te perdoará essa história indiscreta. (Napoleão general)","page":144},{"type":"paragraph","text":"11 Donos em número excessivo. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"12 Esse cuidado era bem justificado. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"13 Com o correr do tempo, isso não era provável. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"14 Hoje em dia só se utilizam dele mesmo. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"15 O que não diria Maquiavel se ainda vivesse! (Cristina da Suécia) Reflexões indiciárias... dignas de ser ponderadas. (Napoleão general)","page":144},{"type":"paragraph","text":"16 Raciocina bem. (Cristina da Suécia)","page":144},{"type":"paragraph","text":"17 É duvidoso que tenha sido mais desprezada que atualmente. (Cristina da Suécia) Eu também pouco a temo. (Napoleão general)","page":144},{"type":"paragraph","text":"18 O que não pode fazer um papa engenhoso com dinheiro e armas? (Cristina da Suécia)","page":144},{"type":"paragraph","text":"A seu tempo e em seu país. (Napoleão general)","page":145},{"type":"paragraph","text":"19 Sem dúvida, realizou grandes coisas com instrumentos e meios detestáveis. (Cristina da Suécia)","page":145},{"type":"paragraph","text":"20 Teria gostado de fazer o mesmo na França. (Napoleão general)","page":145},{"type":"paragraph","text":"21 É no que não acredito. (Cristina da Suécia)","page":145},{"type":"paragraph","text":"22 Valoroso papa! (Cristina da Suécia) Eis o que se chama proceder como grande homem. (Napoleão general)","page":145},{"type":"paragraph","text":"23 É este o verdadeiro dever dos papas. (Cristina da Suécia)","page":145},{"type":"paragraph","text":"24 De todas as coisas, é a única que me convém fazer na França. (Napoleão primeiro-cônsul)","page":145},{"type":"paragraph","text":"25 É o que importa. (Cristina da Suécia)","page":145},{"type":"paragraph","text":"26 Não seria nada mau que eu tivesse ali cardeais que me devessem o seu chapéu encarnado. (Napoleão primeiro-cônsul)","page":145},{"type":"paragraph","text":"27 Valer-me-ei dela para o triunfo da minha. (Napoleão primeiro-cônsul)","page":145},{"type":"paragraph","text":"28 É o essencial. (Cristina da Suécia)","page":145},{"type":"heading","lvl":2,"title":"XII Dos vários tipos de milícias e dos soldados mercenários","id":"h_o_pr_ncipe_nicolau_maquiavel_49","page":146},{"type":"paragraph","text":"1 Por que, pois, aquele visionário do Montesquieu falou de Maquiavel em seu capítulo “Dos legisladores”? (Napoleão primeiro-cônsul)","page":146},{"type":"paragraph","text":"2 Quando não se tem tropas próprias ou quando os mercenários e os auxiliares são mais numerosos, é evidente. (Napoleão general)","page":146},{"type":"paragraph","text":"3 Excetuo, porém, os suíços. (Napoleão em Elba)","page":146},{"type":"paragraph","text":"* Atribuía-se ao papa Alexandre VI o dito segundo o qual “os franceses, ao invadir a Itália, empunharam não a espada para combater, e sim o giz para marcar os seus acampamentos”, em alusão à falta de resistência dos Estados italianos. (N. do E.)","page":146},{"type":"paragraph","text":"4 Na época do autor, qualquer erro, fosse político ou moral, era chamado de pecado, e ninguém era mais indulgente com os erros dos estadistas que o são hoje em dia os jansenistas com os pecados do vulgo. (Napoleão general)","page":146},{"type":"paragraph","text":"5 Exércitos formados por um predecessor inimigo e que só estão realmente a nosso serviço a troco de pagamento não passam de mercenários. (Napoleão em Elba)","page":146},{"type":"paragraph","text":"6 Eles o têm entre seus partidários. (Napoleão em Elba)","page":146},{"type":"paragraph","text":"7 Sei-o, eles deveriam sabê-lo. Mas, pode-o ele?","page":146},{"type":"paragraph","text":"8 Não há decreto nem ordem que os possa estorvar. Não se faz a lei, mas é ele quem a dita. (Napoleão general)","page":146},{"type":"paragraph","text":"9 Deve-se esperar por isso quando não se dispõe senão de mercenários. (Napoleão general)","page":146},{"type":"paragraph","text":"10 Mas, no fim, pode cair. (Napoleão general)","page":146},{"type":"paragraph","text":"11 Pode-se fazer o mesmo com tropas que somente recebem soldo do Estado. Trata-se de infundir nelas o espírito próprio das tropas mercenárias, e isto é fácil quando se tem à disposição o orçamento militar, dadas as contribuições que ele proporciona. A facilidade é ainda maior quando alguém se encontra com suas tropas em países longínquos, onde elas não podem receber outras influências a não ser a de seu general. Que isto nos sirva de norma de proceder. (Napoleão general)","page":146},{"type":"paragraph","text":"12 Sejam quais forem os braços em que nos atiremos, ainda quando realizem nosso principal desejo, acabarão por fazer-nos mais mal que bem. (Napoleão em Elba)","page":146},{"type":"paragraph","text":"13 Quase não teve outro título senão o de homem honrado, aquele famoso","page":146},{"type":"paragraph","text":"Bartolomeu Colleoni, que com tantas oportunidades para se tornar rei de Veneza, não o quis. Que tolice haver aconselhado, já moribundo, os venezianos a nunca deixarem nas mãos de outrem tanto poder militar como o que haviam conferido a ele! (Napoleão general)","page":147},{"type":"paragraph","text":"14 É com isto que convém principiar. (Napoleão general)","page":147},{"type":"paragraph","text":"15 Veremos depois se há oposições insuperáveis. (Napoleão general)","page":147},{"type":"paragraph","text":"16 Importante é ver o que promete mais. (Napoleão general)","page":147},{"type":"paragraph","text":"17 Era mister saber destruí-los. (Napoleão general)","page":147},{"type":"paragraph","text":"18 Sublime! É o melhor modelo. (Napoleão general)","page":147},{"type":"paragraph","text":"19 Porque não pudeste me servir! (Napoleão primeiro-cônsul)","page":147},{"type":"paragraph","text":"20 O diretório murmurará e decretará o que lhe aprouver; eu, porém, continuarei sendo o que sou; e haverá mister, em verdade, que meu exército me obedeça. (Napoleão general)","page":147},{"type":"paragraph","text":"21 Eis o grande benefício das conscrições. (Napoleão primeiro-cônsul)","page":147},{"type":"paragraph","text":"22 Eu teria compreendido muito mais depressa. (Napoleão imperador)","page":147},{"type":"paragraph","text":"23 É o meio mais seguro, um meio que eu devia ter usado mais frequentemente. (Napoleão general)","page":147},{"type":"paragraph","text":"24 Tanto pior para eles; e ainda não viram tudo. (Napoleão general)","page":147},{"type":"paragraph","text":"25 Digressão supérflua para mim. (Napoleão general)","page":147},{"type":"paragraph","text":"26 Restabelecerei ali o império. (Napoleão general)","page":147},{"type":"paragraph","text":"27 A divisão desaparecerá. (Napoleão general)","page":147},{"type":"paragraph","text":"28 Gregório VII, sobretudo, foi habilíssimo nessa matéria. (Napoleão general)","page":147},{"type":"paragraph","text":"29 Farei essas três forças atuarem simultaneamente para meu exclusivo benefício. (Napoleão general)","page":147},{"type":"paragraph","text":"30 Tudo isso mudará. (Napoleão primeiro-cônsul)","page":147},{"type":"paragraph","text":"31 Pobres chefes de foragidos! (Napoleão general)","page":147},{"type":"paragraph","text":"32 A esses faço-os tremer, depois de ter feito, eu sozinho, tanto quanto esses três monarcas juntos, e isso contra exércitos muitos mais formidáveis. (Napoleão primeiro-cônsul)","page":147},{"type":"paragraph","text":"33 Miserável! Lastimoso! (Napoleão general)","page":147},{"type":"paragraph","text":"34 Carece de senso comum. E os elogiam! (Napoleão general)","page":148},{"type":"paragraph","text":"35 Covardia! Idiotice! Apunhalar, fazer em pedaços, estraçalhar, destruir, aterrar... (Napoleão general)","page":148},{"type":"paragraph","text":"36 Quando é possível, cumpre fazer o contrário, para ter boas tropas. (Napoleão general)","page":148},{"type":"paragraph","text":"37 Tinha forçosamente de acontecer. (Napoleão general)","page":148},{"type":"heading","lvl":2,"title":"XIII Dos exércitos auxiliares, mistos e próprios","id":"h_o_pr_ncipe_nicolau_maquiavel_50","page":149},{"type":"paragraph","text":"1 Inúteis! É um termo forte demais. Devemos imaginar um meio de incutir-lhe a ideia de uma incorporação em nossas tropas, por meio de estratagemas de uma confederação ou de união com o grande império. (Napoleão primeirocônsul)","page":149},{"type":"paragraph","text":"2 É o que me basta. (Napoleão primeiro-cônsul)","page":149},{"type":"paragraph","text":"3 Meu sistema de aliança deve prevenir esses dois inconvenientes. (Napoleão primeiro-cônsul)","page":149},{"type":"paragraph","text":"4 Eu, que a devia confirmar, vi-me na realidade destinado a desmenti-la. (Napoleão em Elba)","page":149},{"type":"paragraph","text":"5 Essas terceiras soluções não causarão senão pesados contratempos à minha boa fortuna. (Napoleão em Elba)","page":149},{"type":"paragraph","text":"6 Isso é o que se chama ser afortunado e vencer como papa. (Napoleão general)","page":149},{"type":"paragraph","text":"7 Por certo, faremos o mesmo na Itália, onde só entramos expulsando os coligados. (Napoleão general)","page":149},{"type":"paragraph","text":"8 Nisso a Itália teve mais sorte. (Napoleão imperador)","page":149},{"type":"paragraph","text":"9 Tolo! Poderá haver outros dessa força? (Napoleão imperador)","page":149},{"type":"paragraph","text":"10 Sublime e muito profundo. (Napoleão imperador)","page":149},{"type":"paragraph","text":"11 Hesitar por quê? Por não apreciar-lhe os dotes morais, odiados por muitos tolos. Mas o que isso tem a ver com política? (Napoleão general)","page":149},{"type":"paragraph","text":"12 O que é que não se toma com essas tropas? Mas, quanto a conservá-lo, não sei. (Napoleão general)","page":149},{"type":"paragraph","text":"13 Sempre estas, de preferência a quaisquer outras. (Napoleão general)","page":149},{"type":"paragraph","text":"14 Maquiavel lisonjeia-me recordando outra vez esse herói da minha genealogia. (Napoleão general)","page":149},{"type":"paragraph","text":"15 Feliz por tê-lo podido fazer e, mais ainda, por tê-lo feito. (Napoleão general)","page":149},{"type":"paragraph","text":"16 É sempre ruim dividir com outrem, por dever, qualquer parcela de glória ou de poder adquiridos. (Napoleão general)","page":149},{"type":"paragraph","text":"17 A escolha desse exemplo é uma ingenuidade. (Napoleão general)","page":149},{"type":"paragraph","text":"18 Necessitam de tempo e de experiências funestas para compreender o que lhes é indispensável. (Napoleão em Elba)","page":149},{"type":"paragraph","text":"19 Tolo! Nem sempre. Via as coisas a seu modo. Olhava para a França como para um prado que podia ceifar todos os anos, tão rente quanto quisesse. Teve também o seu homem de Saint-Jean-d’Angely e houve-se muito bem na questão de Odet. (Napoleão primeiro-cônsul)","page":150},{"type":"paragraph","text":"20 Que diferença! Não há um único soldado meu que não se julgue capaz de vencer sozinho. (Napoleão imperador)","page":150},{"type":"paragraph","text":"21 Em grandíssima parte. (Napoleão general)","page":150},{"type":"paragraph","text":"22 E invencível; porque lhe dei outras ainda melhores. (Napoleão imperador)","page":150},{"type":"paragraph","text":"23 Ainda neste século de tantas luzes... (Napoleão em Elba)","page":150},{"type":"paragraph","text":"24 O mesmo pensei eu lendo pela primeira vez, quando menino, a história dessa decadência. (Napoleão general)","page":150},{"type":"paragraph","text":"25 Os vossos não são vossos, porém meus. (Napoleão em Elba)","page":150},{"type":"paragraph","text":"26 Não para eles. Ou, pelo menos, não tão cedo. (Napoleão em Elba)","page":150},{"type":"paragraph","text":"27 Está bem. Meu procedimento, porém, talvez fale ainda melhor. (Napoleão primeiro-cônsul)","page":150},{"type":"heading","lvl":2,"title":"XIV Das competências militares de um príncipe","id":"h_o_pr_ncipe_nicolau_maquiavel_51","page":151},{"type":"paragraph","text":"1 Dizem que vou pegar da pena para escrever minhas “Memórias”. Escrever, eu? Tomar-me-iam por néscio. Já é bastante que meu irmão Luciano faça versos. Entreter-se com mais puerilidade é renunciar ao certo. (Napoleão imperador)","page":151},{"type":"paragraph","text":"2 Demonstrarei uma coisa e outra. (Napoleão imperador)","page":151},{"type":"paragraph","text":"3 É inevitável. (Napoleão em Elba)","page":151},{"type":"paragraph","text":"4 E eu, então! (Napoleão em Elba)","page":151},{"type":"paragraph","text":"5 Como eles ficarão dentro em breve. (Napoleão em Elba)","page":151},{"type":"paragraph","text":"6 A espada e as dragonas por si sós não o evitam, se não houver mais alguma coisa. (Napoleão imperador)","page":151},{"type":"paragraph","text":"7 Pois não o estais vendo? (Napoleão em Elba)","page":151},{"type":"paragraph","text":"8 E eles pensam que o estão. (Napoleão em Elba)","page":151},{"type":"paragraph","text":"9 Ainda que eu não me intrometesse nisso. (Napoleão em Elba)","page":151},{"type":"paragraph","text":"10 Que segredo você lhes revela, Maquiavel! Mas eles não leem você e nunca lerão! (Napoleão em Elba)","page":151},{"type":"paragraph","text":"11 Aproveitei-me dos conselhos. (Napoleão imperador)","page":151},{"type":"paragraph","text":"12 Acrescente-se a isso boas cartas topográficas. (Napoleão general)","page":151},{"type":"paragraph","text":"13 Utilizei bem os seus conselhos? (Napoleão general)","page":151},{"type":"paragraph","text":"14 Nela penso até dormindo... se é que alguma vez durmo. (Napoleão general)","page":151},{"type":"paragraph","text":"15 Quantas vezes eu fiz o mesmo desde a minha mocidade? (Napoleão imperador)","page":151},{"type":"paragraph","text":"16 Nunca se preveem todas; porém, ainda que não seja fácil, acaba-se encontrando de súbito o remédio. (Napoleão general)","page":151},{"type":"paragraph","text":"17 Desgraçado o estadista que não a lê. (Napoleão em Elba)","page":151},{"type":"paragraph","text":"18 Por que não escolher mais de um que, porventura, seja superior a todos os outros? Gostei de Carlos Magno, mas César, Átila, Tamerlão, não são para desprezar. (Napoleão general).","page":151},{"type":"paragraph","text":"19 Observação tola. (Napoleão general).","page":151},{"type":"heading","lvl":2,"title":"XV Das coisas pelas quais os homens, e especialmente os príncipes, são louvados ou vituperados","id":"h_o_pr_ncipe_nicolau_maquiavel_52","page":152},{"type":"paragraph","text":"1 Primeira advertência necessária para se compreender bem Maquiavel. (Napoleão primeiro-cônsul)","page":152},{"type":"paragraph","text":"2 Ver sempre as coisas como são. (Napoleão primeiro-cônsul)","page":152},{"type":"paragraph","text":"3 As fantasias de Platão valem, na prática, quase tanto quanto as de JeanJacques Rousseau. (Napoleão primeiro-cônsul)","page":152},{"type":"paragraph","text":"4 É a esse respeito que os estadistas julgam os visionários da moral e da filosofia. (Napoleão primeiro-cônsul)","page":152},{"type":"paragraph","text":"5 Se nem todos são maus, os que não são possuem tais recursos e atividade que é como se todos o fossem. Os mais perversos são, em geral, os que ao nosso lado afetam ser os melhores. (Napoleão imperador)","page":152},{"type":"paragraph","text":"6 Digam o que quiserem. O essencial é manter-se e conservar a boa ordem do Estado. (Napoleão primeiro-cônsul)","page":152},{"type":"paragraph","text":"7 Escolha, se puder. (Napoleão primeiro-cônsul)","page":152},{"type":"paragraph","text":"8 Sim, como Luís XVI. Mas acaba-se também perdendo o reino e a cabeça. (Napoleão imperador)","page":152},{"type":"paragraph","text":"9 Conselho de moralista. (Napoleão imperador)","page":152},{"type":"paragraph","text":"10 Quanto a isso, pouco se me dá o que dirão. (Napoleão imperador)","page":152},{"type":"heading","lvl":2,"title":"XVI Da liberalidade e da parcimônia","id":"h_o_pr_ncipe_nicolau_maquiavel_53","page":153},{"type":"paragraph","text":"1 És também muito evangélico. De que valeria ser liberal se não fosse para satisfazer o interesse e a vaidade? (Napoleão primeiro-cônsul)","page":153},{"type":"paragraph","text":"2 Isso me diz respeito até certo ponto; mas recobrarei a estima com façanhas enganadoras. (Napoleão imperador)","page":153},{"type":"paragraph","text":"3 Irei em busca de dinheiro em todos os países estrangeiros. (Napoleão imperador)","page":153},{"type":"paragraph","text":"4 Ave de mau agouro, espero que nisso tenhas mentido! (Napoleão imperador)","page":153},{"type":"paragraph","text":"5 A mim pouco me inquietaria. (Napoleão imperador)","page":153},{"type":"paragraph","text":"6 Espírito medroso! (Napoleão imperador)","page":153},{"type":"paragraph","text":"7 Pobre coitado! (Napoleão imperador)","page":153},{"type":"paragraph","text":"8 A palavra “liberal”, entendida metafisicamente, serviu-me quase que da mesma forma. Expressões “ideias liberais”, “modo de pensar liberal”, que pelo menos os ideólogos não arrumam e aformoseiam, são, contudo, de minha invenção. Ideado por mim, esse talismã aproveitará minha causa e falará sempre a favor de meu reinado, ainda em poder dos que me destronaram. (Napoleão em Elba)","page":153},{"type":"paragraph","text":"9 Ideia mesquinha. (Napoleão imperador)","page":153},{"type":"paragraph","text":"10 Tolice. (Napoleão imperador)","page":153},{"type":"paragraph","text":"11 Não seria esse defeito com que eu mais contaria. (Napoleão imperador)","page":153},{"type":"paragraph","text":"12 Meus generais sabem o que lhes dei antes e aonde teria que chegar para lhes conferir ducados e bastões de marechal. (Napoleão imperador)","page":153},{"type":"paragraph","text":"13 Fui liberal em atos e palavras. Quantos tolos não conseguimos iludir com o falso ouropel das ideias liberais! (Napoleão primeiro-cônsul)","page":153},{"type":"paragraph","text":"14 Há de julgar-me. (Napoleão primeiro-cônsul)","page":153},{"type":"paragraph","text":"15 Quem o fez melhor que eu? (Napoleão imperador)","page":153},{"type":"paragraph","text":"16 Eis a razão por que consenti nos saques e pilhagens. Dava-lhes tudo quanto podia tomar, daí seu imutável apego à minha pessoa. (Napoleão em Elba)","page":153},{"type":"paragraph","text":"17 E eu. (Napoleão imperador)","page":153},{"type":"paragraph","text":"18 Que serve para aumentar a outra. (Napoleão imperador)","page":153},{"type":"paragraph","text":"19 Quando não se conhecem outros meios para sustentá-la. (Napoleão imperador)","page":154},{"type":"paragraph","text":"20 Isso, a bem dizer, não me inquieta. (Napoleão imperador)","page":154},{"type":"paragraph","text":"21 No final das contas, pouco me importou. Terei sempre a estima e o amor dos meus soldados... dos meus senadores, prefeitos, etc. (Napoleão imperador)","page":154},{"type":"heading","lvl":2,"title":"XVII Da crueldade e da clemência. É melhor ser amado ou temido?","id":"h_o_pr_ncipe_nicolau_maquiavel_54","page":155},{"type":"paragraph","text":"1 Isso ocorre sempre quando alguém chega com grandes pretensões à glória da clemência. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"2 Não cessem de clamar que esse Bórgia era um monstro do qual cumpre desviar os olhos; não cessem, para que não se aprenda com ele aquilo que poderia me estragar os planos. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"3 Evite dizer-lhes isso. Eles, de resto, não parecem inclinados a compreender você. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"4 Convém-me que todos fiquem ofendidos, ainda quando não seja senão com a impunidade de alguns. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"5 São novos; o Estado é novo para eles; só desejam ser clementes. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"6 Felizmente, porém, Virgílio não é o poeta mais apreciado. (Napoleão em Elba) * Eneida, livro I. (N. do E.)","page":155},{"type":"paragraph","text":"7 É fácil de dizer. (Napoleão primeiro-cônsul)","page":155},{"type":"paragraph","text":"8 Perfeito! Sublime! (Napoleão primeiro-cônsul)","page":155},{"type":"paragraph","text":"9 Para mim, não é uma questão. (Napoleão primeiro-cônsul)","page":155},{"type":"paragraph","text":"10 Não preciso então mais que uma. (Napoleão primeiro-cônsul)","page":155},{"type":"paragraph","text":"11 Os que diziam ser bons todos os homens queriam iludir os príncipes. (Napoleão primeiro-cônsul)","page":155},{"type":"paragraph","text":"12 Conte com isso. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"13 Que bom bilhete tem La Châtre! (Napoleão em Elba)","page":155},{"type":"paragraph","text":"14 É mister, porém, saber em que consiste ela num príncipe de Estado tão difícil de governar. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"15 Acreditam justamente o contrário. (Napoleão em Elba)","page":155},{"type":"paragraph","text":"16 É preciso castigá-lo continuamente. (Napoleão primeiro-cônsul)","page":155},{"type":"paragraph","text":"17 Já é restringir muito as prerrogativas dos príncipes (Napoleão imperador)","page":155},{"type":"paragraph","text":"18 Isso é extremamente difícil. (Napoleão imperador)","page":155},{"type":"paragraph","text":"19 Quando não os temos reais, fabricamo-los. Para minhas importantes providências governativas tenho homens mais sábios que Gabriel Mandé.","page":155},{"type":"paragraph","text":"(Napoleão primeiro-cônsul)","page":156},{"type":"paragraph","text":"20 É a única mistificação pérfida que me fez a sua carta. (Napoleão em Elba)","page":156},{"type":"paragraph","text":"21 Observação profunda que ainda não me havia ocorrido. (Napoleão em Elba)","page":156},{"type":"paragraph","text":"22 Essa facilidade em achar pretextos é uma das vantagens de minha autoridade. (Napoleão primeiro-cônsul)","page":156},{"type":"paragraph","text":"23 Ignorante! Não sabia que os engendramos. (Napoleão primeiro-cônsul)","page":156},{"type":"paragraph","text":"24 Principiei por aí com o fim de fazer marchar para a Itália o exercício cujo comando me foi conferido em 1796. (Napoleão general)","page":156},{"type":"paragraph","text":"25 O meu não apresentava menos elementos de discórdia e de rebelião quando o fiz entrar na Itália. (Napoleão general)","page":156},{"type":"paragraph","text":"26 Outro tanto se pode dizer do meu. (Napoleão general)","page":156},{"type":"paragraph","text":"27 Sem dúvida alguma. (Napoleão general)","page":156},{"type":"paragraph","text":"28 Assim nos julgam sempre. (Napoleão general)","page":156},{"type":"paragraph","text":"29 Admiração sobremaneira tola. (Napoleão general)","page":156},{"type":"paragraph","text":"30 Ninguém deve dá-la senão quando isso lhe traz proveito. (Napoleão general)","page":156},{"type":"paragraph","text":"31 Mais vale a segunda qualidade que a primeira. (Napoleão general)","page":156},{"type":"paragraph","text":"32 Glória extravagante, na verdade! (Napoleão general)","page":156},{"type":"paragraph","text":"33 É sempre o meio mais seguro. (Napoleão primeiro-cônsul)","page":156},{"type":"paragraph","text":"34 A não ser que isso dê muito trabalho e crie grandes tropeços. (Napoleão primeiro-cônsul)","page":156},{"type":"heading","lvl":2,"title":"XVIII Da maneira pela qual os príncipes devem honrar a sua palavra","id":"h_o_pr_ncipe_nicolau_maquiavel_55","page":157},{"type":"paragraph","text":"1 Admirando até esse ponto a lealdade, a honradez, a sinceridade, Maquiavel nem parece estadista. (Napoleão general)","page":157},{"type":"paragraph","text":"2 Os grandes exemplos obrigam-no a falar conforme o meu modo de dar outros semelhantes. (Napoleão general)","page":157},{"type":"paragraph","text":"3 Até que ainda se pode aperfeiçoar. (Napoleão general)","page":157},{"type":"paragraph","text":"4 Os tolos estão neste mundo para nos servirmos deles. (Napoleão general)","page":157},{"type":"paragraph","text":"5 É o melhor, considerando que só temos de tratar com animais. (Napoleão primeiro-cônsul)","page":157},{"type":"paragraph","text":"6 Explicação que ninguém soube dar antes de Maquiavel. (Napoleão general)","page":157},{"type":"paragraph","text":"7 Tudo isso está muito certo quando aplicado à política, como o faz Maquiavel. (Napoleão general)","page":157},{"type":"paragraph","text":"8 O modelo, contudo, é admirável. (Napoleão general)","page":157},{"type":"paragraph","text":"9 Não há outro partido a tomar. (Napoleão general)","page":157},{"type":"paragraph","text":"10 Pública retratação de moralista. (Napoleão general)","page":157},{"type":"paragraph","text":"11 Isso basta para não confiar, mas não serve de desculpa aos que são como o resto: malvados e falsos. (Cristina da Suécia)","page":157},{"type":"paragraph","text":"12 Par pari refertur (Igual com igual se paga). (Napoleão general)","page":157},{"type":"paragraph","text":"13 Tenho para isto homens de talento. (Napoleão imperador)","page":157},{"type":"paragraph","text":"14 Em geral, para os vassalos há nisso mais benefício do que escândalo. (Napoleão imperador)","page":157},{"type":"paragraph","text":"15 Os mais hábeis não são capazes de superar-me. O papa pode dar disso testemunho. (Napoleão primeiro-cônsul)","page":157},{"type":"paragraph","text":"16 Mentes atrevidamente. O mundo está constituído por tolos. Entre a multidão, essencialmente crédula, contar-se-ão pouquíssimos indivíduos céticos, e estes mesmos não ousarão confessar que o são. (Napoleão primeiro-cônsul)","page":157},{"type":"paragraph","text":"17 Não faltam. (Napoleão primeiro-cônsul)","page":157},{"type":"paragraph","text":"18 Que homem terrível! Se não honrou o sólio, pelo menos estendeu os seus domínios, e a Santa Sé muito lhe deve. Soou a hora do contraponto. (Napoleão imperador)","page":157},{"type":"paragraph","text":"19 Os tolos que julgarem ser esse um conselho para todos não sabem a enorme diferença que há entre um príncipe e os vassalos. (Napoleão imperador)","page":157},{"type":"paragraph","text":"20 Nos tempos de hoje, vale mais parecer honrado que sê-lo realmente. (Napoleão imperador)","page":158},{"type":"paragraph","text":"21 Supondo que tenha uma. (Napoleão primeiro-cônsul)","page":158},{"type":"paragraph","text":"22 Maquiavel é severo. (Napoleão primeiro-cônsul)","page":158},{"type":"paragraph","text":"23 Isto também é exigir muito. A coisa não é tão fácil. Faz-se o que é possível. (Napoleão primeiro-cônsul)","page":158},{"type":"paragraph","text":"24 Bom conselho para o tempo dele. (Napoleão primeiro-cônsul)","page":158},{"type":"paragraph","text":"25 Não se pode fingir por muito tempo o que não se é. (Cristina da Suécia) Ah! Ainda que eles o sentissem... (Napoleão primeiro-cônsul)","page":158},{"type":"paragraph","text":"26 É justamente nisso que eu confio. (Napoleão primeiro-cônsul)","page":158},{"type":"paragraph","text":"27 Triunfe sempre, pouco importa como, e você nunca deixará de ter razão. (Napoleão imperador)","page":158},{"type":"paragraph","text":"28 Fatal, mil vezes fatal a retirada de Moscou! (Napoleão em Elba) * Alusão a Fernando II de Aragão. (N. do E.)","page":158},{"type":"heading","lvl":2,"title":"XIX De que maneira é preciso evitar o desprezo e o ódio","id":"h_o_pr_ncipe_nicolau_maquiavel_56","page":159},{"type":"paragraph","text":"1 Não preciso recear o menosprezo. Realizei grandes coisas e de bom ou mau grado admirar-me-ão. Quanto ao ódio, hei de opor-lhe vigorosos contrapesos (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"2 Isso me é necessário. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"3 Modus est in rebus (Para tudo há um limite). (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"4 Não tão fácil assim. (Napoleão imperador)","page":159},{"type":"paragraph","text":"5 De que vale esse cuidado se não o tomamos logo no início? (Napoleão em Elba)","page":159},{"type":"paragraph","text":"6 Essencial para tirar toda a esperança de perdão aos conspiradores, sem o que você morre. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"7 Tem-se muito mais que o pensamento: tem-se a esperança e a facilidade, com a certeza do triunfo. (Napoleão em Elba)","page":159},{"type":"paragraph","text":"8 Há sempre valentões que não o estimam. (Napoleão em Elba)","page":159},{"type":"paragraph","text":"9 Disso dei provas admiráveis e o meu casamento é a sua mais alta expressão. (Napoleão imperador)","page":159},{"type":"paragraph","text":"10 Esmaguei as que se tramaram. (Napoleão imperador)","page":159},{"type":"paragraph","text":"11 Tolice. (Napoleão imperador)","page":159},{"type":"paragraph","text":"12 Não me diz respeito. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"13 Tranquiliza-me. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"14 Atira-se-lhe nos braços um suposto descontente; e, depois, atribui-se tudo à Providência. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"15 Especialmente se o comprei antes. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"16 Pode contar com boas gratificações. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"17 De um lado, só perigos; do outro, só vantagens. (Napoleão primeiro-cônsul)","page":159},{"type":"paragraph","text":"18 Quanto a isso, minhas precauções chegam ao mais alto grau de eficácia. (Napoleão imperador)","page":159},{"type":"paragraph","text":"19 Ficam sempre, decerto, bastantes êmulos, mas a polícia se encarregará deles (Napoleão imperador)","page":159},{"type":"paragraph","text":"20 O povo! Não é ele ingrato e não se coloca sempre ao lado de quem vence, sobretudo quando este o deslumbra? (Napoleão imperador)","page":159},{"type":"paragraph","text":"21 O espírito efeminado da nossa época não permite que eles se renovem. (Napoleão primeiro-cônsul)","page":160},{"type":"paragraph","text":"22 Fossem eles capazes de ir fazer coisas semelhantes em Viena, já que não o foram de vir me buscar, camus et non! (Napoleão em Elba)","page":160},{"type":"paragraph","text":"23 Aqui Maquiavel se esquece de ter ele mesmo dito que os homens são maus. (Napoleão imperador)","page":160},{"type":"paragraph","text":"24 O sono afasta-se de mim. (Napoleão imperador)","page":160},{"type":"paragraph","text":"25 Mas os grandes que me vi obrigado a fazer irritam-se quando por um momento deixo de enriquecê-los. (Napoleão imperador)","page":160},{"type":"paragraph","text":"26 Não é possível aplacar esses ambiciosos sem descontentar o povo. (Napoleão imperador)","page":160},{"type":"paragraph","text":"27 Você tem razão de se admirar disso; mas era mister dissolvê-lo para conseguir a destruição do trono dos Bourbon, sem o que, afinal de contas, não teria podido erguer-se o meu. Farei o mesmo estatuto o mais cedo possível. (Napoleão imperador)","page":160},{"type":"paragraph","text":"28 Admirável. (Napoleão imperador)","page":160},{"type":"paragraph","text":"29 No atual Estado cabem a ele todos os assuntos que exigem rigor, e seus ministros reservam para si próprios a concessão de todas as graças. Às mil maravilhas. (Napoleão em Elba)","page":160},{"type":"paragraph","text":"30 Que as pessoas leem como se fosse um simples romance. (Napoleão primeiro-cônsul)","page":160},{"type":"paragraph","text":"31 Bem sei. (Napoleão imperador)","page":160},{"type":"paragraph","text":"32 Minha situação é difícil. E não se deve imputar ambição guerreira a mim, mas aos meus soldados e generais, que a transformam em gênero de primeira necessidade. Matar-me-iam se os deixasse mais de dois anos sem lhes apresentar a isca de uma guerra. (Napoleão imperador)","page":160},{"type":"paragraph","text":"33 A isso me obrigam idênticos motivos. Os soldados são iguais em toda parte, quando se depende deles. (Napoleão imperador)","page":160},{"type":"paragraph","text":"34 Logrei conter ambos, mas ainda não é suficiente. (Napoleão imperador)","page":160},{"type":"paragraph","text":"35 Não há necessidade de me fazer de desentendido, todavia, sob todos os aspectos, acho-me no mesmo caso. (Napoleão imperador)","page":160},{"type":"paragraph","text":"36 É essa a minha desculpa aos olhos da posteridade. (Napoleão imperador)","page":160},{"type":"paragraph","text":"37 Eis uma grande verdade. (Napoleão imperador)","page":161},{"type":"paragraph","text":"38 É sempre o exército, quando tem tantos soldados como o meu. (Napoleão imperador)","page":161},{"type":"paragraph","text":"39 Hei de fazer tudo para consegui-lo. Assim me vejo forçado. (Napoleão imperador)","page":161},{"type":"paragraph","text":"40 Virtudes intempestivas, nesse caso. É digno de compreensão quem não sabe aplicar as virtudes de acordo com as circunstâncias. (Napoleão imperador)","page":161},{"type":"paragraph","text":"41 Nem podia ser de outro modo. Eu tê-lo-ia previsto. (Napoleão imperador)","page":161},{"type":"paragraph","text":"42 Esse destino está reservado a meu filho. (Napoleão imperador)","page":161},{"type":"paragraph","text":"43 Se me fosse dado ressuscitar para suceder a meu filho, seria adorado. (Napoleão imperador)","page":161},{"type":"paragraph","text":"44 É natural que assim seja. (Napoleão em Elba)","page":161},{"type":"paragraph","text":"45 É inevitável. (Napoleão em Elba)","page":161},{"type":"paragraph","text":"46 Não me diz respeito. (Napoleão em Elba)","page":161},{"type":"paragraph","text":"47 E eles não podem deixar de sê-lo. (Napoleão em Elba)","page":161},{"type":"paragraph","text":"48 É, certamente, o que desejam fazer; mas corrompem e desconhecem a força de seus partidários. (Napoleão em Elba)","page":161},{"type":"paragraph","text":"49 Isso é inevitável. (Napoleão em Elba)","page":161},{"type":"paragraph","text":"50 Quem é sempre bom não pode evitar essa reputação. (Napoleão em Elba)","page":161},{"type":"paragraph","text":"51 Pior ainda quando alguém é obrigado a sê-lo nas mãos de ministros ineptos e antipatizados. (Napoleão imperador)","page":161},{"type":"paragraph","text":"52 Modelo sublime que não cessei de contemplar! (Napoleão imperador)","page":161},{"type":"paragraph","text":"53 O respeito e a admiração fazem-nos proceder como se o estivessem. (Napoleão imperador)","page":161},{"type":"paragraph","text":"54 Disso sempre estive convencido. (Napoleão imperador)","page":161},{"type":"paragraph","text":"55 Eu quis imitar esse rasgo em Frutidor de 1797 quando dizia aos meus soldados da Itália que o corpo legislativo assassinara a liberdade republicana na França, mas para aí não pude conduzi-los nem eu mesmo ir. O tiro saiu errado então, porém, não depois. (Napoleão imperador)","page":161},{"type":"paragraph","text":"56 Exatamente como o meu regresso do Egito. (Napoleão imperador)","page":161},{"type":"paragraph","text":"57 Meu Dídio era pura e simplesmente o Diretório, e para destruí-lo bastava dissolvê-lo. (Napoleão imperador)","page":162},{"type":"paragraph","text":"58 Nomearam-me chefe de todas as tropas reunidas em Paris e arredores, e, por isso, árbitro de ambos os conselhos. (Napoleão imperador)","page":162},{"type":"paragraph","text":"59 Meu Nigro e meu Albino não passavam, respectivamente, de Barras e Sieyès. Não eram formidáveis. Nenhum deles procedia por conta própria e eu queria que se diferenciassem em seus intentos. O primeiro almejava a restauração do rei, e o segundo a subida ao trono do eleitor de Brunswick. Mas o meu desejo era diferente, e Sétimo, em meu lugar, não se teria havido melhor. (Napoleão imperador)","page":162},{"type":"paragraph","text":"60 Bastava-me remover o meu Nigro e era-me fácil enganar o meu Albino. (Napoleão imperador)","page":162},{"type":"paragraph","text":"61 Assim fiz nomear Sieyès para colega meu na comissão consular. RogerDucos, que também aceitei por membro dela, só podia ser um contrapeso ao meu dispor. (Napoleão imperador)","page":162},{"type":"paragraph","text":"62 Não precisava de tão amplas manobras para me desembaraçar de Sieyès. Mais astuto que ele, consegui-o em minha junta de 22 de frimário, na qual eu mesmo arranjei a Constituição que me fez primeiro-cônsul e afastou os dois colegas, mandando-os para o meu Senado. (Napoleão imperador)","page":162},{"type":"paragraph","text":"63 Não me censurarão por não o ter sido, nem por sombra, em tal conjuntura. (Napoleão imperador)","page":162},{"type":"paragraph","text":"64 A minha não pode ser maior por agora, e hei de sustentá-la. (Napoleão imperador)","page":162},{"type":"paragraph","text":"65 Aproveitarei todas as oportunidades para lhe conquistar o amor por esse meio. (Napoleão imperador)","page":162},{"type":"paragraph","text":"66 Pouco hábil. (Napoleão imperador)","page":162},{"type":"paragraph","text":"67 Jamais ocorrem quando o príncipe impõe respeito com grande genial integridade. (Napoleão imperador)","page":162},{"type":"paragraph","text":"68 Quando as tivermos ofendido, deveremos removê-las, transferi-las, desterrálas, honrosamente ou não. (Napoleão imperador)","page":162},{"type":"paragraph","text":"69 Tolo, estúpido, embrutecido. (Napoleão imperador)","page":162},{"type":"paragraph","text":"70 Dá pena. Não merece que eu detenha, um instante sequer, meu olhar nele. (Napoleão imperador)","page":162},{"type":"paragraph","text":"71 Era justo. Não é possível ser mais indigno de reinar. (Napoleão imperador)","page":163},{"type":"paragraph","text":"72 Ser desprezado é o pior de todos os males. (Napoleão imperador)","page":163},{"type":"paragraph","text":"73 Nunca faltam meios para ocultar isso. (Napoleão imperador)","page":163},{"type":"paragraph","text":"74 Por que não desaprovava esses atos depois, mandando castigá-los?","page":163},{"type":"paragraph","text":"75 É digno disso quem deixa as coisas chegarem a tal extremo. (Napoleão imperador)","page":163},{"type":"paragraph","text":"76 Realmente, não me causa dificuldades. (Napoleão imperador)","page":163},{"type":"paragraph","text":"77 Tratemos de mudar com frequência as guarnições. (Napoleão imperador)","page":163},{"type":"paragraph","text":"78 Meu interesse exige que entre uns e outros haja certo equilíbrio, sem maior inclinação para um lado que para outro. (Napoleão primeiro-cônsul)","page":163},{"type":"paragraph","text":"79 A minha guarda imperial pode, sendo necessário, fazer o papel de janízaros. (Napoleão imperador)","page":163},{"type":"paragraph","text":"80 O mesmo devo eu fazer. (Napoleão imperador)","page":163},{"type":"paragraph","text":"81 Quer nos preocupemos, quer não, precisamos possuir uma guarda forte, com a qual possamos contar, ainda quando haja desertores entre as outras por demais ligadas ao povo. (Napoleão imperador)","page":163},{"type":"paragraph","text":"82 A comparação é curiosa, mas verdadeira aos olhos de todo pensador político. (Napoleão imperador)","page":163},{"type":"paragraph","text":"83 Os cardeais criam, efetivamente, o governo temporal de Roma, assim como os próceres do Egito criavam seu príncipe. (Napoleão imperador)","page":163},{"type":"paragraph","text":"84 Sê-lo assim é a melhor sorte que se pode ter. (Napoleão imperador)","page":163},{"type":"paragraph","text":"85 Há alguma coisa boa em cada um desses modelos; é mister saber escolher. Só os tolos podem restringir-se a um único e imitá-lo em tudo. (Napoleão imperador)","page":163},{"type":"paragraph","text":"86 Quem será capaz de imitar as minhas? (Napoleão imperador)","page":163},{"type":"paragraph","text":"87 Conclusão perfeita; todavia, ainda não posso renunciar aos procedimentos de Severo. (Napoleão imperador)","page":163},{"type":"heading","lvl":2,"title":"XX Se as fortalezas e muitas outras coisas que um príncipe realiza cotidianamente são úteis ou não","id":"h_o_pr_ncipe_nicolau_maquiavel_57","page":164},{"type":"paragraph","text":"1 Um mesmo príncipe pode ver-se compelido a fazer isso tudo no decurso de seu reinado, conforme a época e as circunstâncias. (Napoleão imperador)","page":164},{"type":"paragraph","text":"2 Fala, que eu me encarregarei das consequências práticas. (Napoleão imperador)","page":164},{"type":"paragraph","text":"3 Assim procederam os hábeis defensores da Revolução. Fazendo-se príncipes da França, transformaram os estados-gerais por meio de uma assembleia nacional e armaram logo todo o povo para formar um exército nacional em seu próprio benefício. Por que conservam as guardas urbanas e comunais o título de nacionais, que hoje não mais lhes quadra? É forçoso que o percam, mas gradativamente. Não passam nem devem passar de guardas urbanas ou provinciais. Assim o exigem a boa ordem e o juízo sadio. (Napoleão imperador)","page":164},{"type":"paragraph","text":"4 Os grandes forjadores da Revolução Francesa queriam, realmente, armar só o povo. Os poucos nobres que deixaram que se introduzissem na guarda nacional não lhes causavam receio. Sabiam muito bem que não tardariam em expulsá-los, e o povo, julgando-se o único favorecido, só a eles pertenceu. (Napoleão imperador)","page":164},{"type":"paragraph","text":"5 Que resultado obterá dando esse difícil passo, com tantos corpos de guardas nacionais que não lhe obedecem? (Napoleão em Elba)","page":164},{"type":"paragraph","text":"6 Não há mais tropas dessa espécie. (Napoleão em Elba)","page":164},{"type":"paragraph","text":"7 Duvido que os aliados que estão na França possam impedir isso. Ademais, em breve irão embora. (Napoleão em Elba)","page":164},{"type":"paragraph","text":"8 Neste momento, não o podem fazer, embora fosse urgente. Conservam, porém, o meu, para o qual eu sou tudo. (Napoleão em Elba)","page":164},{"type":"paragraph","text":"9 Não me esqueci disso na Itália. (Napoleão primeiro-cônsul)","page":164},{"type":"paragraph","text":"10 Vi-os com prazer tomarem horror ao serviço e estava convencido de que, passado o 1º de fevereiro, cansar-se-iam dele. (Napoleão primeiro-cônsul)","page":164},{"type":"paragraph","text":"11 O melhor é não colocar como guarda do país conquistado senão regimentos de cuja fidelidade esteja seguro. (Napoleão primeiro-cônsul)","page":164},{"type":"paragraph","text":"12 Esse raciocínio não se deve tomar ao pé da letra porque nos tempos de Maquiavel os cidadãos eram também soldados, no caso de se verificar algum ataque à sua cidade. Hoje, para defender uma cidade atacada, já ninguém conta com os cidadãos, mas com as boas tropas que nela hajam sido colocadas. Penso, pois, como os antigos florentinos, que é bom manter facções de qualquer gênero nas cidades e províncias a fim de ocupá-las caso se mostrem turbulentas; mas com a condição, é claro, de que nenhuma delas me combata. (Napoleão primeiro-cônsul)","page":164},{"type":"paragraph","text":"13 Estratagema de que frequentemente fiz uso, com bom resultado. Às vezes, atiro no meio deles algumas sementes de discórdias particulares quando quero desviar-lhes a atenção dos negócios de Estado ou quando preparo em segredo alguma lei extraordinária. (Napoleão imperador).","page":165},{"type":"paragraph","text":"14 Às vezes, quem sabe, é também sinal de prudência e habilidade. (Napoleão imperador)","page":165},{"type":"paragraph","text":"15 Em tempo de guerra é mister distraí-los de outra maneira para contentá-los. (Napoleão imperador)","page":165},{"type":"paragraph","text":"16 Podia alguém superá-las melhor que eu as superei? (Napoleão imperador)","page":165},{"type":"paragraph","text":"17 Quantas escadas me ofereceram? Aproveitei-as bem. (Napoleão imperador)","page":165},{"type":"paragraph","text":"18 Maquiavel deve estar contente com os benefícios que tirei desse conselho. (Napoleão imperador)","page":165},{"type":"paragraph","text":"19 Isso pode ser verdade quanto a outros; porém, no que a mim se refere, quase não o é. (Napoleão imperador)","page":165},{"type":"paragraph","text":"20 Ainda bem! (Napoleão imperador)","page":165},{"type":"paragraph","text":"21 Tal como ganhei certos nobres, que, por ambição ou falta de dinheiro, precisavam de empregos, e os emigrados, aos quais abri as portas da França e lhes restituí os bens... (Napoleão imperador)","page":165},{"type":"paragraph","text":"22 O que não fizeram comigo para esse fim? (Napoleão imperador)","page":165},{"type":"paragraph","text":"23 É necessário saber perturbar tal segurança quando se desconfia que afrouxa; e, ainda quando não haja motivo para desconfiar, algumas violências intempestivas surtem sempre bom efeito. (Napoleão imperador)","page":165},{"type":"paragraph","text":"24 Quiseram-me somente para que os enchesse de bens, e como são insaciáveis, quereriam da mesma forma a outro príncipe que me substituísse, para que também fizesse o mesmo. A alma deles é o tonel das danaides e a ambição, o abutre de Prometeu. (Napoleão imperador)","page":165},{"type":"paragraph","text":"25 Tais são os realistas moderados. (Napoleão imperador)","page":165},{"type":"paragraph","text":"26 Por ambição frustrada. (Napoleão imperador)","page":165},{"type":"paragraph","text":"27 Reflexão de algum valor. (Napoleão imperador)","page":166},{"type":"paragraph","text":"28 Assim se construiu a Bastilha, no reinado de Carlos, o Sábio, para manter quietos os parisienses, e o castelo Trombeta, de Bordéus, no de Carlos VIII, para fazer o mesmo em relação aos bordegalenses. Não percamos isso de vista. (Napoleão imperador)","page":166},{"type":"paragraph","text":"29 Na primeira ocasião mandarei construir uma nas alturas de Montmartre para impor respeito aos parisienses. Porém, não tive nenhuma quando eles me entregaram covardemente aos aliados! O castelo Trombeta contará os traidores do Garona. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"30 Destruirei todas as da Itália, com exceção da de Mântua e de Alexandria, que hei de fortificar o mais que puder. (Napoleão general)","page":166},{"type":"paragraph","text":"31 Quando se receia igualmente uns e outros, convém erguê-las em todos os pontos fracos. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"32 Porém, se nos odeiam, o mal que nos causam é frequentemente superior ao que porventura nos faça uma centena de amigos.","page":166},{"type":"paragraph","text":"33 Não o creio. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"34 Naquela época. Hoje o caso é outro. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"35 Isso, por certo, é bastante para justificar as fortalezas. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"36 Não tinha um exército igual ao meu. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"37 Se tinha apenas isso para se defender, acredito perfeitamente. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"38 Não ser odiado pelo povo? Volta sempre a essa puerilidade. As fortalezas equivalem, sem dúvida alguma, ao amor do povo. (Napoleão em Elba)","page":166},{"type":"paragraph","text":"39 Podes aplaudir-me desde já. (Napoleão em Elba)","page":166},{"type":"heading","lvl":2,"title":"XXI Como um príncipe deve se comportar para que seja apreciado","id":"h_o_pr_ncipe_nicolau_maquiavel_58","page":167},{"type":"paragraph","text":"1 Com elas me elevei e unicamente com elas hei de me manter. Se não me lançasse em outras novas que sobrepujassem as anteriores, decairia. (Napoleão imperador)","page":167},{"type":"paragraph","text":"2 Existem os de muitas espécies. (Napoleão em Elba)","page":167},{"type":"paragraph","text":"3 Chegarei a ser outro tanto. (Napoleão em Elba)","page":167},{"type":"paragraph","text":"4 Não mais que as minhas. (Napoleão imperador)","page":167},{"type":"paragraph","text":"5 Farei o mesmo com a Espanha. (Napoleão primeiro-cônsul)","page":167},{"type":"paragraph","text":"6 Minha situação quando acometi a Espanha diversifica muito da sua e não me permitia alcançar triunfos iguais. Ademais, eu podia prescindir deles. (Napoleão imperador)","page":167},{"type":"paragraph","text":"7 Fernando foi mais feliz que eu ou teve oportunidades mais favoráveis. Mandar meu irmão (ah! que irmão!) não era porventura eu mesmo ir? (Napoleão imperador)","page":167},{"type":"paragraph","text":"8 Minha devoção à concordata não me permitia mais que expulsar os sacerdotes que se haviam mostrado e continuavam a se mostrar ainda avessos ao cumprimento das promessas e juramentos. Dóceis e jesuíticos era como eu os queria. De quando em quando, maltratarei os “padres da fé”. Fesch os protegerá e eles o farão papa. (Napoleão primeiro-cônsul)","page":167},{"type":"paragraph","text":"9 Manter embasbacados os povos sob o meu domínio, dando-lhes continuamente motivo para falar de minhas vitórias ou de meus projetos engrandecidos pelo gênio da ambição não pode deixar de ser-me de grande utilidade. (Napoleão primeiro-cônsul)","page":167},{"type":"paragraph","text":"10 A isso me dediquei de maneira especial em meus tratados de paz, mandando inserir sempre alguma cláusula suscetível de gerar pretexto de uma nova guerra imediata. (Napoleão imperador)","page":167},{"type":"paragraph","text":"11 É alvo meu na rápida sucessão de minhas empresas. (Napoleão imperador)","page":167},{"type":"paragraph","text":"12 Convém que essas coisas deslumbrem com o fausto e que não estejam inteiramente despidas de algumas aparências de utilidade pública. (Napoleão imperador)","page":167},{"type":"paragraph","text":"13 A instituição de meus prêmios decenais. (Napoleão imperador)","page":167},{"type":"paragraph","text":"14 Nessa matéria, nada mais se pode inventar. (Napoleão imperador)","page":167},{"type":"paragraph","text":"15 Compreendo-te e adapto-me aos seus conselhos. (Napoleão imperador)","page":167},{"type":"paragraph","text":"16 Salvo fazermos, depois, exatamente o contrário. (Napoleão primeiro-cônsul)","page":168},{"type":"paragraph","text":"17 Indício da maior fraqueza em armas e talento. (Napoleão primeiro-cônsul)","page":168},{"type":"paragraph","text":"18 Seja; não receio nenhum em particular, e mantê-los-ei divididos até que os possa reunir todos a mim. (Napoleão primeiro-cônsul)","page":168},{"type":"paragraph","text":"19 Não há outra coisa a fazer. (Napoleão imperador)","page":168},{"type":"paragraph","text":"20 Assim como os neutros das alianças anteriores foram presas de mim. (Napoleão imperador)","page":168},{"type":"paragraph","text":"21 Disso me aproveito sempre à custa deles. (Napoleão imperador)","page":168},{"type":"paragraph","text":"22 Boa reflexão para os outros e, sobretudo, para os que nunca tiveram bastante bom senso para fazê-la. (Napoleão imperador)","page":168},{"type":"paragraph","text":"23 Hei de levar os príncipes da Alemanha a falar assim, quando se tratar da mim, na famosa expedição à Rússia. Farei que os outros marchem sem isso. (Napoleão imperador)","page":168},{"type":"paragraph","text":"24 Mostraram-se débeis e por isso mesmo não podiam escapar à perdição. (Napoleão imperador)","page":168},{"type":"paragraph","text":"25 Valiam, pois, os homens de então mais que os de agora, em que semelhantes considerações não têm cabimento nem são feitas? Nosso século das luzes dilatou maravilhosamente a esfera da ciência política. (Napoleão imperador)","page":168},{"type":"paragraph","text":"26 Cada qual a entende a seu modo. (Napoleão imperador)","page":168},{"type":"paragraph","text":"27 Bom para os principiantes. (Napoleão imperador)","page":168},{"type":"paragraph","text":"28 A Rússia não viu isso quando abandonou a Áustria às minhas armas. Verei melhor quando se tratar de investir contra ela. A Áustria e a Prússia, por mais interessadas que estejam na própria conservação, podem se deixar arrastar por mim. (Napoleão imperador)","page":168},{"type":"paragraph","text":"29 Todos eles chegarão a isso. (Napoleão imperador)","page":168},{"type":"paragraph","text":"30 Quando me convier, farei que sintam essa necessidade. (Napoleão imperador)","page":168},{"type":"paragraph","text":"31 Hão de ficar. (Napoleão imperador)","page":168},{"type":"paragraph","text":"32 Não é necessário que possam evitá-lo. (Napoleão imperador)","page":168},{"type":"paragraph","text":"33 Exemplo bem reles! (Napoleão primeiro-cônsul)","page":168},{"type":"paragraph","text":"34 Mas podemos contar com a nossa boa sorte. (Napoleão primeiro-cônsul)","page":168},{"type":"paragraph","text":"35 Sempre há os mais graves de um lado que de outro. (Napoleão primeirocônsul)","page":169},{"type":"paragraph","text":"36 Multiplica as patentes de invenção. (Napoleão primeiro-cônsul)","page":169},{"type":"paragraph","text":"37 Os impostos jamais assustam a cobiça mercantil. (Napoleão primeiro-cônsul)","page":169},{"type":"paragraph","text":"38 Alguém porventura já conseguiu multiplicá-los tanto quanto eu? (Napoleão imperador)","page":169},{"type":"paragraph","text":"39 É, decerto, suficiente mostrar-se nas reuniões teatrais. (Napoleão primeirocônsul)","page":169},{"type":"paragraph","text":"40 O povo gosta muito disso. (Napoleão primeiro-cônsul)","page":169},{"type":"paragraph","text":"41 Nessa matéria, é bom ser moderado. (Napoleão primeiro-cônsul)","page":169},{"type":"heading","lvl":2,"title":"XXII Dos ministros dos príncipes","id":"h_o_pr_ncipe_nicolau_maquiavel_59","page":170},{"type":"paragraph","text":"1 Mas essa sabedoria deve adaptar-se bem às circunstâncias. Às vezes, o mais difamado é o que melhor se recomenda para ministro. (Napoleão primeirocônsul)","page":170},{"type":"paragraph","text":"2 O que teriam pensado de mim se houvesse tomado para ministro e conselheiro vários amigos notórios dos Bourbon, condecorados com suas cruzes de São Luís e cobertos de favores por aqueles que eu substituía e que ambicionavam suplantar-me? (Napoleão imperador)","page":170},{"type":"paragraph","text":"3 Pode-se encontrar tudo isso mais facilmente num indivíduo desacreditado que naquele cuja reputação cheira como bálsamo. (Napoleão primeirocônsul)","page":170},{"type":"paragraph","text":"4 Nisso reside a dificuldade e nisso encontrarão sua ruína. (Napoleão em Elba)","page":170},{"type":"paragraph","text":"5 Não o sabe evitar quem não conhece os homens e se deixa guiar por outrem em suas escolhas. (Napoleão em Elba)","page":170},{"type":"paragraph","text":"6 Veja suas escolhas e julgue. (Napoleão em Elba)","page":170},{"type":"paragraph","text":"7 Dou preferência a esses. (Napoleão primeiro-cônsul)","page":170},{"type":"paragraph","text":"8 Não desprezo esse, desde que dê mostras de grande superioridade intelectual. (Napoleão primeiro-cônsul)","page":170},{"type":"paragraph","text":"9 São uns estúpidos e uns animais. Maquiavel esqueceu os espíritos rotineiros acorrentados a seus métodos. (Napoleão primeiro-cônsul)","page":170},{"type":"paragraph","text":"10 Os quartos perdem-se julgando soberbamente que fazem o melhor. (Napoleão em Elba)","page":170},{"type":"paragraph","text":"11 É tratar de fazer tudo para que não possa pensar em seus interesses senão ocupando-se dos nossos. (Napoleão primeiro-cônsul)","page":170},{"type":"paragraph","text":"12 Não é possível; é querer demais. Porém, se pensar mais em si que em mim, percebê-lo-ei a tempo e adeus. (Napoleão primeiro-cônsul)","page":170},{"type":"paragraph","text":"13 Como sabem ocultar os seus interesses atrás daqueles do meu reinado! (Napoleão imperador)","page":170},{"type":"paragraph","text":"14 Quando não se trata de um ministro como um dos meus, que perderam toda a vergonha. Há mais honradez em meu reino da Itália. (Napoleão imperador)","page":170},{"type":"paragraph","text":"15 Embusteiros! Aprenderam agora a tornar-se importantes em todos os governos, até os mais diversos e opostos. (Napoleão em Elba)","page":170},{"type":"paragraph","text":"16 Bom para outras épocas e para lugares diferentes da França. (Napoleão imperador)","page":170},{"type":"paragraph","text":"17 Quem acreditaria que o lesado fosse eu? Hei de prestar atenção a isso. (Napoleão em Elba)","page":171},{"type":"heading","lvl":2,"title":"XXIII Como evitar os aduladores","id":"h_o_pr_ncipe_nicolau_maquiavel_60","page":172},{"type":"paragraph","text":"1 São necessários. Um príncipe precisa do incenso dele; mas não deve se deixar desvanecer, e isso é difícil. (Napoleão imperador)","page":172},{"type":"paragraph","text":"2 Se não me louvassem com ponderação, o povo me julgaria inferior a um homem vulgar. (Napoleão imperador)","page":172},{"type":"paragraph","text":"3 Concordo com isso. Mas hão de querer dizer-me a verdade? (Napoleão primeiro-cônsul)","page":172},{"type":"paragraph","text":"4 Já é demais permiti-lo a dois ou três. (Napoleão primeiro-cônsul)","page":172},{"type":"paragraph","text":"5 A esses mesmos deve-se também proibir que abram a boca quando não forem interrogados. (Napoleão primeiro-cônsul)","page":172},{"type":"paragraph","text":"6 É muito. (Napoleão primeiro-cônsul)","page":172},{"type":"paragraph","text":"7 Não me descuidei disso e estou me dando muito bem. (Napoleão imperador)","page":172},{"type":"paragraph","text":"8 Isso eu nunca deixo de fazer. (Napoleão imperador)","page":172},{"type":"paragraph","text":"9 Acrescente-se a força das circunstâncias atuais que tornam esses dois perigos ainda mais difíceis de evitar e verei aonde arrastam os aduladores. (Napoleão em Elba)","page":172},{"type":"paragraph","text":"10 Teve boas ideias, sobretudo quando quis ser colega e igual do pontífice até em matéria de religião, e com esse escopo tomou o título de pontifex maximus. Mas não possuía minha perseverança genial. Contentouse em dizer que “se fosse Deus e tivesse dois filhos, o primeiro seria Deus e o segundo rei de França”. Quanto a mim, todo-poderoso na Europa, farei que meu filho, se vier a ser o único, tenha sozinho a soberania da Santa Sé junto com a do Império. (Napoleão imperador)","page":172},{"type":"paragraph","text":"11 Desgraçado de quem o imaginasse. (Napoleão imperador)","page":172},{"type":"paragraph","text":"12 Bela imaginação numa cabeça fraca. (Napoleão imperador)","page":172},{"type":"paragraph","text":"13 Não somos realmente auxiliados senão quando as pessoas por quem desejamos sê-lo sabem que somos invariáveis. (Napoleão imperador)","page":172},{"type":"paragraph","text":"14 Soube fazer perder completamente a vontade disso. (Napoleão imperador)","page":172},{"type":"paragraph","text":"15 Maquiavel é muito exigente. Sei melhor que ele o que convém em minha situação. (Napoleão imperador)","page":172},{"type":"paragraph","text":"16 A opinião está firmada. Sabe-se que posso dizer como Luís XI: “Meu verdadeiro conselho está em minha cabeça”. (Napoleão imperador)","page":172},{"type":"paragraph","text":"17 Sede um Luís XIII em nossos dias e vereis bem cedo que Armand fará como Pepino. (Napoleão imperador)","page":173},{"type":"paragraph","text":"18 Não deve, nesse caso, carregar-se com o peso de outrem. (Napoleão imperador)","page":173},{"type":"paragraph","text":"19 Isso se verifica. (Napoleão em Elba)","page":173},{"type":"paragraph","text":"20 Verdade irrefutável que basta para levar os ministros e cortesãos a afastar do príncipe toda leitura de Maquiavel. (Napoleão em Elba)","page":173},{"type":"paragraph","text":"21 Onde está a cabeça reinante capaz disso? Numa ilhota do Mediterrâneo. (Napoleão em Elba)","page":173},{"type":"heading","lvl":2,"title":"XXIV Por qual motivo os príncipes da Itália perderam seus Estados","id":"h_o_pr_ncipe_nicolau_maquiavel_61","page":174},{"type":"paragraph","text":"1 É o capítulo mais curioso. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"2 Eu mesmo fiz a experiência. (Napoleão imperador)","page":174},{"type":"paragraph","text":"3 O apego que me tem a maioria de seus nobres prova que já quase os esqueceram. (Napoleão imperador)","page":174},{"type":"paragraph","text":"4 Especialmente quando são emigrados a quem se restituíram os seus bens ou fidalgotes pobres aos quais se deram riquezas. E também os ricos me agradecem por tê-los ajudado a aumentar seus tesouros. (Napoleão imperador)","page":174},{"type":"paragraph","text":"5 Lançar-me-ão ao rosto uma dessas faltas para justificar o fato de me haverem virado as costas. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"6 Estou fazendo essa feliz experiência. (Napoleão imperador)","page":174},{"type":"paragraph","text":"7 Não me falta nenhuma dessas glórias. (Napoleão imperador)","page":174},{"type":"paragraph","text":"8 Isso me interessa. (Napoleão imperador)","page":174},{"type":"paragraph","text":"9 Ter a inimizade de uma só das partes deve bastar. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"10 Isso não é possível com os que o rodeiam. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"11 Sim, mas no caso de que possa dispor deles... (Napoleão em Elba)","page":174},{"type":"paragraph","text":"12 Do mesmo modo, assumirei melhor atitude no que concerne à confederação, caso ela se renove. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"13 Ainda que aceitasse a cessão já feita dos países por mim conquistados e me restringisse às fronteiras estabelecidas, continuaria sempre a ser imperador dos franceses. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"14 Vejam como isso acontece: os favoritos pavoneiam-se em meio às suas manifestações e receariam digerir mal se dessem guarida à menor inquietação. Ainda supondo que tornassem a me ver, não quereriam acreditar na possibilidade do meu regresso. Sua natural disposição presta-se muito para meus estratagemas narcóticos. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"15 Não terão mais ensejo para fazê-lo. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"16 Responderei como um príncipe que se tornou moderado, humano, sábio. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"17 Terão eles outra? É possível que os desamparem ao me verem; e, por outro lado, resguardar-me-ei deles. (Napoleão em Elba)","page":174},{"type":"paragraph","text":"18 Nunca fiz conta senão destas... e tê-las-ei! (Napoleão em Elba)","page":175},{"type":"heading","lvl":2,"title":"XXV De quanto a sorte influi nas coisas humanas e de como lhe opor resistência","id":"h_o_pr_ncipe_nicolau_maquiavel_62","page":176},{"type":"paragraph","text":"1 Sistema dos preguiçosos e dos fracos. Com engenho e atividade podemos dominar a sorte mais adversa. (Napoleão em Elba)","page":176},{"type":"paragraph","text":"2 Por acaso ele as teria visto maiores e mais numerosas que as que engendrei e que posso ainda produzir? (Napoleão em Elba)","page":176},{"type":"paragraph","text":"3 Santo Agostinho não falou melhor acerca do livre arbítrio. O meu domou a Europa e a Natureza. (Napoleão imperador)","page":176},{"type":"paragraph","text":"4 Minha sorte sou eu mesmo. (Napoleão imperador)","page":176},{"type":"paragraph","text":"5 Minha perícia na matéria não lhes deixou margem para fazê-los. (Napoleão imperador)","page":176},{"type":"paragraph","text":"6 Não há de ser minha estrela que mingue até esse ponto. (Napoleão imperador)","page":176},{"type":"paragraph","text":"7 Como seria a dos meus inimigos. (Napoleão imperador)","page":176},{"type":"paragraph","text":"8 Sê-lo-á. (Napoleão general)","page":176},{"type":"paragraph","text":"9 Verás muitas coisas. (Napoleão general)","page":176},{"type":"paragraph","text":"10 Se hoje me visses lá e conhecesses meus planos... (Napoleão general)","page":176},{"type":"paragraph","text":"11 Apesar da sua discrição, adivinho o seu pensamento e aproveitá-lo-ei. (Napoleão general)","page":176},{"type":"paragraph","text":"12 Pobres formalistas! (Napoleão imperador)","page":176},{"type":"paragraph","text":"13 É mister adaptarmo-nos às suas variações sem confiar inteiramente nelas, embora afetando estarmos seguros do êxito. (Napoleão primeiro-cônsul)","page":176},{"type":"paragraph","text":"14 Nunca a minha boa sorte esteve mais em desacordo com a minha situação. (Napoleão em Elba)","page":176},{"type":"paragraph","text":"15 Contanto que sigamos as nossas inclinações e não sejamos intempestivos. (Napoleão primeiro-cônsul)","page":176},{"type":"paragraph","text":"16 Variar conforme as circunstâncias e as épocas sem nada perder do próprio vigor é a coisa mais difícil do mundo e a que mais perseverança requer. Verse-á em breve a força e a flexibilidade da minha. (Napoleão em Elba)","page":176},{"type":"paragraph","text":"17 É difícil, mas hei de consegui-lo. (Napoleão em Elba)","page":176},{"type":"paragraph","text":"18 Mostrar-se bom durante o reinado só porque se mostrou antes, quando pretendia chegar ao trono, é o pior dos métodos. (Napoleão em Elba)","page":176},{"type":"paragraph","text":"19 Espero fazê-lo com absoluta confiança em minha boa sorte. (Napoleão em Elba)","page":177},{"type":"paragraph","text":"20 Felizmente, já não há papas como esse, que atirou ao Tibre as chaves de São Pedro para utilizar somente a espada de São Paulo. (Napoleão general)","page":177},{"type":"paragraph","text":"21 Servi-me dessa tática não por ser arrebatado como ele, mas por cálculo e de acordo com a oportunidade. (Napoleão imperador)","page":177},{"type":"paragraph","text":"22 Inventarei algo semelhante no que diz respeito aos aliados, conforme o curso de sua política. (Napoleão em Elba)","page":177},{"type":"paragraph","text":"23 As imprudências são, muitas vezes, necessárias; mas convém calculá-las. (Napoleão em Elba)","page":177},{"type":"paragraph","text":"24 Quantos reis, não pertencentes ao clero, procedem com essa cautela vagarosa e tola! (Napoleão em Elba)","page":177},{"type":"paragraph","text":"25 Se não puder me esquivar de tudo isso, autorizo a que me julguem indigno de reinar. (Napoleão em Elba)","page":177},{"type":"paragraph","text":"26 Contudo, é maravilhoso poder, durante dez anos, continuar com bom resultado e com o mesmo método. Maquiavel deveria ter dito: Júlio II sabia distrair com pactos de amizade as potências que desejava surpreender. (Napoleão primeiro-cônsul)","page":177},{"type":"paragraph","text":"27 Quando esse procedimento nos traz sempre bons frutos e está de acordo com a nossa índole, temos motivos fortes para não desprezar, embora misturandolhe um pouco de estúpida moderação diplomática. (Napoleão imperador)","page":177},{"type":"paragraph","text":"28 Realmente. As repetidas experiências feitas afastam qualquer dúvida a esse respeito. (Napoleão em Elba)","page":177},{"type":"paragraph","text":"29 Comprovei-o muitas vezes, e se fosse menos jovem, já não contaria com ela. Devo apressar-me. (Napoleão em Elba)","page":177},{"type":"heading","lvl":2,"title":"XXVI Exortação à tomada da Itália para libertá-la das mãos dos bárbaros","id":"h_o_pr_ncipe_nicolau_maquiavel_63","page":178},{"type":"paragraph","text":"1 Maquiavel também falava como romano e pensava sempre nos franceses. Para mim, ao contrário, os bárbaros que devem ser expulsos da Itália são a Áustria, a Espanha, o papa etc. etc. (Napoleão general)","page":178},{"type":"paragraph","text":"2 Projeto esplêndido cuja execução estava reservada a mim. Com italianos efeminados como os de hoje, teria sido impossível; mas, sendo eu italiano, posso fazê-lo com franceses sob minhas ordens, com quem os italianos aprenderão o valor militar. (Napoleão general).","page":178},{"type":"paragraph","text":"3 Os tempos atuais são ainda muito mais propícios, visto que ao ser ali repelida a Revolução, operam-se profundos abalos políticos e uma grande agitação nos espíritos. (Napoleão general)","page":178},{"type":"paragraph","text":"4 Convém tornar a colocá-la na mesma situação para restabelecê-la depois sob um único cetro. (Napoleão cônsul)","page":178},{"type":"paragraph","text":"5 Não tanto como eu, por certo. (Napoleão general)","page":178},{"type":"paragraph","text":"6 Eis-me aqui. Mas, antes que seja para mim reservada, é mister que eu lhe cauterize as feridas com ferro e fogo. (Napoleão general)","page":178},{"type":"paragraph","text":"7 A mando desses mesmos bárbaros ouvirei os seus rogos. (Napoleão general)","page":178},{"type":"paragraph","text":"8 Ter-se-ia realizado se eu tivesse sido parte dela. (Napoleão general)","page":178},{"type":"paragraph","text":"9 Para empreendê-la, sim; porém, para realizá-la, falta-lhe capacidade para fazer mais do que fez. (Napoleão general)","page":178},{"type":"paragraph","text":"10 Mas para bem imitá-los, é preciso ter a força deles. (Napoleão general)","page":178},{"type":"paragraph","text":"11 Meu raciocínio: há homens e homens. (Napoleão general)","page":178},{"type":"paragraph","text":"12 Há uma boa dose de verdade nisso tudo; porém, o que vejo com maior clareza é o ardor extremo que Maquiavel emprega para pleitear tal solução. (Napoleão general)","page":178},{"type":"paragraph","text":"13 Outros tantos milagres que se renovaram a meu favor de modo mais positivo que a favor de Lourenço. (Napoleão primeiro-cônsul)","page":178},{"type":"paragraph","text":"14 Assim há de ser. (Napoleão primeiro-cônsul)","page":178},{"type":"paragraph","text":"15 Vê-se que Maquiavel queria ter o seu quinhão. Concedo-lhe porque me tem sido útil com as suas advertências. (Napoleão imperador)","page":178},{"type":"paragraph","text":"16 Com as minhas, tão gloriosamente experimentadas na França e que eles experimentarão por sua vez, o triunfo é inevitável. (Napoleão primeirocônsul)","page":178},{"type":"paragraph","text":"17 A tática que emprega é invenção minha, e diante de seus efeitos renderam-se todos os poderosos da Europa. (Napoleão imperador)","page":179},{"type":"paragraph","text":"18 Isso é sempre um motivo de alento. (Napoleão general)","page":179},{"type":"paragraph","text":"19 Somente ao século XVIII estava reservado produzir tal homem. (Napoleão general)","page":179},{"type":"paragraph","text":"20 O que não farei quando dispuser, como seu príncipe, de um exército italiano incorporado em outro francês! (Napoleão general)","page":179},{"type":"paragraph","text":"21 Maquiavel fala apenas em se defender dos estrangeiros. Eu aspiro a conquistá-los e torná-los súditos meus. (Napoleão general)","page":179},{"type":"paragraph","text":"22 Conceito ridículo que a pólvora fez esquecer. Esses pretensos mestres da arte militar não passavam de criancinhas. (Napoleão general)","page":179},{"type":"paragraph","text":"23 Já aprontei tudo. (Napoleão general)","page":179},{"type":"paragraph","text":"24 Minha tática, cujos segredos os meus inimigos ignoram, me proporcionará, de forma muito superior, aquela que teria sido possível a Lourenço. (Napoleão general)","page":179},{"type":"paragraph","text":"25 A Itália finalmente viu-o em mim. (Napoleão imperador)","page":179},{"type":"paragraph","text":"26 Todas essas predições se verificaram. Até os habitantes da Cidade Eterna se vangloriam de estar sob o meu cetro. (Napoleão imperador)","page":179},{"type":"paragraph","text":"27 Poderá enobrecer-se ainda mais se isso não envolver riscos para mim. (Napoleão imperador)","page":179},{"type":"paragraph","text":"28 Hoje, graças a mim, revive quase por completo. Todavia, não deixarei que se reúnam em uma só nação, porque isso equivaleria à destruição da França, Alemanha e da Europa inteira. (Napoleão imperador)","page":179},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p180_380.jpeg","page":180,"width":300,"height":441},{"type":"paragraph","text":"A privataria tucana","page":181},{"type":"paragraph","text":"Jr, Amaury Ribeiro","page":181},{"type":"paragraph","text":"344 páginas","page":181},{"type":"paragraph","text":"Prepare-se, leitor, porque este, infelizmente, não é um livro qualquer. A PRIVATARIA TUCANA nos traz, de maneira chocante e até decepcionante, a dura realidade dos bastidores da política e do empresariado brasileiro, em conluio para roubar dinheiro público. Faz uma denúncia vigorosa do que foi a chamada Era das Privatizações, instaurada pelo governo de Fernando Henrique Cardoso e por seu então Ministro do Planejamento, José Serra. Nomes imprevistos, até agora blindados pela aura da honestidade, surgirão manchados pela imprevista descoberta de seus malfeitos. Amaury Ribeiro Jr. faz um trabalho investigativo que começa de maneira assustadora, quando leva um tiro ao fazer reportagem sobre o narcotráfico e assassinato de adolescentes, na periferia de Brasília. Depois do trauma sofrido, refugia-se em Minas e começa a investigar uma rede de espionagem estimulada pelo ex-governador paulista José Serra, para desacreditar seu rival no PSDB, o ex-governador mineiro Aécio Neves. Ao puxar o fi o da meada, mergulha num novelo de proporções espantosas.","page":181},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p182_388.jpeg","page":182,"width":300,"height":455},{"type":"paragraph","text":"Sonho Estrelado","page":183},{"type":"paragraph","text":"Baiano, José Ubaldo","page":183},{"type":"paragraph","text":"148 páginas","page":183},{"type":"paragraph","text":"Este livro é um hino à vida, ao trabalho, à luta para se superar e vencer os obstáculos da batalha diária rumo ao autoconhecimento e ao sucesso profissional. José Ubaldo Tuca Baiano, um dos maiores homens de vendas do Brasil, narra sua infância pobre no interior da Bahia, a ajuda que teve de um parente melhor de vida, as lições que aprendeu, suas aventuras no Caminho de Santiago de Compostela, na Espanha, e o valor da amizade e da honestidade para seguir em frente e tornar-se um vitorioso. Seu relato, simples e acessível a qualquer um, mostra como venceu na vida e como - com a criação de um círculo de grandes amizades que sempre o respeitaram - chegou a ajudar dois rapazes simples e corretos que há 20 anos o procuraram para vender sabão e carne e se transformaram em proprietários da maior empresa privada brasileira, o Grupo JBS, dono da Friboi. Trata-se de um relato admirável, para qualquer leitor que valorize a vida e o trabalho.","page":183},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p184_393.jpeg","page":184,"width":300,"height":466},{"type":"paragraph","text":"Sangue azul","page":185},{"type":"paragraph","text":"Gudel, Leornado","page":185},{"type":"paragraph","text":"332 páginas","page":185},{"type":"paragraph","text":"Mais violento que o filme \"Tropa de Elite\". Mais polêmico que o livro \"A elite da tropa\".Mais revelador que \"Rota 66\". Mais impressionante que qualquer livro, filme ou documento que você tenha lido ou visto sobre o tráfico de drogas e a corrupção policial e política no Rio ou em qualquer lugar. Incomparável. Revoltante. Absurdamente real. Um depoimento chocante e arrasador!","page":185},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p186_398.jpeg","page":186,"width":300,"height":460},{"type":"paragraph","text":"O Piloto de Hitler","page":187},{"type":"paragraph","text":"Sweeting, C.G.","page":187},{"type":"paragraph","text":"440 páginas","page":187},{"type":"paragraph","text":"Um livro que faltava sobre as duas guerras mundiais e o inferno do nazismo. C. G. Sweeting resgata nas páginas deste O piloto de Hitler o testemunho privilegiado de um homem fiel ao ditador alemão mesmo depois dos dez anos de sofrimento em masmorras e campos de prisioneiros da União Soviética. Hans Baur era a sombra de Hitler no ar. Amava o Führer e os aviões. Tudo sobre os horrores da guerra está aqui.","page":187},{"type":"image","src":"_sistema/biblioteca_data/images/o_pr_ncipe_nicolau_maquiavel/img_p188_403.jpeg","page":188,"width":300,"height":461},{"type":"paragraph","text":"Política","page":189},{"type":"paragraph","text":"Moraes, Míriam","page":189},{"type":"paragraph","text":"172 páginas","page":189},{"type":"paragraph","text":"Não fique por fora dos temas que agitam o país. Veja aqui o que você precisa saber para entender,opinar e debater política e atualidades. O pior analfabeto é o analfabeto político. Ele não ouve, não fala, nem participa dos acontecimentos políticos. Ele não sabe que o custo de vida, o preço do feijão, do peixe, da farinha, do aluguel, do sapato e do remédio dependem das decisões políticas. O analfabeto político é tão burro que se orgulha e estufa o peito dizendo que odeia a política. Não sabe o imbecil que, da sua ignorância política, nasce a prostituta, o menor abandonado, e o pior de todos os bandidos, que é o político vigarista, pilantra, corrupto e lacaio dos exploradores do povo. Bertolt Brech","page":189}];
